function myloMdLink(label, url){
  const name = String(label || 'Untitled').replace(/[\[\]]/g, '').trim() || 'Untitled';
  const href = String(url || '').trim();
  if (!/^https?:\/\//i.test(href)) return name;
  return `[${name}](${href})`;
}

/** Escape text, then turn [label](https://…) into clickable links. */
function myloRichText(text){
  return esc(text || '').replace(
    /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g,
    '<a class="mylo-inline-link" href="$2" target="_blank" rel="noopener">$1</a>'
  );
}
