function refreshTodayAnchor(){
  const n = new Date(); n.setHours(0,0,0,0);
  const next = iso(n);
  if (next === TODAY_ISO) return false;
  TODAY = n;
  TODAY_ISO = next;
  selectedDay = TODAY_ISO;
  calCursor = new Date(TODAY.getFullYear(), TODAY.getMonth(), 1);
  return true;
}
/* Two things can quietly invalidate what is on screen while the app just sits
   there: the date rolling over, and the grace hour running out at 01:00. Both
   have to force a repaint, or yesterday's to-dos keep looking tickable after
   they have settled. `inTodoGrace` is defined further down with the rest of
   the to-do rules; this only runs on a timer, long after load. */
let _graceWasOpen = null;
function dayStateChanged(){
  const rolled = refreshTodayAnchor();
  const open = inTodoGrace();
  const graceFlipped = _graceWasOpen !== null && open !== _graceWasOpen;
  _graceWasOpen = open;
  return rolled || graceFlipped;
}
