/** Nothing in the app had a timeout, so one hung request froze it until reload. */
const BUSY_MAX_MS = 45000;
function busyLocked(){
  if (!busy) return false;
  if (busySince && Date.now() - busySince > BUSY_MAX_MS){ busy = false; busySince = 0; return false; }
  return true;
}
function markBusy(on){ busy = !!on; busySince = on ? Date.now() : 0; }
/** Reject instead of hanging forever when a call never settles. */
function withTimeout(promise, ms = 30000, label = 'request'){
  let timer;
  return Promise.race([
    Promise.resolve(promise).finally(() => clearTimeout(timer)),
    new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} timed out - check your connection and try again`)), ms);
    })
  ]);
}
