function unlockAudio(){
  try{
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
  }catch{}
}
function playMessageSound(kind='recv'){
  try{
    unlockAudio();
    if (!audioCtx) return;
    const ctx = audioCtx;
    const now = ctx.currentTime;
    if (kind === 'send'){
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(920, now);
      o.frequency.exponentialRampToValueAtTime(420, now + 0.09);
      g.gain.setValueAtTime(0.0001, now);
      g.gain.exponentialRampToValueAtTime(0.11, now + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, now + 0.14);
      o.connect(g); g.connect(ctx.destination);
      o.start(now); o.stop(now + 0.16);
      return;
    }
    // Soft iPhone-like chime (two tones)
    [[1046.5, 0], [1318.5, 0.08]].forEach(([freq, delay]) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'triangle';
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, now + delay);
      g.gain.exponentialRampToValueAtTime(0.16, now + delay + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, now + delay + 0.32);
      o.connect(g); g.connect(ctx.destination);
      o.start(now + delay); o.stop(now + delay + 0.34);
    });
  }catch{}
}
function isChatVisible(){
  const mobile = window.matchMedia('(max-width:900px)').matches;
  if (mobile) return !!$('#m-chat')?.classList.contains('active');
  return currentDeskView() === 'chat';
}
/* The chat markup is rendered into BOTH #view (desktop) and #m-chat (mobile),
   which duplicates every id. Always resolve chat controls against the surface
   that is actually visible so mobile taps hit the right input/scroll. */
function chatSurface(){
  const mobile = window.matchMedia('(max-width:900px)').matches;
  const el = mobile ? document.getElementById('m-chat') : document.getElementById('view');
  return el || document;
}
// The Mylo thread composer is rendered into BOTH #view (desktop) and #m-chat (mobile),
// so #mylo-chat-in exists twice. Always read the input on the VISIBLE surface, else the
// send button on mobile grabs the hidden desktop copy (empty) and appears to do nothing.
function myloInput(){
  return chatSurface().querySelector('#mylo-chat-in') || $('#mylo-chat-in') || $('#mylo-in');
}
/** Account/profile markup is dual-rendered into #view (desk) and #m-you (mobile). */
