function currentDeskView(){
  return state.deskView || ($('.nav-item.is-active')||{}).dataset?.view || 'today';
}
function syncDeskNav(){
  const view = currentDeskView();
  $$('.nav-item[data-view]').forEach(n => n.classList.toggle('is-active', n.dataset.view === view));
  $$('.nav-sub-item').forEach(n => {
    const on = view === 'goals' && n.dataset.goalScope === (state.goalScope || 'day');
    n.classList.toggle('is-active', on);
  });
  const parent = $('[data-nav-toggle="goals"]');
  if (parent) parent.classList.toggle('is-section-on', view === 'goals');
}
function setDeskView(view, opts = {}){
  // Desktop Today nav also snaps back to the real today page.
  if (view === 'today' && state.todayFocus){
    state.todayFocus = null;
    state.todayFilter = 'todo';
  }
  state.deskView = view;
  if (opts.goalScope) state.goalScope = opts.goalScope;
  if (view === 'goals' && !state.goalScope) state.goalScope = 'day';
  syncDeskNav();
  if (view === 'chat') clearUnread();
  if (view === 'calendar') scheduleGcalSync(400);
  saveNav({ deskView: view, screen: view === 'categories' ? 'cats' : view, goalScope: state.goalScope });
  renderAll();
}
function setUnread(n){
  state.unread = Math.max(0, n);
  sessionStorage.setItem('mylo:unread', String(state.unread));
  updateChatBadge();
}
function clearUnread(){
  setUnread(0);
}
function bumpUnread(){
  setUnread((state.unread || 0) + 1);
}
/* What is unread is a fact about the log, not something the client has to
   remember: everything in a chat after my own read mark, written by someone
   else. Before this, the count only ever went up live and started from zero on
   every load, so a message that arrived while the app was closed never showed
   a badge at all. Runs whenever the caches or the marks change. */
function deriveUnread(){
  const mid = me()?.id;
  if (!mid) return;
  const rooms = state.rooms || [];
  const inThread = (state.chatView === 'thread' && isChatVisible()) ? activeChat()?.id : null;
  const next = {};
  rooms.forEach(r => {
    if (!(r.kind === 'dm' || r.kind === 'group') || r.archived_at) return;
    const id = r.id;
    if (id === inThread || state._readPending?.[id]) { next[id] = 0; return; }
    const seen = new Set();
    const rows = [];
    [state.msgCacheByRoom?.[id], state.liveRowsByRoom?.[id], (activeChat()?.id === id ? state.messages : null)]
      .forEach(arr => (arr || []).forEach(m => { if (m && !seen.has(m.id)){ seen.add(m.id); rows.push(m); } }));
    if (!rows.length) return;
    rows.sort(byTimeAsc);
    const mark = state.reads?.[id]?.[mid];
    let from = 0;
    if (mark){
      const at = rows.findIndex(m => String(m.id) === String(mark.ref));
      from = at >= 0 ? at + 1 : rows.findIndex(m => new Date(m.created_at) > new Date(mark.at));
      if (from < 0) from = rows.length;
    }
    let n = 0;
    for (let i = from; i < rows.length; i++){
      const m = rows[i];
      if (m.from_id === mid || String(m.id).startsWith('tmp-')) continue;
      if (isThemeChangeMsg(m) || msgHidden(m)) continue;
      n++;
    }
    next[id] = n;
  });
  state.unreadByRoom = next;
  setUnread(Object.values(next).reduce((a, b) => a + b, 0));
}
function updateChatBadge(){
  const fromRooms = Object.values(state.unreadByRoom || {}).reduce((a, b) => a + (Number(b) || 0), 0);
  const n = Math.max(state.unread || 0, fromRooms);
  state.unread = n;
  const label = n > 9 ? '9+' : String(n);
  ['#desk-chat-badge', '#m-chat-badge'].forEach(sel => {
    const el = $(sel);
    if (!el) return;
    el.textContent = label;
    el.classList.toggle('hidden', n <= 0);
  });
}
function onIncomingMessage(row){
  const mine = me() && row.from_id === me().id;
  // Keep the cross-room cache current — notifications and win counts read from it,
  // and they must not depend on which thread happens to be open.
  if (row?.room_id){
    state.msgCacheByRoom = state.msgCacheByRoom || {};
    const cache = state.msgCacheByRoom[row.room_id];
    if (Array.isArray(cache) && !cache.some(m => m.id === row.id)) cache.push(row);
    /* A room you have not opened yet has no cache, and this used to throw the row
       away — so a game someone started, or the move they just made, never reached
       the board or the notification list until you went into that chat and it
       reloaded. Live rows are kept on their own, whatever the cache is doing. */
    const live = (state.liveRowsByRoom = state.liveRowsByRoom || {});
    const list = (live[row.room_id] = live[row.room_id] || []);
    if (!list.some(m => m.id === row.id)){
      list.push(row);
      if (list.length > 200) list.splice(0, list.length - 200);
    }
  }
  // A game move is just another row - refresh the open board.
  try{
    const gp = payloadOf(row);
    if (isBoardGameMsg(row) && $('#game-overlay')?.classList.contains('on')
        && gp.gameId === state._gameFocus){
      state._gameSel = null;
      setTimeout(renderGameOverlay, 0);
    }
  }catch(_){}
  if (row?.room_id){
    state.lastMsgByRoom[row.room_id] = {
      id: row.id,
      room_id: row.room_id,
      body: row.body,
      kind: row.kind,
      from_id: row.from_id,
      created_at: row.created_at,
      payload: row.payload
    };
  }
  if (isThemeChangeMsg(row)){
    const theme = payloadOf(row).theme;
    if (THEME_IDS.has(theme) && row.room_id){
      persistRoomChatTheme(row.room_id, theme);
      if (activeChat()?.id === row.room_id) applyChatTheme();
    }
  }
  if (mine){
    refreshChatListIfNeeded();
    return;
  }
  if (!isThemeChangeMsg(row)) playMessageSound('recv');
  const inThisThread = activeChat()?.id === row.room_id && isChatVisible() && state.chatView === 'thread';
  if (!inThisThread && !isThemeChangeMsg(row)){
    state.unreadByRoom[row.room_id] = (state.unreadByRoom[row.room_id] || 0) + 1;
    if (msgMentionsMe(row)) state.mentionByRoom[row.room_id] = true;
    bumpUnread();
  }
  refreshChatListIfNeeded();
  pumpAlerts();
}
function refreshChatListIfNeeded(){
  if (state.chatView !== 'list' && state.chatView !== 'thread') return;
  const onChat = (($('.m-screen.active')||{}).id === 'm-chat') || currentDeskView() === 'chat';
  if (!onChat) {
    updateChatBadge();
    return;
  }
  if (state.chatView === 'list') renderChatOnly();
  else updateChatBadge();
}
function isThemeChangeMsg(m){
  return payloadOf(m)?.type === 'theme_change';
}
function msgPreviewText(m){
  if (!m) return 'No messages yet';
  if (msgDeletedForAll(m.id)) return 'Message deleted';
  if (payloadOf(m).image) return 'Photo';
  if (payloadOf(m).voice) return 'Voice note';
  if (payloadOf(m).transfer) return FEATURES.wallet ? '$MYL sent' : 'Transfer';
  if (payloadOf(m).mylo_reply) return 'Mylo replied';
  if (isThemeChangeMsg(m)) return 'Changed the theme';
  const kind = m.kind || 'text';
  if (kind === 'text') return m.body || 'Message';
  if (kind === 'sticker') return 'Sticker';
  if (kind === 'mood') return 'Mood';
  if (kind === 'cheer') return 'Cheer';
  if (kind === 'spin') return 'Spin';
  if (kind === 'chance' || isChanceRpsMsg(m) || isBoardGameMsg(m)){
    const g = payloadOf(m).game;
    if (g === 'chess') return 'Chess';
    if (g === 'eights') return 'Eights';
    if (g === 'rush') return 'Rush';
    return 'Chance';
  }
  if (kind === 'task_card') return 'Today';
  if (kind === 'poll') return 'Poll';
  if (kind === 'note') return 'Note';
  return m.body || 'Message';
}
function fmtMsgClock(isoStr){
  if (!isoStr) return '';
  const d = new Date(isoStr);
  if (Number.isNaN(d.getTime())) return '';
  const now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  if (sameDay) return displayTime(`${pad(d.getHours())}:${pad(d.getMinutes())}`);
  const yest = new Date(now); yest.setDate(now.getDate()-1);
  if (d.toDateString() === yest.toDateString()) return 'Yesterday';
  return `${pad(d.getDate())}/${pad(d.getMonth()+1)}`;
}
function chatRoomIds(){
  const spaceId = room()?.id;
  const allowGroup = canUseGroupChat();
  return state.rooms
    .filter(r => {
      if (r.archived_at) return false;
      if (!(r.kind === 'dm' || r.kind === 'group')) return false;
      if (r.kind === 'group' && !allowGroup) return false;
      return !spaceId || r.parent_room_id === spaceId || r.id === room()?.group_room_id;
    })
    .map(r => r.id);
}

function setAuthCookie(profile){
  if (!profile) return;
  const maxAge = 60 * 60 * 24 * 180;
  document.cookie = `mylo_uid=${encodeURIComponent(profile.id)}; Max-Age=${maxAge}; Path=/; SameSite=Lax`;
  document.cookie = `mylo_user=${encodeURIComponent(profile.username)}; Max-Age=${maxAge}; Path=/; SameSite=Lax`;
}
function clearAuthCookie(){
  document.cookie = 'mylo_uid=; Max-Age=0; Path=/; SameSite=Lax';
  document.cookie = 'mylo_user=; Max-Age=0; Path=/; SameSite=Lax';
}
function cookieAccepted(){
  try{
    if (localStorage.getItem('mylo_cookies') === '1' || localStorage.getItem('sephora_cookies') === '1') return true;
  }catch{}
  return document.cookie.split(';').some(c => {
    const t = c.trim();
    return t.startsWith('mylo_cookies=1') || t.startsWith('sephora_cookies=1');
  });
}
function acceptCookies(){
  try{ localStorage.setItem('mylo_cookies', '1'); }catch{}
  document.cookie = 'mylo_cookies=1; Max-Age=' + (60*60*24*365) + '; Path=/; SameSite=Lax';
  $('#cookie-bar')?.classList.add('hidden');
}
function dismissCookieBar(){
  $('#cookie-bar')?.classList.add('hidden');
}
function showCookieBar(){
  // Keep off the auth gate — it covers Sign in / Create account on short screens
  const onAuth = !$('#auth')?.classList.contains('hidden');
  if (!cookieAccepted() && !onAuth) $('#cookie-bar')?.classList.remove('hidden');
  else $('#cookie-bar')?.classList.add('hidden');
}

/* Two channels, deliberately.

   `notify` is the only one that puts a black pill on screen, and it is reserved for
   things you would be annoyed to miss: something failed, or money moved. `toast` is
   the old chatty confirmation ("Goal added", "joined the room") — those are now
   swallowed, because narrating every successful action is noise. Keeping the name
   means no call site had to be rewritten to go quiet. */
function notify(msg){
  const t = $('#toast');
  if (!t || !msg) return;
  t.textContent = msg;
  t.classList.add('on');
  clearTimeout(t._x);
  t._x = setTimeout(() => t.classList.remove('on'), 2200);
}
/* Silencing every toast went too far: most of them sit on a `return` and are the
   only explanation for why an action did NOT happen — an illegal Scrabble word, a
   card that doesn't match, a field left blank. Those have to speak. What the user
   actually objected to was the chatter after something obviously worked, so that
   is what gets swallowed here, by pattern. */
const QUIET_TOAST = /^(joined|welcome|added|saved|updated|created|removed|copied|done|sent|shared|deleted|signed|linked|connected|disconnected|photo removed|cover updated|group photo updated|room created|goal added|shared goal added|milestone created|system added|move sent|chance sent|reminders? (on|off)|telegram|whatsapp|synced|demo:|\+\d)/i;
function toast(msg){
  const m = String(msg || '');
  if (!m) return;
  if (QUIET_TOAST.test(m.trim())) return;   // pure confirmation — stays quiet
  notify(m);
}
function errMsg(e){
  const m = e?.message || String(e || 'Something went wrong');
  if (/messages_kind_check/i.test(m) || (/violates check constraint/i.test(m) && /messages/i.test(m))){
    return 'Game couldn’t save — refresh and try again';
  }
  if (/invalid code/i.test(m)) return 'Code must be 6–12 letters or numbers';
  if (/already taken/i.test(m)) return 'That code is already taken';
  if (/join request sent/i.test(m)) return 'Request sent — wait for an admin to allow you in';
  if (/rate limit exceeded/i.test(m)) return 'Too many tries — wait a few minutes';
  if (/already a member/i.test(m)) return 'You are already in that room';
  if (/already in a room/i.test(m)) return 'You are already in a room';
  if (/room is full/i.test(m)) return 'Room is full';
  if (/room not found/i.test(m)) return 'Room not found';
  if (/not authorized/i.test(m)) return 'Not allowed';
  if (/room_limit/i.test(m)) return FEATURES.plans
    ? 'Room limit reached — upgrade in You → Plan'
    : 'You have reached your room limit — you can still join one with a code';
  if (/Google Calendar requires Pro/i.test(m)) return FEATURES.plans ? 'Google Calendar needs Pro or Pod' : 'Google Calendar is not available yet';
  if (/Notion requires Pro/i.test(m)) return FEATURES.plans ? 'Notion needs Pro or Pod' : 'Notion is not available yet';
  if (/Notion is not configured/i.test(m)) return 'Notion isn’t configured yet — add Client ID/Secret';
  if (/not configured yet/i.test(m)) return 'Integration isn’t configured yet — add Client ID/Secret';
  if (/Share at least one Notion page/i.test(m)) return 'In Notion, open a page → ••• → Connect to → Mylo, then try again.';
  if (/Connect Notion first/i.test(m)) return 'Connect Notion first — You → Integrations.';
  if (/invalid username/i.test(m)) return 'Username taken or invalid';
  if (/User already registered/i.test(m)) return 'Username taken';
  if (/Email not confirmed/i.test(m)) return 'Confirm email is on — turn it off in Supabase Auth settings';
  if (/Invalid login/i.test(m)) return 'Wrong username or password';
  if (/Edge Function returned a non-2xx/i.test(m)) return 'Notion request failed — try Connect Notion again, and share a page with Mylo.';
  return m;
}

async function invokeFunction(name, body = {}){
  const { data, error } = await withTimeout(
    sb.functions.invoke(name, { body }), 30000, name
  );
  if (!error){
    if (data?.error) throw new Error(String(data.error));
    return data || {};
  }
  // Prefer the JSON body from the edge function over the generic non-2xx message
  try{
    const ctx = error.context;
    if (ctx && typeof ctx.json === 'function'){
      const payload = await ctx.json();
      if (payload?.error) throw new Error(String(payload.error));
      if (typeof payload?.message === 'string' && payload.message) throw new Error(payload.message);
    } else if (ctx && typeof ctx.text === 'function'){
      const raw = await ctx.text();
      try{
        const payload = JSON.parse(raw);
        if (payload?.error) throw new Error(String(payload.error));
      }catch(parseErr){
        if (parseErr?.message && !/JSON|Unexpected/i.test(parseErr.message)) throw parseErr;
      }
    }
  }catch(inner){
    if (inner?.message && !/Edge Function returned a non-2xx/i.test(inner.message)) throw inner;
  }
  throw error;
}

