async function startCheckout(sku){
  if (!FEATURES.plans) return;
  if (!BILLING_SKUS[sku]){ toast('Unknown product'); return; }
  if (!me()){ toast('Sign in first'); return; }
  if (!canUseDemoTopUp()){
    toast('Payments coming soon — demo top-up is owner-only for now');
    return;
  }
  if (busyLocked()) return;
  markBusy(true);
  try{
    // Demo only — no Paystack until API keys are configured
    const { data, error } = await sb.rpc('demo_apply_purchase', { p_sku: sku });
    if (error) throw error;
    if (data?.error) throw new Error(data.error);
    await refreshBilling();
    await refreshGcalStatus();
    await refreshNotionStatus();
    await refreshTelegramStatus();
    await refreshWhatsappStatus();
    const label = BILLING_SKUS[sku]?.label || sku;
    toast(`Demo: ${label} applied`);
    renderAll();
  }catch(e){
    notify(errMsg(e));
  }finally{ markBusy(false); }
}

