function googleEventsOn(dateIso){
  const list = state.gcalEvents || [];
  if (!dateIso || !list.length) return [];
  // Only under All / Mine filters
  if (calFilter && calFilter.startsWith('user:')) return [];
  return list.filter(ev => {
    if (!ev.starts_at) return false;
    const d = String(ev.starts_at).slice(0, 10);
    return d === dateIso;
  });
}

function gcalEventTimeLabel(ev){
  if (!ev?.starts_at) return '';
  if (ev.all_day) return 'All day';
  try{
    const d = new Date(ev.starts_at);
    if (Number.isNaN(d.getTime())) return '';
    return d.toLocaleTimeString([], {
      hour: 'numeric',
      minute: '2-digit',
      hour12: !use24HourClock()
    });
  }catch{ return ''; }
}

function gcalAgendaHTML(dateIso){
  // Nothing to collapse around: no header, no empty card, no gap.
  if (!FEATURES.integrations) return '';
  const events = googleEventsOn(dateIso);
  if (!events.length) return '';
  return events.map(ev => `
    <div class="m-book gcal-book">
      <div class="m-book-body">
        <div class="gcal-mark" aria-hidden="true">G</div>
        <div class="m-book-main">
          <div class="m-book-top">
            <span class="m-book-name">${esc(ev.title || 'Google event')}</span>
            <span class="badge gcal-badge">Google</span>
          </div>
          <div class="m-book-svc">${esc(gcalEventTimeLabel(ev) || 'Event')}</div>
        </div>
      </div>
      <div class="m-book-actions">
        ${ev.html_link
          ? `<a class="m-book-act primary" href="${esc(ev.html_link)}" target="_blank" rel="noopener">Open</a>`
          : `<span class="m-book-act ghost">Read only</span>`}
      </div>
    </div>`).join('');
}

