function scheduleGcalSync(delay = 1200){
  if (!FEATURES.integrations) return;
  if (!state.gcal?.connected || !state.gcal?.plan_ok) return;
  clearTimeout(_gcalSyncTimer);
  _gcalSyncTimer = setTimeout(() => { syncGoogleCalendar({ quiet: true }); }, delay);
}

async function syncGoogleCalendar({ quiet = false } = {}){
  if (!me()) return;
  if (!state.gcal?.connected){
    if (!quiet) toast('Connect Google Calendar first');
    return;
  }
  if (!state.gcal?.plan_ok){
    if (!quiet) toast(FEATURES.plans ? 'Google Calendar needs Pro or Pod' : 'Google Calendar is not available yet');
    return;
  }
  try{
    const { data, error } = await sb.functions.invoke('google-calendar', {
      body: { action: 'sync' }
    });
    if (error) throw error;
    if (data?.error) throw new Error(data.error);
    await refreshGcalStatus();
    await loadGcalEvents();
    if (!quiet) toast(`Synced · ${data?.pushed || 0} out · ${data?.pulled || 0} in`);
    if (state.deskView === 'calendar' || ($('.m-screen.active')||{}).id === 'm-calendar') renderAll();
  }catch(e){
    if (!quiet) notify(errMsg(e));
  }
}

async function connectGoogleCalendar(){
  if (!me()){ toast('Sign in first'); return; }
  const plan = state.billing?.plan || me()?.plan || 'free';
  const planOk = state.gcal?.plan_ok ?? (plan === 'pro' || plan === 'pod' || !!me()?.is_admin);
  if (!FEATURES.integrations) return;
  if (!planOk){ toast(FEATURES.plans ? 'Upgrade to Pro or Pod for Google Calendar' : 'Google Calendar is not available yet'); return; }
  if (busyLocked()) return;
  markBusy(true);
  try{
    const { data, error } = await sb.functions.invoke('google-calendar', {
      body: { action: 'connect', callback_origin: location.origin }
    });
    if (error) throw error;
    if (data?.error) throw new Error(data.error);
    if (!data?.url) throw new Error('Could not start Google connect');
    location.href = data.url;
  }catch(e){
    notify(errMsg(e));
  }finally{ markBusy(false); }
}

