function myloAddDays(isoStr, n){
  const d = new Date(isoStr + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return iso(d);
}
function inferMyloCategory(title, blob, existingNames){
  const text = `${title || ''} ${blob || ''}`;
  const names = existingNames || state.categories.map(c => c.name);
  for (const name of names){
    if (!name) continue;
    try{
      if (new RegExp(`\\b${String(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(text)) return name;
    }catch(_){}
  }
  for (const h of MYLO_CAT_HINTS){
    if (h.words.test(text)) return h.name;
  }
  return null;
}
async function ensureMyloCategory(name){
  const clean = String(name || '').trim().slice(0, 24);
  if (!clean || !room() || !me()) return null;
  const existing = state.categories.find(c => c.name.toLowerCase() === clean.toLowerCase());
  if (existing) return existing.id;
  const hint = MYLO_CAT_HINTS.find(h => h.name.toLowerCase() === clean.toLowerCase());
  const color = hint?.color || COLORS[Math.floor(Math.random() * COLORS.length)];
  const { data, error } = await sb.from('categories').insert({
    room_id: room().id,
    owner_id: me().id,
    name: clean,
    color
  }).select().single();
  if (error) throw error;
  if (data){
    state.categories = [...state.categories, data];
    if (hint?.icon) setCatIconName(data.id, hint.icon);
  }
  return data?.id || null;
}
function myloParseLocal(text){
  const chunks = text.split(/\n+|,\s*(?=[a-zA-Z])|\band\s+then\b|\bthen\b|\balso\b|;/i).map(s => s.trim()).filter(s => s.length > 2);
  const goals = [];
  const existingNames = state.categories.map(c => c.name);
  for (const chunk of chunks){
    const lower = chunk.toLowerCase();
    let due = TODAY_ISO;
    let scope = 'day';
    if (/\btomorrow\b/.test(lower)) due = myloAddDays(TODAY_ISO, 1);
    else if (/\bthis\s+week\b/.test(lower)) scope = 'week';
    else if (/\bthis\s+month\b/.test(lower)) scope = 'month';
    else if (/\bthis\s+year\b/.test(lower)) scope = 'year';
    let start = '08:00';
    const tm = lower.match(/\bat\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
    if (tm){
      let h = Number(tm[1]);
      const min = tm[2] ? Number(tm[2]) : 0;
      const ap = (tm[3] || '').toLowerCase();
      if (ap === 'pm' && h < 12) h += 12;
      if (ap === 'am' && h === 12) h = 0;
      if (h <= 23 && min <= 59) start = `${pad(h)}:${pad(min)}`;
    } else if (/\bafternoon\b/.test(lower)) start = '13:00';
    else if (/\b(night|evening|tonight)\b/.test(lower)) start = '19:00';
    else if (/\bmorning\b/.test(lower)) start = '08:00';
    let duration = 30;
    const hm = lower.match(/(\d+(?:\.\d+)?)\s*h(?:ou)?rs?/);
    const mm = lower.match(/(\d+)\s*mins?/);
    if (hm) duration = Math.round(Number(hm[1]) * 60);
    else if (mm) duration = Number(mm[1]);
    else if (/\ban?\s*hour\b/.test(lower)) duration = 60;
    else if (/\bhalf\s*an?\s*hour\b/.test(lower)) duration = 30;
    const is_shared = /\b(shared|together|with\s+(the\s+)?(crew|pod|team|friends?|everyone)|as\s+a\s+group)\b/i.test(lower);
    let title = chunk
      .replace(/\b(today|tomorrow|tonight|this\s+week|this\s+month|this\s+year|morning|afternoon|evening|night)\b/gi, ' ')
      .replace(/\bat\s+\d{1,2}(?::\d{2})?\s*(am|pm)?/gi, ' ')
      .replace(/\bfor\s+\d+(?:\.\d+)?\s*(h(?:ou)?rs?|mins?|m)\b/gi, ' ')
      .replace(/\b(shared|together|with\s+(the\s+)?(crew|pod|team|friends?|everyone)|i\s+want\s+to|i'd\s+like\s+to|i\s+need\s+to|lets?|let's|gonna|going\s+to|please|can\s+you|mylo|milo)\b/gi, ' ')
      .replace(/[^a-zA-Z0-9 &'+/-]+/g, ' ').replace(/\s+/g, ' ').trim();
    if (!title) title = 'Goal';
    title = title.slice(0, 80).replace(/^\w/, c => c.toUpperCase());
    const category_name = inferMyloCategory(title, chunk, existingNames);
    goals.push({
      title, scope,
      due_date: scope === 'year' ? null : due,
      start_time: scope === 'year' ? null : start,
      duration_min: scope === 'year' ? null : duration,
      is_shared,
      category_name
    });
  }
  if (!goals.length){
    return { engine: 'local', reply: 'tell me what you want on the board — e.g. “gym today at 7 for 1 hour, study tomorrow afternoon.”', goals: [] };
  }
  const summary = goals.map(g => {
    const when = g.due_date || 'someday';
    const time = g.start_time ? ` ${displayTime(g.start_time)}` : '';
    const dur = g.duration_min ? ` · ${g.duration_min}m` : '';
    const cat = g.category_name ? ` · ${g.category_name}` : '';
    return `• ${g.title} (${when}${time}${dur}${cat}${g.is_shared ? ' · shared' : ''})`;
  }).join('\n');
  return { engine: 'local', reply: `I drafted ${goals.length} goal${goals.length === 1 ? '' : 's'} for your pod:\n${summary}\n\nAdd them?`, goals };
}

function myloTodayPool(){
  return [...myGoals(), ...sharedGoals()].filter(inToday).slice().sort(sortByStart);
}
function myloFindGoal(query, pool){
  const q = String(query || '').trim().toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!q) return null;
  const list = pool || myloTodayPool();
  let best = null, bestScore = 0;
  for (const g of list){
    const title = String(g.title || '').toLowerCase();
    if (!title) continue;
    let score = 0;
    if (title === q) score = 100;
    else if (title.includes(q) || q.includes(title)) score = 80;
    else {
      const words = q.split(' ').filter(w => w.length > 2);
      const hits = words.filter(w => title.includes(w)).length;
      if (hits) score = 40 + hits * 15;
    }
    if (score > bestScore){ bestScore = score; best = g; }
  }
  return bestScore >= 40 ? best : null;
}
function myloStripGoalQuery(text, verbs){
  let t = String(text || '');
  for (const v of verbs){
    t = t.replace(v, ' ');
  }
  return t
    .replace(/\b(today|tonight|please|for\s+me|the\s+goal|goal|task|my)\b/gi, ' ')
    .replace(/[^a-zA-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function myloLooksLikeGoal(text){
  const raw = String(text || '').trim();
  const lower = raw.toLowerCase();
  if (!raw || raw.length > 160) return false;
  if (/[?]/.test(raw)) return false;
  if (/\b(what|where|who|why|how|when|can you|could you|tell me|explain|confused|help me understand)\b/.test(lower)) return false;
  if (myloLooksLikeRoutine(raw)) return false;
  if (/\b(add|create|lock in|schedule|new goal|set a goal)\b/.test(lower)) return true;
  const hasClock = myloParseClockToken(lower) != null
    || /\bat\s+\d{1,2}(?::\d{2})?\s*(am|pm)?/.test(lower)
    || /\bby\s+\d{1,2}/.test(lower);
  const hasDur = /\bfor\s+\d+(\.\d+)?\s*(h|hr|hrs|hour|hours|min|mins|minutes)\b/.test(lower) || /\b\d+\s*(min|mins|minutes|h|hr|hrs|hours)\b/.test(lower);
  const hasWhen = /\b(today|tomorrow|tonight)\b/.test(lower);
  // Clear lock-in shape: when + (time or duration), or clock + activity-ish length
  if (hasWhen && (hasClock || hasDur)) return true;
  if (hasClock && hasDur) return true;
  // "go to the gym by 1" / "gym at 1pm" — start intake even if duration is missing
  if (hasClock && /\b(gym|workout|study|pray|run|walk|cook|work|read|clean|meeting|dentist|doctor)\b/.test(lower)) return true;
  // "study tonight" / "gym today" — enough to start asking for the rest
  if (hasWhen && /\b(gym|workout|study|pray|run|walk|cook|work|read|clean|meeting|dentist|doctor|go to)\b/.test(lower)) return true;
  return false;
}
function myloLooksLikeRoutine(text){
  const lower = String(text || '').toLowerCase().trim();
  if (!lower || lower.length > 200) return false;
  if (/[?]/.test(lower)) return false;
  if (/\b(add|create|set( up)?|make|new)\b.+\b(routine|system|morning\s+routine|night\s+routine)\b/.test(lower)) return true;
  if (/\b(my |a )?(morning|afternoon|night|evening)\s+routine\b/.test(lower) && /\b(add|create|set|make|build|start)\b/.test(lower)) return true;
  if (/^(wake up|get up)\b/.test(lower) && /\b(then|after|and)\b/.test(lower)) return true;
  if (/\bevery\s+(day|morning|afternoon|night|evening)\b/.test(lower)) return true;
  if (/^i want to (add|set up|create) a routine\b/.test(lower)) return true;
  return false;
}

/* ── Conversational intake: gather missing fields, then review, then confirm ── */
const MYLO_WORD_HOURS = {
  one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8,
  nine: 9, ten: 10, eleven: 11, twelve: 12, noon: 12, midnight: 0
};
function myloParseClockToken(text){
  const s = String(text || '').toLowerCase();
  let m = s.match(/\b(?:at|by|around|from)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm|o'?clock)?\b/i);
  if (!m) m = s.match(/\b(\d{1,2})(?::(\d{2}))\s*(am|pm)\b/i);
  if (!m){
    const w = s.match(/\b(?:at|by|around)\s+(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|noon|midnight)(?:\s*o'?clock)?(?:\s*(am|pm))?\b/i);
    if (w){
      let h = MYLO_WORD_HOURS[w[1].toLowerCase()];
      const ap = (w[2] || '').toLowerCase();
      if (w[1].toLowerCase() === 'noon') return '12:00';
      if (w[1].toLowerCase() === 'midnight') return '00:00';
      if (ap === 'pm' && h < 12) h += 12;
      if (ap === 'am' && h === 12) h = 0;
      // bare "by one" with no am/pm — afternoon if 1–6, else as-is morning
      if (!ap && h >= 1 && h <= 6) h += 12;
      return `${pad(h)}:00`;
    }
    return null;
  }
  let h = Number(m[1]);
  const min = m[2] ? Number(m[2]) : 0;
  let ap = (m[3] || '').toLowerCase();
  if (ap.startsWith('o')) ap = ''; // o'clock
  if (ap === 'pm' && h < 12) h += 12;
  if (ap === 'am' && h === 12) h = 0;
  if (!ap && h >= 1 && h <= 6 && /\bby\b/.test(s)) h += 12;
  if (h > 23 || min > 59) return null;
  return `${pad(h)}:${pad(min)}`;
}
function myloParseDurationToken(text){
  const lower = String(text || '').toLowerCase();
  let m = lower.match(/(\d+(?:\.\d+)?)\s*h(?:ou)?rs?/);
  if (m) return Math.round(Number(m[1]) * 60);
  m = lower.match(/(\d+)\s*(mins?|minutes?)\b/);
  if (m) return Number(m[1]);
  m = lower.match(/\bfor\s+(\d+)\s*m\b/);
  if (m) return Number(m[1]);
  if (/\bhalf\s*an?\s*hour\b/.test(lower)) return 30;
  if (/\ban?\s*hour\b/.test(lower)) return 60;
  // bare number while we're asking for duration: "45" / "45 minutes"
  m = lower.match(/^(\d{1,3})\s*(m|min|mins|minutes)?$/);
  if (m){
    const n = Number(m[1]);
    if (m[2] || n >= 5) return n > 480 ? 480 : n;
  }
  return null;
}
function myloCleanActivityTitle(chunk){
  let t = String(chunk || '')
    .replace(/\b(today|tomorrow|tonight|this\s+week|this\s+month|this\s+year|morning|afternoon|evening|night)\b/gi, ' ')
    .replace(/\b(?:at|by|around|from)\s+(\d{1,2}(?::\d{2})?\s*(?:am|pm)?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|noon|midnight)(?:\s*o'?clock)?/gi, ' ')
    .replace(/\bfor\s+\d+(?:\.\d+)?\s*(h(?:ou)?rs?|mins?|m)\b/gi, ' ')
    .replace(/\b(every\s+day|daily|routine|system)\b/gi, ' ')
    .replace(/\b(shared|together|with\s+(the\s+)?(crew|pod|team|friends?|everyone)|i\s+want\s+to|i'd\s+like\s+to|i\s+need\s+to|lets?|let's|gonna|going\s+to|please|can\s+you|mylo|milo|add|create|set\s+up|a\s+goal|go\s+to|the)\b/gi, ' ')
    .replace(/[^a-zA-Z0-9 &'+/-]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) t = 'Goal';
  return t.slice(0, 80).replace(/^\w/, c => c.toUpperCase());
}
function myloExtractSteps(text){
  const raw = String(text || '');
  // "wake up, stretch, pray" or "wake up then stretch then pray"
  const parts = raw
    .split(/\s*(?:,|\band\s+then\b|\bthen\b|\bafter\s+that\b|\bafterwards\b|;)\s*/i)
    .map(s => s.trim())
    .filter(s => s.length > 1);
  if (parts.length < 2) return [];
  return parts.slice(1).map(s => myloCleanActivityTitle(s)).filter(Boolean).slice(0, 12);
}
function myloExtractPartial(text){
  const chunk = String(text || '').trim();
  const lower = chunk.toLowerCase();
  const isRoutine = myloLooksLikeRoutine(chunk);
  let due = TODAY_ISO;
  let scope = 'day';
  if (/\btomorrow\b/.test(lower)) due = myloAddDays(TODAY_ISO, 1);
  else if (/\bthis\s+week\b/.test(lower)) scope = 'week';
  else if (/\bthis\s+month\b/.test(lower)) scope = 'month';
  else if (/\bthis\s+year\b/.test(lower)) scope = 'year';
  const start = myloParseClockToken(lower);
  let daypart = null;
  if (/\bmorning\b/.test(lower)) daypart = 'morning';
  else if (/\bafternoon\b/.test(lower)) daypart = 'afternoon';
  else if (/\b(night|evening|tonight)\b/.test(lower)) daypart = 'night';
  else if (start) daypart = daypartFromTime(start);
  const duration = myloParseDurationToken(lower);
  const is_shared = /\b(shared|together|with\s+(the\s+)?(crew|pod|team|friends?|everyone)|as\s+a\s+group)\b/i.test(lower);
  const steps = isRoutine ? myloExtractSteps(chunk) : [];
  const titleHead = isRoutine
    ? myloCleanActivityTitle(chunk.split(/\s*(?:,|\bthen\b|\band\s+then\b)/i)[0] || chunk)
    : myloCleanActivityTitle(chunk);
  const title = titleHead || (isRoutine ? 'Routine' : 'Goal');
  const category_name = inferMyloCategory(title, chunk, state.categories.map(c => c.name));
  return {
    kind: isRoutine ? 'routine' : 'goal',
    title,
    scope: isRoutine ? 'day' : scope,
    due_date: isRoutine || scope === 'year' ? null : due,
    start_time: start,
    duration_min: isRoutine ? null : duration,
    daypart,
    is_shared: isRoutine ? false : is_shared,
    category_name,
    steps
  };
}
function myloIntake(){ return state.myloIntake || null; }
function myloClearIntake(){ state.myloIntake = null; myloDrafts = []; }
function myloStartIntake(partial){
  const kind = partial.kind === 'routine' ? 'routine' : 'goal';
  state.myloIntake = {
    kind,
    ask: null,
    draft: {
      title: partial.title || (kind === 'routine' ? 'Routine' : 'Goal'),
      scope: partial.scope || 'day',
      due_date: partial.due_date ?? (kind === 'goal' ? TODAY_ISO : null),
      start_time: partial.start_time || null,
      duration_min: partial.duration_min || null,
      daypart: partial.daypart || null,
      is_shared: !!partial.is_shared,
      category_name: partial.category_name || null,
      steps: Array.isArray(partial.steps) ? partial.steps.slice() : []
    }
  };
  let next = myloNextAsk(state.myloIntake);
  // Steps already in the first message → still ask once if they want more
  if (kind === 'routine' && (state.myloIntake.draft.steps || []).length && next === 'review'){
    next = 'more_steps';
  }
  state.myloIntake.ask = next;
  return state.myloIntake;
}
function myloNextAsk(session){
  if (!session) return null;
  const d = session.draft;
  if (session.kind === 'goal'){
    if (!d.start_time && !d.daypart) return 'time';
    if (d.scope !== 'year' && !(Number(d.duration_min) > 0)) return 'duration';
    return 'review';
  }
  // routine
  if (!d.start_time && !d.daypart) return 'time';
  if (!d.daypart && d.start_time) d.daypart = daypartFromTime(d.start_time);
  if (session.ask !== 'more_steps' && !(d.steps || []).length) return 'steps';
  if (session.ask === 'more_steps') return 'more_steps';
  return 'review';
}
function myloAskPrompt(session){
  const d = session.draft;
  const title = d.title || (session.kind === 'routine' ? 'this' : 'that');
  if (session.ask === 'time'){
    if (session.kind === 'routine'){
      return {
        reply: `got it — “${title}”.\nwhat time should this start? morning, afternoon, or night also works.`,
        chips: [
          { label: 'Morning · 8am', send: '8am' },
          { label: 'Afternoon · 1pm', send: '1pm' },
          { label: 'Night · 8pm', send: '8pm' }
        ]
      };
    }
    return {
      reply: `“${title}” — what time?\nsomething like 1pm or 13:00.`,
      chips: [
        { label: 'Morning', send: 'morning' },
        { label: 'Afternoon', send: 'afternoon' },
        { label: 'Night', send: 'night' }
      ]
    };
  }
  if (session.ask === 'duration'){
    const when = d.start_time ? ` at ${displayTime(d.start_time)}` : '';
    return {
      reply: `how many minutes for “${title}”${when}?`,
      chips: [
        { label: '30 min', send: '30 minutes' },
        { label: '1 hour', send: '1 hour' },
        { label: '90 min', send: '90 minutes' }
      ]
    };
  }
  if (session.ask === 'steps'){
    return {
      reply: `What’s the first step after you start “${title}”?`,
      chips: [
        { label: 'Skip steps', send: '__SKIP_STEPS__' },
        { label: 'Cancel', send: 'cancel' }
      ]
    };
  }
  if (session.ask === 'more_steps'){
    return {
      reply: `What else after that? Or say “done” when the list is complete.`,
      chips: [
        { label: 'Done', send: 'done' },
        { label: 'Cancel', send: 'cancel' }
      ]
    };
  }
  return myloReviewPrompt(session);
}
function myloReviewPrompt(session){
  const d = session.draft;
  if (session.kind === 'routine'){
    if (!d.daypart && d.start_time) d.daypart = daypartFromTime(d.start_time);
    const steps = (d.steps || []).map((s, i) => `${i + 1}. ${s}`).join('\n');
    const when = d.start_time
      ? `${displayTime(d.start_time)} · ${d.daypart || 'daily'}`
      : (d.daypart || 'daily');
    return {
      reply: `review your routine, then confirm:`,
      chips: [
        { label: 'Confirm', send: '__CONFIRM_INTAKE__' },
        { label: 'Change time', send: '__EDIT_TIME__' },
        { label: 'Cancel', send: 'cancel' }
      ],
      routine: {
        title: d.title,
        start_time: d.start_time,
        daypart: d.daypart,
        category_name: d.category_name,
        steps: d.steps || [],
        when_label: when,
        steps_label: steps || 'No steps'
      },
      goals: []
    };
  }
  const when = d.due_date === TODAY_ISO ? 'Today' : (d.due_date || d.scope || 'day');
  const time = d.start_time ? displayTime(d.start_time) : (d.daypart || '');
  const dur = d.duration_min ? `${d.duration_min} min` : '';
  return {
      reply: `review this, then confirm:`,
    chips: [
      { label: 'Confirm', send: '__CONFIRM_INTAKE__' },
      { label: 'Change time', send: '__EDIT_TIME__' },
      { label: 'Cancel', send: 'cancel' }
    ],
    goals: [{
      title: d.title,
      scope: d.scope || 'day',
      due_date: d.due_date,
      start_time: d.start_time,
      duration_min: d.duration_min,
      is_shared: !!d.is_shared,
      category_name: d.category_name,
      when_label: [when, time, dur].filter(Boolean).join(' · ')
    }],
    routine: null
  };
}
function myloApplyIntakeAnswer(raw){
  const session = myloIntake();
  if (!session) return null;
  const text = String(raw || '').trim();
  const lower = text.toLowerCase();
  const d = session.draft;

  if (text === '__EDIT_TIME__'){
    session.ask = 'time';
    d.start_time = null;
    if (session.kind === 'routine') d.daypart = null;
    return myloAskPrompt(session);
  }
  if (text === '__SKIP_STEPS__'){
    d.steps = [];
    session.ask = 'review';
    return myloAskPrompt(session);
  }
  if (text === '__CONFIRM_INTAKE__' || /^(ok|okay|yes|yep|yeah|confirm|add( it)?|do it|sure|please)\b/i.test(text)){
    if (session.ask === 'review' || myloNextAsk(session) === 'review'){
      session.ask = 'review';
      return { confirm: true };
    }
  }

  if (session.ask === 'time'){
    if (/^(morning|afternoon|night|evening)$/.test(lower)){
      const part = lower === 'evening' ? 'night' : lower;
      d.daypart = part;
      d.start_time = part === 'morning' ? '08:00' : (part === 'afternoon' ? '13:00' : '19:00');
    } else {
      const clock = myloParseClockToken(lower) || myloParseClockToken(`at ${lower}`);
      if (!clock){
        return {
          reply: `I didn’t catch a time. Try “1pm”, “13:00”, or tap morning / afternoon / night.`,
          chips: [
            { label: 'Morning · 8am', send: '8am' },
            { label: 'Afternoon · 1pm', send: '1pm' },
            { label: 'Night · 8pm', send: '8pm' }
          ]
        };
      }
      d.start_time = clock;
      d.daypart = daypartFromTime(clock);
    }
    session.ask = myloNextAsk(session);
    return myloAskPrompt(session);
  }

  if (session.ask === 'duration'){
    const dur = myloParseDurationToken(lower);
    if (!(dur > 0)){
      return {
        reply: `How long should “${d.title}” take? Reply with minutes, like 45 or 1 hour.`,
        chips: [
          { label: '30 min', send: '30 minutes' },
          { label: '1 hour', send: '1 hour' },
          { label: '90 min', send: '90 minutes' }
        ]
      };
    }
    d.duration_min = dur;
    session.ask = 'review';
    return myloAskPrompt(session);
  }

  if (session.ask === 'steps' || session.ask === 'more_steps'){
    if (/^(done|that'?s all|thats all|finish|finished|no more|nothing else|skip)\b/i.test(lower) || text === '__SKIP_STEPS__'){
      session.ask = 'review';
      return myloAskPrompt(session);
    }
    const step = text.replace(/^(then|and then|also|after that)\s+/i, '').trim().slice(0, 120);
    if (step.length < 2){
      return {
        reply: `Type a short step, or say “done”.`,
        chips: [{ label: 'Done', send: 'done' }, { label: 'Cancel', send: 'cancel' }]
      };
    }
    d.steps = d.steps || [];
    d.steps.push(step.replace(/^\w/, c => c.toUpperCase()));
    session.ask = 'more_steps';
    return myloAskPrompt(session);
  }

  // Mid-intake free text that looks like a brand-new goal/routine → restart
  if (myloLooksLikeRoutine(text) || myloLooksLikeGoal(text)){
    myloStartIntake(myloExtractPartial(text));
    return myloAskPrompt(myloIntake());
  }
  return {
    reply: `We’re still setting up “${d.title}”. Answer the last question, or say cancel.`,
    chips: [{ label: 'Cancel', send: 'cancel' }]
  };
}
async function confirmMyloIntake(){
  const session = myloIntake();
  if (!session){ toast('Nothing to add'); return; }
  if (session.kind === 'routine'){
    await confirmMyloRoutine(session);
    return;
  }
  // Map draft → myloDrafts and reuse goal insert
  const d = session.draft;
  if (!d.start_time && d.daypart){
    d.start_time = d.daypart === 'morning' ? '08:00' : (d.daypart === 'afternoon' ? '13:00' : '19:00');
  }
  myloDrafts = [{
    title: d.title,
    scope: d.scope || 'day',
    due_date: d.due_date || TODAY_ISO,
    start_time: d.start_time || '08:00',
    duration_min: Number(d.duration_min) > 0 ? Number(d.duration_min) : 30,
    is_shared: !!d.is_shared,
    category_name: d.category_name || null
  }];
  myloClearIntake();
  await confirmMyloGoals({ fromAsk: true });
}
async function confirmMyloRoutine(session){
  if (!room() || !me()){ toast('Open a room first'); return; }
  const d = session.draft;
  if (!d.start_time && d.daypart){
    d.start_time = d.daypart === 'morning' ? '08:00' : (d.daypart === 'afternoon' ? '13:00' : '19:00');
  }
  if (!d.daypart && d.start_time) d.daypart = daypartFromTime(d.start_time) || 'morning';
  let catId = null;
  if (d.category_name){
    try{ catId = await ensureMyloCategory(d.category_name); }catch(_){ catId = null; }
  }
  const id = await addRoutineItem(d.title, d.daypart || 'morning', catId, d.start_time || null);
  if (!id) return;
  for (const step of (d.steps || [])){
    await addRoutineSub(id, step);
  }
  myloClearIntake();
  await loadSpaceMeta();
  if (state.chatView === 'mylo'){
    const msgs = state.myloMessages || [];
    const last = msgs[msgs.length - 1];
    const text = `added “${d.title}” to your ${d.daypart || 'daily'} routine${(d.steps || []).length ? ` · ${d.steps.length} step${d.steps.length > 1 ? 's' : ''}` : ''}.`;
    if (last?.typing || last?.text === 'okay — adding that.' || last?.text === 'Adding it now…'){
      last.typing = false;
      last.text = text;
      last.chips = myloDefaultChips();
      last.goals = [];
      last.routine = null;
      last.review = false;
      saveMyloChat();
    } else {
      myloPushMessage({
        id: 'a'+Date.now(),
        role: 'assistant',
        text,
        chips: myloDefaultChips(),
        at: new Date().toISOString()
      });
    }
    renderChatOnly();
  } else {
    renderAll();
  }
  toast('Routine added');
}
function myloLooksLikeGcal(text){
  const lower = String(text || '').toLowerCase();
  return /\b(google\s*calendar|gcal)\b/.test(lower) ||
    /\b(on|to|in|from)\s+(my\s+)?(google\s+)?calendar\b/.test(lower) ||
    /\b(add|create|schedule|book|put|delete|remove|cancel|move|reschedule|edit|update)\b.+\bcalendar\b/.test(lower) ||
    /\bwhat('?s| is) on (my )?(google )?calendar\b/.test(lower) ||
    /\b(show|list)\b.+\b(google )?calendar\b/.test(lower) ||
    /\bupcoming (google )?events?\b/.test(lower);
}

function myloLooksLikeNotion(text){
  const lower = String(text || '').toLowerCase();
  return /\bnotion\b/.test(lower) ||
    /\b(push|send|export)\b.+\b(today|goals?|tasks?)\b.+\b(to\s+)?notion\b/.test(lower) ||
    /\b(add|create|write|append|edit|update|rename|search|find|list|read|open)\b.+\b(to|in|on|from)?\s*notion\b/.test(lower);
}

/** Google Calendar bridge for Mylo. Mirrors myloInvokeNotion. */
async function myloInvokeGcal(action, payload = {}){
  return invokeFunction('google-calendar', { action, ...payload });
}
async function myloInvokeNotion(action, payload = {}){
  return invokeFunction('notion', { action, ...payload });
}

async function myloRunNotionActions(actions){
  const results = [];
  for (const a of (actions || []).slice(0, 5)){
    const op = String(a.op || a.action || '').toLowerCase();
    if (op === 'list' || op === 'search'){
      const data = await myloInvokeNotion(op === 'search' ? 'search' : 'list_pages', {
        query: a.query || '',
        limit: Number(a.limit) || 12
      });
      const pages = data.pages || [];
      if (!pages.length){
        results.push(
          (a.query
            ? `No Notion pages matched “${a.query}”.\n\n`
            : `Notion is connected, but Mylo can’t see any pages yet.\n\n`) +
          `Fix (pick one):\n` +
          `1) You → Integrations → Disconnect Notion → Connect Notion again, and select pages in Notion’s allow screen\n` +
          `2) Or in Notion: open a page → ••• → Connections → Add connection → Mylo`
        );
      } else {
        const lines = pages.slice(0, 12).map(p => {
          const label = `${p.title || 'Untitled'}${p.object === 'database' ? ' (db)' : ''}`;
          return `• ${myloMdLink(label, p.url)}`;
        });
        results.push(`Notion pages${a.query ? ` for “${a.query}”` : ''}:\n${lines.join('\n')}`);
      }
      continue;
    }
    if (op === 'read'){
      const data = await myloInvokeNotion('read_page', {
        page_id: a.page_id,
        query: a.query || a.title
      });
      const preview = (data.preview || []).slice(0, 12);
      const titled = myloMdLink(data.page?.title || a.query || 'page', data.page?.url);
      results.push(preview.length
        ? `Notion ${titled}:\n${preview.join('\n')}`
        : `Opened Notion ${titled} (empty or no readable blocks).`);
      continue;
    }
    if (op === 'append' || op === 'append_todo'){
      const data = await myloInvokeNotion(op === 'append_todo' || a.as_todo ? 'append_todo' : 'append', {
        page_id: a.page_id,
        query: a.query || a.page_title,
        content: a.content || a.text || a.title,
        title: a.title,
        as_todo: !!a.as_todo,
        items: a.items
      });
      results.push(`Updated Notion ${myloMdLink(data.title || a.query || 'page', data.url)}.`);
      continue;
    }
    if (op === 'rename'){
      const data = await myloInvokeNotion('rename_page', {
        page_id: a.page_id,
        query: a.query,
        title: a.title
      });
      results.push(`Renamed Notion page to ${myloMdLink(data.title, data.url)}.`);
      continue;
    }
    if (op === 'push_today'){
      const data = await pushTodayToNotion({ quiet: true });
      const titled = myloMdLink(data?.title || 'Mylo · Today', data?.url);
      results.push(`Pushed Today to Notion as ${titled} (${data?.count || 0} items).`);
      continue;
    }
    if (op === 'create'){
      const data = await myloInvokeNotion('create_page', {
        title: a.title || 'Mylo note',
        content: a.content || a.text || `Added by Mylo · ${TODAY_ISO}`
      });
      results.push(`Added ${myloMdLink(data.title || a.title, data.url)} in Notion.`);
      continue;
    }
  }
  await refreshNotionStatus();
  return results.join('\n\n') || 'Done.';
}

function myloFindGcalEvent(query){
  const q = String(query || '').toLowerCase().trim();
  if (!q) return null;
  const list = state.gcalEvents || [];
  let hit = list.find(ev => String(ev.title || '').toLowerCase() === q);
  if (hit) return hit;
  hit = list.find(ev => String(ev.title || '').toLowerCase().includes(q));
  if (hit) return hit;
  const tokens = q.split(/\s+/).filter(Boolean);
  hit = list.find(ev => {
    const t = String(ev.title || '').toLowerCase();
    return tokens.every(tok => t.includes(tok));
  });
  return hit || null;
}

function myloParseGcalDraft(text){
  const parsed = myloParseLocal(text);
  const g = (parsed.goals && parsed.goals[0]) || null;
  if (!g){
    let title = String(text || '')
      .replace(/\b(add|create|schedule|book|put|to|on|in|my|google|calendar|please|can you|mylo|milo)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80);
    if (!title) title = 'Event';
    return {
      title: title.replace(/^\w/, c => c.toUpperCase()),
      date: TODAY_ISO,
      start_time: '09:00',
      duration_min: 60
    };
  }
  return {
    title: g.title || 'Event',
    date: g.due_date || TODAY_ISO,
    start_time: (g.start_time || '09:00').slice(0, 5),
    duration_min: Number(g.duration_min) > 0 ? Number(g.duration_min) : 60
  };
}

function busyIntervalsForDate(dateIso, { excludeGoalIds = [] } = {}){
  const intervals = [];
  const excl = new Set(excludeGoalIds);
  (state.goals || []).forEach(g => {
    if (!g || excl.has(g.id)) return;
    if (g.scope !== 'day' || g.due_date !== dateIso) return;
    const start = parseTimeToMins(g.start_time);
    if (start == null) return;
    const dur = Number(g.duration_min) > 0 ? Number(g.duration_min) : 30;
    intervals.push({ start, end: start + dur, source: 'goal', title: g.title });
  });
  (state.gcalEvents || []).forEach(ev => {
    if (!ev?.starts_at) return;
    const d = String(ev.starts_at).slice(0, 10);
    if (d !== dateIso) return;
    if (ev.all_day){
      intervals.push({ start: 0, end: 24 * 60, source: 'gcal', title: ev.title });
      return;
    }
    try{
      const s = new Date(ev.starts_at);
      const e = ev.ends_at ? new Date(ev.ends_at) : new Date(s.getTime() + 30 * 60000);
      if (Number.isNaN(s.getTime())) return;
      const start = s.getHours() * 60 + s.getMinutes();
      const end = Number.isNaN(e.getTime()) ? start + 30 : e.getHours() * 60 + e.getMinutes();
      intervals.push({ start, end: Math.max(end, start + 15), source: 'gcal', title: ev.title });
    }catch{}
  });
  (state._myloBatchBusy || []).forEach(b => {
    if (b.date !== dateIso || b.start == null) return;
    intervals.push({ start: b.start, end: b.end, source: 'batch', title: b.title });
  });
  return intervals.sort((a, b) => a.start - b.start);
}

function intervalsOverlap(aStart, aEnd, bStart, bEnd){
  return aStart < bEnd && bStart < aEnd;
}

function findClashFreeSlot(dateIso, startTime, durationMin, opts = {}){
  const dur = Math.max(15, Number(durationMin) || 30);
  let start = parseTimeToMins(startTime);
  if (start == null) start = 9 * 60;
  const busy = busyIntervalsForDate(dateIso, opts);
  const dayEnd = 22 * 60; // don't schedule past 10pm when shifting
  const step = 15;
  let shifted = false;
  let clashWith = null;
  for (let guard = 0; guard < 48; guard++){
    const end = start + dur;
    const hit = busy.find(b => intervalsOverlap(start, end, b.start, b.end));
    if (!hit){
      return {
        start_time: minsToTime(start),
        end_time: minsToTime(end),
        duration_min: dur,
        shifted,
        clashWith
      };
    }
    clashWith = hit.title || 'another event';
    shifted = true;
    start = Math.ceil(hit.end / step) * step;
    if (start + dur > dayEnd) break;
  }
  // fallback: keep original but mark conflict
  const orig = parseTimeToMins(startTime) ?? 9 * 60;
  return {
    start_time: minsToTime(orig),
    end_time: minsToTime(orig + dur),
    duration_min: dur,
    shifted: false,
    conflict: true,
    clashWith: clashWith || 'another event'
  };
}

async function myloPushGoalsToGoogleCalendar(rows){
  if (!state.gcal?.connected || !state.gcal?.plan_ok) return { notes: [] };
  try{ await loadGcalEvents(); }catch{}
  const notes = [];
  // Times were already clash-checked against goals + calendar before insert.
  // Only re-check Google events in case something changed; prefer shifting on calendar only.
  for (const row of rows){
    if (row.scope !== 'day' || !row.due_date || !row.start_time) continue;
    const gcalOnlyBusy = (state.gcalEvents || [])
      .filter(ev => ev?.starts_at && String(ev.starts_at).slice(0, 10) === row.due_date)
      .map(ev => {
        if (ev.all_day) return { start: 0, end: 24 * 60, title: ev.title };
        try{
          const s = new Date(ev.starts_at);
          const e = ev.ends_at ? new Date(ev.ends_at) : new Date(s.getTime() + 30 * 60000);
          const start = s.getHours() * 60 + s.getMinutes();
          const end = Number.isNaN(e.getTime()) ? start + 30 : e.getHours() * 60 + e.getMinutes();
          return { start, end: Math.max(end, start + 15), title: ev.title };
        }catch{ return null; }
      })
      .filter(Boolean);
    let start = parseTimeToMins(row.start_time) ?? 9 * 60;
    const dur = Math.max(15, Number(row.duration_min) || 30);
    let shifted = false;
    let clashWith = null;
    for (let i = 0; i < 40; i++){
      const end = start + dur;
      const hit = gcalOnlyBusy.find(b => intervalsOverlap(start, end, b.start, b.end));
      if (!hit) break;
      clashWith = hit.title || 'another event';
      shifted = true;
      start = Math.ceil(hit.end / 15) * 15;
      if (start + dur > 22 * 60){ shifted = false; break; }
    }
    const startTime = minsToTime(start);
    if (shifted){
      notes.push(`Moved “${row.title}” to ${startTime} on Google to avoid ${clashWith}.`);
      // Keep Mylo goal aligned with calendar
      try{
        await sb.from('goals')
          .update({ start_time: startTime, end_time: minsToTime(start + dur), duration_min: dur })
          .eq('room_id', row.room_id)
          .eq('owner_id', row.owner_id)
          .eq('title', row.title)
          .eq('due_date', row.due_date);
        row.start_time = startTime;
        row.end_time = minsToTime(start + dur);
        row.duration_min = dur;
      }catch{}
    }
    try{
      await myloInvokeGcal('create_event', {
        title: row.title,
        date: row.due_date,
        start_time: startTime,
        duration_min: dur,
        description: 'Added by Mylo · also on Mylo Today'
      });
      // Reserve this slot for later items in the same batch
      gcalOnlyBusy.push({ start, end: start + dur, title: row.title });
      notes.push(`📅 “${row.title}” → Google Calendar · ${row.due_date} ${startTime}`);
    }catch(e){
      notes.push(`Couldn’t add “${row.title}” to Google Calendar (${errMsg(e)}).`);
    }
  }
  await loadGcalEvents();
  return { notes };
}

