function currentLookBg(){
  return (state.lookDraft && state.lookDraft.bg)
    || localStorage.getItem('mylo:lookBg')
    || 'E8EDF2';
}
function draftLook(){
  if (!window.avatarKit) return { bg: currentLookBg() };
  // Customize always builds from layered parts (Mylo base + eyes/mouth/extras)
  const raw = state.lookDraft || avatarKit.lookFromProfile(me()) || avatarKit.defaultLook();
  const base = avatarKit.normalizeLook(raw);
  base.bg = (state.lookDraft && state.lookDraft.bg) || currentLookBg();
  return base;
}
function lookBgPanel(){
  const sel = String(currentLookBg()).replace('#','').toUpperCase();
  return `<div class="look-color-grid">${lookBgColors().map(c => `
    <button type="button" class="look-color ${sel===c.id?'is-on':''}" data-set-look="bg" data-look-id="${c.id}" aria-label="${esc(c.label)}" style="--swatch:#${c.id}"></button>
  `).join('')}</div>`;
}
/** Avatar studio: Suits (personas) · Customize (skin/eyes/mouth/extras/bg) · Photo */
/* One editor. The base Mylo is always what you are editing - presets just set
   the layers, they are not a separate mode you can get stuck in. */
const LOOK_PRESETS = [
  { id: 'classic', label: 'Classic', look: { eyes:'default', mouth:'straight', accessories:'none'    } },
  { id: 'soft',    label: 'Soft',    look: { eyes:'default', mouth:'straight', accessories:'bow'     } },
  { id: 'sharp',   label: 'Sharp',   look: { eyes:'default', mouth:'straight', accessories:'shades'  } },
  { id: 'focus',   label: 'Focus',   look: { eyes:'default', mouth:'straight', accessories:'nerd'    } },
  { id: 'play',    label: 'Play',    look: { eyes:'default', mouth:'straight', accessories:'hat'     } },
  { id: 'party',   label: 'Party',   look: { eyes:'default', mouth:'straight', accessories:'party'   } },
  { id: 'crown',   label: 'Crown',   look: { eyes:'default', mouth:'straight', accessories:'crown'   } },
  { id: 'headset', label: 'Headset', look: { eyes:'default', mouth:'straight', accessories:'headset' } }
];
function presetMatches(look, p){
  return ['eyes','mouth','accessories'].every(k => look[k] === p.look[k]);
}
function lookStudioPanel(look){
  const kit = window.AVATAR_KIT;
  if (!kit || !window.avatarKit){
    return `<p class="look-photo-copy">Avatar kit failed to load. Refresh and try again.</p>`;
  }
  look = avatarKit.normalizeLook(look || draftLook());
  const cats = [
    { id: 'preset', label: 'Looks', icon: 'body' },
    { id: 'color', label: 'Skin tone', icon: 'color' },
    { id: 'eyes', label: 'Eyes', icon: 'eyes' },
    { id: 'mouth', label: 'Mouth', icon: 'mouth' },
    { id: 'accessories', label: 'Extras', icon: 'glasses' },
    { id: 'bg', label: 'Background', icon: 'bg' }
  ];
  let cat = state.lookCat || 'preset';
  if (!cats.some(c => c.id === cat)) cat = 'preset';
  const catRow = cats.map(c => `
    <button type="button" class="look-cat ${c.id===cat?'is-on':''}" data-look-cat="${c.id}" aria-label="${esc(c.label)}" title="${esc(c.label)}">
      ${lookCatIcon(c.icon)}
    </button>`).join('');
  let label = cats.find(c => c.id === cat)?.label || 'Options';
  let panelBody = '';
  if (cat === 'preset'){
    panelBody = `<div class="look-preset-grid">
      ${LOOK_PRESETS.map(p => `
        <button type="button" class="look-preset ${presetMatches(look, p) ? 'is-on' : ''}" data-look-preset="${esc(p.id)}" aria-label="${esc(p.label)}">
          <span class="avatar-stack look-preset-av" role="img">${avatarLayersHTML({ ...look, ...p.look })}</span>
          <span class="look-preset-n">${esc(p.label)}</span>
        </button>`).join('')}
    </div>`;
  } else if (cat === 'color'){
    panelBody = lookColorGrid(look.color);
  } else if (cat === 'bg'){
    panelBody = lookBgPanel();
  } else {
    const layer = kit.layers.find(l => l.id === cat);
    label = layer?.label || label;
    panelBody = lookOptionGrid(layer, look[cat]);
  }
  return `
    <div class="look-cats" role="tablist">${catRow}</div>
    <div class="look-panel-label">${esc(label)}</div>
    ${panelBody}`;
}
function profileJoinedYear(p){
  const d = p?.created_at ? new Date(p.created_at) : null;
  return d && !Number.isNaN(d.getTime()) ? String(d.getFullYear()) : '2026';
}
/* ---- streak ----
   The old one read a localStorage key nothing ever wrote, so it silently fell back to
   "goals done" and never moved. Days are now derived from the space log: any day you
   ticked a quick to-do, finished a system, or earned XP is a day you showed up.
   The run counts back from today, and today being empty is a grace day rather than a
   broken streak — otherwise every morning would read 0. */
function activeDaySet(uid){
  const who = uid || me()?.id;
  const days = new Set();
  (state.spaceRows || []).forEach(r => {
    if (r.from_id !== who) return;
    const pl = r.payload || {};
    const hit = (pl.msg_kind === 'todo' && pl.mtype === 'tick' && pl.done)
      || (pl.msg_kind === 'routinecheck' && pl.done)
      || (pl.msg_kind === 'xp' && pl.mtype === 'earn' && pl.src !== 'time');
    if (!hit) return;
    const d = pl.date || String(r.created_at).slice(0, 10);
    if (d) days.add(d);
  });
  return days;
}
function isoDaysAgo(n){
  const d = new Date(TODAY);
  d.setDate(d.getDate() - n);
  return iso(d);
}
/* ── Streak ──────────────────────────────────────────────────────────────
   Duolingo's rule. A day counts only when you set at least one to-do for it and
   ticked every single one. It used to count any day you did anything at all —
   one tick out of ten kept it alive — which made the number meaningless.
   Today gets grace while it is still today; it breaks once the day is over. */
function dayTodos(dayIso, uid){
  const who = uid || me()?.id;
  return (state.todos || []).filter(t => t.by === who && todoDay(t) === dayIso);
}
function dayComplete(dayIso, uid){
  const list = dayTodos(dayIso, uid);
  return list.length > 0 && list.every(t => t.done);
}
function computeStreak(uid){
  let i = dayComplete(isoDaysAgo(0), uid) ? 0 : 1;
  let run = 0;
  while (dayComplete(isoDaysAgo(i), uid) && run < 5000){ run++; i++; }
  return run;
}
/* The run is what you have now. The record is the longest you have ever held,
   and the start is the day this one began — both walked back over the last
   year of days, which is as far as anyone's memory of a streak goes. */
const STREAK_MILESTONES = [7, 14, 30, 60, 100, 365];
function streakHistory(uid){
  const run = computeStreak(uid);
  const offset = dayComplete(isoDaysAgo(0), uid) ? 0 : 1;
  const startIso = run > 0 ? isoDaysAgo(offset + run - 1) : null;
  let record = 0, cur = 0;
  for (let n = 0; n < 400; n++){
    if (dayComplete(isoDaysAgo(n), uid)){ cur++; if (cur > record) record = cur; }
    else if (n > 0) cur = 0;                 // today still open does not break the count
  }
  record = Math.max(record, run);
  const next = STREAK_MILESTONES.find(m => m > run) || null;
  const prev = [...STREAK_MILESTONES].reverse().find(m => m <= run) || 0;
  return { run, record, startIso, next, prev };
}
/* What today is worth in XP, and how much of it is already banked. Possible
   counts what is on the board right now; earned is what the log says. */
function xpTodayStats(){
  const mine = me()?.id;
  const earned = (state.xpLog || [])
    .filter(e => e.by === mine && String(e.at).slice(0, 10) === TODAY_ISO)
    .reduce((n, e) => n + (Number(e.amount) || 0), 0);
  const todos = dayTodos(TODAY_ISO, mine).length;
  const systems = (state.routineItems || []).length;
  const goals = [...goalsOf(mine), ...sharedGoals()].filter(belongsOnFocusBoard).length;
  const possible = todos * xpFor('todo') + systems * xpFor('system') + goals * xpFor('goal') + 30;
  return { earned, possible: Math.max(possible, earned), left: Math.max(0, possible - earned) };
}
/** The last seven days, oldest first: done, missed, open (today), or empty. */
function streakWeek(uid){
  const out = [];
  for (let n = 6; n >= 0; n--){
    const day = isoDaysAgo(n);
    const list = dayTodos(day, uid);
    const done = list.length > 0 && list.every(t => t.done);
    const d = new Date(TODAY); d.setDate(d.getDate() - n);
    out.push({
      day, label: d.toLocaleDateString('en-GB', { weekday: 'short' }).slice(0, 2),
      state: done ? 'done' : (n === 0 ? 'open' : (list.length ? 'missed' : 'empty')),
      today: n === 0
    });
  }
  return out;
}
function streakLine(run, todayDone){
  if (todayDone){
    if (run >= 100) return '100 days and counting. Legendary.';
    if (run >= 30) return 'A whole month. That is a habit now.';
    if (run >= 14) return 'Two weeks without a miss.';
    if (run >= 7) return 'One full week locked in.';
    if (run >= 3) return 'Three days straight. Keep it going.';
    return 'Day done. See you tomorrow.';
  }
  if (run > 0) return 'What a streak! Finish today to keep it going.';
  return 'Tick off everything today to start a streak.';
}

function profileStats(p){
  const rooms = (state.rooms || []).length;
  const people = Math.max(0, (state.members || []).filter(m => m.id !== p?.id).length);
  const plan = (p?.id === me()?.id ? (state.billing?.plan || p?.plan) : p?.plan) || 'free';
  return { rooms, people, plan };
}
function profileOverview(p){
  const mine = p?.id === me()?.id;
  const goalsDone = (state.goals || []).filter(g => g.done).length;
  const credits = mine ? (state.billing?.credits ?? p?.credits ?? 0) : (p?.credits ?? 0);
  return {
    streak: computeStreak(p?.id),
    credits, goalsDone,
    level: levelOf(p?.id),
    xp: xpOf(p?.id),
    myl: mylOf(p?.id)
  };
}

