/** Family behind a profile: the live theme for yourself, their saved theme for others. */
function profileFam(p, self){
  const t = self
    ? (document.documentElement.getAttribute('data-theme') || 'light')
    : (p?.theme || 'light');
  return THEME_FAMILIES.find(f => f.light === t || f.dark === t) || THEME_FAMILIES[0];
}
/** Snapchat-style cover gradient derived from the profile's theme family (DB-backed). */
function coverGradient(p, self){
  const fam = profileFam(p, self);
  const c = fam.swatch;
  if (fam.id === 'neutral'){
    return `linear-gradient(135deg,#6366F1 0%,#8B5CF6 48%,#EC4899 100%)`;
  }
  return `linear-gradient(135deg, ${c} 0%, color-mix(in srgb, ${c} 60%, #7C3AED) 58%, color-mix(in srgb, ${c} 35%, #0EA5E9) 100%)`;
}
/* ---- Editable cover (own choice; DB-backed via space-meta; falls back to theme) ---- */
const COVER_GRADIENTS = [
  'linear-gradient(135deg,#6366F1,#EC4899)',
  'linear-gradient(135deg,#0EA5E9,#22D3EE)',
  'linear-gradient(135deg,#F97316,#EF4444)',
  'linear-gradient(135deg,#10B981,#34D399)',
  'linear-gradient(135deg,#8B5CF6,#6366F1)',
  'linear-gradient(160deg,#0F172A,#334155)'
];
const COVER_COLORS = ['#111827','#EF4444','#F59E0B','#10B981','#3B82F6','#8B5CF6','#EC4899','#64748B'];
function getCover(id){ return (state.covers || {})[id] || ''; }
function computeCovers(rows){
  const map = {};
  rows.slice().sort(byTimeAsc).forEach(r => {
    if (r.payload.style != null){ if (r.payload.style) map[r.from_id] = r.payload.style; else delete map[r.from_id]; }
  });
  return map;
}
async function setCover(style){
  state.covers = state.covers || {};
  if (style) state.covers[me().id] = style; else delete state.covers[me().id];
  await spaceInsert({ msg_kind: 'cover', style: style || '' }, 'cover');
  renderAll();
}
/** Full CSS `background` value for a profile's cover: their saved choice, else the theme gradient. */
function coverStyle(p, self){
  return getCover(p?.id) || coverGradient(p, self);
}
