async function sendMyl(){
  if (!FEATURES.wallet) return;
  const to = state.walletTo;
  const amt = Math.floor(Number(($('#wal-amount') || {}).value || 0));
  const note = (($('#wal-note') || {}).value || '').trim();
  if (!to){ toast('Pick who it goes to'); return; }
  if (!(amt > 0)){ toast('Enter an amount'); return; }
  if (amt > mylOf()){ toast('More than you have'); return; }
  const { error } = await spaceInsert(
    { msg_kind: 'myl', mtype: 'send', to, amount: amt, note }, 'sent');
  if (error){ notify(errMsg(error)); return; }
  notify(`Sent ${fmtMyl(amt)} to ${uname(profileById(to))}`);
  state.walletView = 'main';
  renderAll();
  syncMobileTopBar('today');
}

const NOTIF_PREF_KEY = 'mylo:notifPrefs';
const NOTIF_KINDS = [
  { id: 'challenge', label: 'Game challenges',  d: 'When someone starts a game with you' },
  { id: 'turn',      label: 'Your move',        d: 'When a game is waiting on you' },
  { id: 'cheer',     label: 'Cheers',           d: 'When someone celebrates your goal' },
  { id: 'shared',    label: 'Shared goals',     d: 'When a goal is shared into the room' },
  { id: 'join',      label: 'Join requests',    d: 'Owners and admins only' },
  { id: 'challenge', label: 'Challenges',       d: 'When someone dares you to something' },
  { id: 'money',     label: '$MYL',             d: 'When someone sends you tokens' },
  { id: 'milestone', label: 'Milestones',       d: 'Invitations to join one' },
  { id: 'message',   label: 'Messages',         d: 'New messages you have not read' }
];
function notifPrefs(){
  try{
    const raw = JSON.parse(localStorage.getItem(NOTIF_PREF_KEY) || '{}');
    const out = {};
    NOTIF_KINDS.forEach(k => { out[k.id] = raw[k.id] !== false; });   // on unless turned off
    return out;
  }catch(_){
    return Object.fromEntries(NOTIF_KINDS.map(k => [k.id, true]));
  }
}
function setNotifPref(id, on){
  const p = notifPrefs();
  p[id] = !!on;
  try{ localStorage.setItem(NOTIF_PREF_KEY, JSON.stringify(p)); }catch(_){}
  updateNotifBadge();
}

/* ---------- the service worker ----------
   Registered for notifications, not for offline caching. iOS Safari has never
   implemented `new Notification(...)`, in a tab or in an installed PWA, so the
   registration's showNotification() is the only route that reaches an iPhone. */
let swReg = null;
async function registerSW(){
  if (!('serviceWorker' in navigator)) return null;
  if (swReg) return swReg;
  try{
    swReg = await navigator.serviceWorker.register('sw.js', { scope: './' });
    await navigator.serviceWorker.ready;
    return swReg;
  }catch(err){
    console.warn('sw register failed', err);
    return null;
  }
}
/* One door for every alert. Prefers the worker (works everywhere including iOS),
   falls back to the constructor for older desktop browsers with no worker. */
async function showAlert(title, opts = {}){
  const body = opts.body || '';
  const tag = opts.tag;
  try{
    const reg = swReg || await registerSW();
    if (reg && reg.active){
      reg.active.postMessage({ type: 'notify', title, body, tag, url: opts.url || '/' });
      return true;
    }
    if (reg && reg.showNotification){
      await reg.showNotification(title, {
        body, tag, icon: 'assets/icon-192.png', badge: 'assets/icon-192.png',
        data: { url: opts.url || '/' }
      });
      return true;
    }
  }catch(_){}
  try{
    const note = new Notification(title, {
      body, tag, icon: 'assets/icon-192.png', badge: 'assets/icon-192.png'
    });
    note.onclick = () => { try{ window.focus(); }catch(_){} openNotifSheet(); note.close(); };
    return true;
  }catch(_){ return false; }
}
/* iOS only delivers web notifications to an installed app, so it is worth
   knowing whether this is running from the Home Screen. */
function isStandalone(){
  return window.matchMedia?.('(display-mode: standalone)')?.matches
      || window.navigator.standalone === true;
}
function isIOS(){
  return /iPad|iPhone|iPod/.test(navigator.userAgent)
      || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

/* Park the push subscription where a sender can find it. Without a VAPID key in
   config there is nothing to subscribe to, so this quietly does nothing rather
   than throwing on every launch. */
async function syncPushSubscription(){
  const key = CFG.vapidPublicKey;
  if (!key || !me()) return;
  const reg = swReg || await registerSW();
  if (!reg || !reg.pushManager) return;
  try{
    let sub = await reg.pushManager.getSubscription();
    if (!sub){
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlB64ToUint8(key)
      });
    }
    const json = sub.toJSON();
    await spaceInsert({
      msg_kind: 'push', mtype: 'sub',
      endpoint: json.endpoint,
      p256dh: json.keys?.p256dh || '',
      auth: json.keys?.auth || '',
      ua: navigator.userAgent.slice(0, 120)
    }, '·');
  }catch(err){ console.warn('push subscribe failed', err); }
}
function urlB64ToUint8(base64){
  const pad = '='.repeat((4 - base64.length % 4) % 4);
  const raw = atob((base64 + pad).replace(/-/g, '+').replace(/_/g, '/'));
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

/* ---------- alerts ----------
   The list was only ever a list: nothing left the tab. This asks the browser for
   permission once, then raises a real system notification (plus the in-app sound) for
   anything new that arrives while you are not looking at it. */
const ALERT_KEY = 'mylo:alerts';
const ALERT_FIRED_KEY = 'mylo:alertsFired';
function alertsOn(){
  try{ return localStorage.getItem(ALERT_KEY) === '1'; }catch(_){ return false; }
}
function alertsSupported(){ return typeof Notification !== 'undefined'; }
function alertsState(){
  if (!alertsSupported()) return 'unsupported';
  if (Notification.permission === 'denied') return 'blocked';
  if (!alertsOn() || Notification.permission !== 'granted') return 'off';
  return 'on';
}
async function setAlerts(on){
  if (!on){
    try{ localStorage.setItem(ALERT_KEY, '0'); }catch(_){}
    renderAll();
    return;
  }
  if (!alertsSupported()){ toast('This browser has no alerts'); renderAll(); return; }
  let perm = Notification.permission;
  if (perm === 'default'){
    try{ perm = await Notification.requestPermission(); }catch(_){ perm = 'denied'; }
  }
  if (perm !== 'granted'){
    toast(perm === 'denied' ? 'Alerts are blocked in your browser settings' : 'Alerts not allowed');
    try{ localStorage.setItem(ALERT_KEY, '0'); }catch(_){}
    renderAll();
    return;
  }
  try{ localStorage.setItem(ALERT_KEY, '1'); }catch(_){}
  // mark everything current as already alerted, so turning it on is not a burst
  notifItems().forEach(n => alertFired(n.id, true));
  toast('Alerts on');
  renderAll();
}
function alertFired(id, mark){
  let set;
  try{ set = new Set(JSON.parse(localStorage.getItem(ALERT_FIRED_KEY) || '[]')); }
  catch(_){ set = new Set(); }
  if (!mark) return set.has(id);
  set.add(id);
  try{ localStorage.setItem(ALERT_FIRED_KEY, JSON.stringify([...set].slice(-300))); }catch(_){}
  return true;
}
/* A phone notification gets one glance. "Your move on Scrabble" beats
   "Your move / Scrabble vs abeo" split across two lines nobody reads. */
function pushTitle(n){
  if (n.kind === 'turn'){
    const game = String(n.body || '').split(' vs ')[0].trim();
    return game ? `Your move on ${game}` : 'Your move';
  }
  return n.title;
}
function pushBody(n){
  if (n.kind === 'turn'){
    const who = String(n.body || '').split(' vs ')[1];
    return who ? `Playing ${who.trim()}` : '';
  }
  return n.body || '';
}
/** Fire anything new. Safe to call as often as you like — each id alerts once. */
function pumpAlerts(){
  updateNotifBadge();
  if (alertsState() !== 'on') return;
  const fresh = notifItems().filter(n => !alertFired(n.id));
  if (!fresh.length) return;
  /* You are in the app, looking at it: it would be telling you about something
     already on your screen. Count them as seen, so they do not all go off at
     once the moment you leave. */
  if (document.visibilityState === 'visible' && document.hasFocus()){
    fresh.forEach(n => alertFired(n.id, true));
    return;
  }
  fresh.slice(0, 3).forEach(n => {
    alertFired(n.id, true);
    showAlert(pushTitle(n), { body: pushBody(n), tag: n.id });
  });
  fresh.slice(3).forEach(n => alertFired(n.id, true));
  try{ playMessageSound('recv'); }catch(_){}
}

