/** Instagram groups by age; so does this. */
function notifBucket(at){
  const h = (Date.now() - new Date(at)) / 3600000;
  if (h < 24) return 'Today';
  if (h < 168) return 'This week';
  return 'Earlier';
}
function vNotifPage(){
  if (state.notifView === 'settings') return vNotifSettings();
  const items = notifItems();
  const groups = [];
  items.forEach(n => {
    const b = notifBucket(n.at);
    const last = groups[groups.length - 1];
    if (last && last.label === b) last.items.push(n);
    else groups.push({ label: b, items: [n] });
  });
  return `
    <div class="np-page">
      ${items.length
        ? groups.map(g => `<div class="np-sec">${esc(g.label)}</div>
            <div class="np-list">${g.items.map(notifRowHTML).join('')}</div>`).join('')
        : `<div class="np-empty">
             <span class="np-empty-ic" aria-hidden="true">
               <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9"/><path d="M10 20a2 2 0 0 0 4 0"/></svg>
             </span>
             <span class="np-empty-t">No notifications yet</span>
             <span class="np-empty-d">Game challenges, cheers and shared goals land here.</span>
           </div>`}
    </div>`;
}
function vNotifSettings(){
  const prefs = notifPrefs();
  const st = alertsState();
  const alertCopy = {
    on: 'On — alerts reach you even when Mylo is in the background.',
    off: 'Off — nothing leaves this tab.',
    blocked: 'Blocked in your browser settings. Allow notifications for this site, then come back.',
    unsupported: 'This browser cannot show alerts.'
  }[st];
  return `
    <div class="np-page">
      <div class="nset-alert ${st === 'on' ? 'is-on' : ''}">
        <label class="nset-row">
          <span class="nset-copy">
            <span class="nset-t">Alerts on this device</span>
            <span class="nset-d">${esc(alertCopy)}</span>
          </span>
          <input type="checkbox" class="nset-sw" data-alerts-toggle ${st === 'on' ? 'checked' : ''} ${st === 'unsupported' || st === 'blocked' ? 'disabled' : ''}>
          <span class="nset-track" aria-hidden="true"></span>
        </label>
      </div>
      ${isIOS() && !isStandalone() ? `<div class="nset-ios">
        <span class="nset-ios-t">iPhone needs Mylo on your Home Screen</span>
        <span class="nset-ios-d">Apple only delivers notifications to an installed app — never to a Safari tab. Tap Share, then <b>Add to Home Screen</b>, and open Mylo from there.</span>
      </div>` : ''}
      <p class="np-note">Choose what reaches you. Everything is on by default.</p>
      <div class="nset-list">
        ${NOTIF_KINDS.map(k => `
          <label class="nset-row">
            <span class="nset-copy">
              <span class="nset-t">${esc(k.label)}</span>
              <span class="nset-d">${esc(k.d)}</span>
            </span>
            <input type="checkbox" class="nset-sw" data-notif-pref="${esc(k.id)}" ${prefs[k.id] ? 'checked' : ''}>
            <span class="nset-track" aria-hidden="true"></span>
          </label>`).join('')}
      </div>
      <button type="button" class="np-clear" data-notif-clear>Clear all notifications</button>
    </div>`;
}
/* ---------- Add to home screen ----------
   Android/Chrome fires beforeinstallprompt and we can trigger the real dialog.
   iOS Safari never does, so it gets the Share -> Add to Home Screen walkthrough. */
let deferredInstall = null;
const INSTALL_KEY = 'mylo:installPrompted';
function isStandalone(){
  return window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
}
function isIOS(){
  return /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
}
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  deferredInstall = e;
});
function maybeShowInstallPrompt(){
  if (isStandalone()) return;
  try{ if (localStorage.getItem(INSTALL_KEY) === '1') return; }catch(_){}
  if (!deferredInstall && !isIOS()) return;
  setTimeout(openInstallSheet, 1400);
}
function dismissInstall(){
  try{ localStorage.setItem(INSTALL_KEY, '1'); }catch(_){}
  closeSheets();
}
function openInstallSheet(){
  if (isStandalone()) return;
  let sheet = $('#install-sheet');
  if (!sheet){
    sheet = document.createElement('div');
    sheet.className = 'sheet sheet-sm';
    sheet.id = 'install-sheet';
    document.body.appendChild(sheet);
  }
  const ios = isIOS();
  sheet.innerHTML = `<div class="sheet-grab"></div>
    <div class="install-hero">
      <img class="install-mark" src="assets/icon-192.png?v=20260906g" alt="">
      <h3>Keep Mylo one tap away</h3>
      <p>Add it to your home screen and it opens full screen, like an app.</p>
    </div>
    ${ios
      ? `<ol class="install-steps">
           <li><span class="install-step-n">1</span> Tap the <b>Share</b> button in Safari's toolbar</li>
           <li><span class="install-step-n">2</span> Scroll and choose <b>Add to Home Screen</b></li>
           <li><span class="install-step-n">3</span> Tap <b>Add</b> - done</li>
         </ol>`
      : `<div class="install-steps-note">One tap and it's installed. No app store.</div>`}
    <div class="sheet-actions">
      <button class="btn-secondary" data-install-later>Not now</button>
      ${ios ? '' : '<button class="btn-primary" data-install-go>Add to home screen</button>'}
    </div>`;
  openSheet('#install-sheet');
}
async function runInstall(){
  if (!deferredInstall){ dismissInstall(); return; }
  try{
    deferredInstall.prompt();
    await deferredInstall.userChoice;
  }catch(_){}
  deferredInstall = null;
  dismissInstall();
}

/* ---------- Journal ----------
   A private diary per person, stored in the space-meta log. Mylo can append to
   today's entry, so "tell Mylo" and "write it down" are the same action. */
function journalToday(){ return todayFocusIso(); }
function computeJournal(rows){
  const mineId = me()?.id;
  const byDay = {};
  rows.filter(r => r.payload.mtype === 'entry' && r.from_id === mineId)
    .sort(byTimeAsc)
    .forEach(r => {
      const day = r.payload.day || r.created_at.slice(0, 10);
      byDay[day] = byDay[day] || { day, parts: [], at: r.created_at };
      byDay[day].parts.push({ id: r.id, text: r.payload.text || r.body || '', at: r.created_at });
      byDay[day].at = r.created_at;
    });
  return Object.values(byDay).sort((a, b) => b.day.localeCompare(a.day));
}
function journalFor(day){
  return (state.journal || []).find(e => e.day === day) || null;
}
async function addJournal(text, day){
  const clean = (text || '').trim();
  if (!clean){ toast('Nothing to write'); return null; }
  const { data, error } = await spaceInsert(
    { msg_kind: 'journal', mtype: 'entry', text: clean, day: day || journalToday() }, clean.slice(0, 80));
  if (error){ notify(errMsg(error)); return null; }
  return data?.id || null;
}
/* Notes: the things you keep, not the things that happened. Same log, own
   kind, private to whoever wrote them. */
function computeNotes(rows){
  const mineId = me()?.id;
  const items = {};
  rows.filter(r => r.payload.mtype === 'add' && r.from_id === mineId).forEach(r => {
    items[r.id] = { id: r.id, text: r.payload.text || r.body || '', at: r.created_at, pinned: false };
  });
  rows.filter(r => r.payload.mtype === 'del' && r.from_id === mineId).forEach(r => { delete items[r.payload.ref]; });
  rows.filter(r => r.payload.mtype === 'pin' && r.from_id === mineId).sort(byTimeAsc).forEach(r => {
    const it = items[r.payload.ref]; if (it) it.pinned = !!r.payload.on;
  });
  return Object.values(items).sort((a, b) => (b.pinned - a.pinned) || (new Date(b.at) - new Date(a.at)));
}
async function addNote(text){
  const clean = (text || '').trim();
  if (!clean){ toast('Nothing to keep'); return null; }
  const { data, error } = await spaceInsert({ msg_kind: 'note', mtype: 'add', text: clean }, clean.slice(0, 80));
  if (error){ notify(errMsg(error)); return null; }
  return data?.id || null;
}
async function deleteNote(id){
  const { error } = await spaceInsert({ msg_kind: 'note', mtype: 'del', ref: id }, '·');
  if (error){ notify(errMsg(error)); return; }
  renderAll();
}
async function pinNote(id, on){
  const { error } = await spaceInsert({ msg_kind: 'note', mtype: 'pin', ref: id, on: !!on }, '·');
  if (error){ notify(errMsg(error)); return; }
  renderAll();
}
function openJournal(){
  state.appView = 'journal';
  goMobileScreen('apps');
  renderAll();
}
function jrClock(iso){
  try{
    return new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  }catch(_){ return ''; }
}
function vJournal(){
  const days = state.journal || [];
  const today = journalToday();
  const todays = journalFor(today);
  const older = days.filter(d => d.day !== today);
  const entryHTML = (part) => `
    <div class="jr-node">
      <span class="jr-time">${esc(jrClock(part.at))}</span>
      <div class="jr-body">${myloRichText(part.text)}</div>
    </div>`;
  const tab = state.jrTab === 'notes' ? 'notes' : 'journal';
  const notes = state.notes || [];
  const noteHTML = (n) => `
    <div class="nt-card ${n.pinned ? 'is-pinned' : ''}">
      <div class="nt-body">${myloRichText(n.text)}</div>
      <div class="nt-foot">
        <span class="nt-when">${esc(dayLabelRelative(String(n.at).slice(0, 10)))} &middot; ${esc(jrClock(n.at))}</span>
        <span class="nt-acts">
          <button type="button" class="nt-act ${n.pinned ? 'on' : ''}" data-note-pin="${esc(n.id)}" aria-label="${n.pinned ? 'Unpin' : 'Pin'}"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M14 2l8 8-3 1-1 5-4-4-6 6v-4l6-6-4-4 4-2z"/></svg></button>
          <button type="button" class="nt-act" data-note-copy="${esc(n.id)}" aria-label="Copy"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg></button>
          <button type="button" class="nt-act is-danger" data-note-del="${esc(n.id)}" aria-label="Delete"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
        </span>
      </div>
    </div>`;
  return `
    <div class="jr-page">
      ${miniHead(tab === 'notes' ? 'Notes' : 'Journal', { add: 'data-jr-ask', label: tab === 'notes' ? 'New note' : 'Write' })}
      <div class="jr-tabs" role="tablist">
        <button type="button" class="jr-tab ${tab === 'journal' ? 'on' : ''}" data-jr-tab="journal" role="tab">Journal</button>
        <button type="button" class="jr-tab ${tab === 'notes' ? 'on' : ''}" data-jr-tab="notes" role="tab">Notes</button>
      </div>
      ${tab === 'notes' ? `
      <div class="nt-list">
        ${notes.length ? notes.map(noteHTML).join('')
          : `<div class="jr-blank">Nothing kept yet. A link, a number, a line you want to find again.</div>`}
      </div>` : `
      <div class="jr-datebar">
        <span class="jr-date">${esc(new Date(today + 'T00:00:00').toLocaleDateString([], { weekday: 'long', month: 'short', day: 'numeric' }))}</span>
      </div>

      <div class="jr-sheet">
        ${todays && todays.parts.length
          ? `<div class="jr-line">${todays.parts.map(entryHTML).join('')}</div>`
          : `<div class="jr-blank">Nothing yet today. Write a line below, or <button type="button" class="jr-blank-link" data-jr-mylo>tell Mylo</button> and it will.</div>`}

        ${older.length ? older.map(d => `
          <div class="jr-past">
            <div class="jr-past-day">${esc(dayLabelRelative(d.day))}</div>
            <div class="jr-line">${d.parts.map(entryHTML).join('')}</div>
          </div>`).join('') : ''}
      </div>`}

      <div class="jr-dock">
        <button type="button" class="jr-dock-plus" data-jr-ask aria-label="Write">
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>
        </button>
        <input id="jr-in" class="jr-dock-in" placeholder="${tab === 'notes' ? 'Keep something&hellip;' : 'Start typing&hellip;'}" autocomplete="off"
          enterkeyhint="done" maxlength="4000" style="font-size:16px">
        <button type="button" class="jr-dock-save" id="jr-save" aria-label="Save">
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h15M13 6l6 6-6 6"/></svg>
        </button>
      </div>
    </div>`;
}
async function saveJournalFromView(){
  const el = document.querySelector('#m-apps #jr-in') || $('#jr-in');
  const text = (el?.value || '').trim();
  if (!text){ toast('Write something first'); return; }
  const id = state.jrTab === 'notes' ? await addNote(text) : await addJournal(text);
  if (!id) return;
  if (el) el.value = '';
  renderAll();
  toast(state.jrTab === 'notes' ? 'Kept' : 'Saved to your journal');
}

/* ---------- WeSub ----------
   Who pays for what, and what each person owes. Amounts are plain numbers so
   the room can use whatever currency it already thinks in. */
const SUB_PRESETS = [
  { name: 'Netflix',      colour: '#E50914' },
  { name: 'Prime Video',  colour: '#00A8E1' },
  { name: 'Spotify',      colour: '#1DB954' },
  { name: 'Claude',       colour: '#D97757' },
  { name: 'ChatGPT',      colour: '#10A37F' },
  { name: 'CapCut',       colour: '#000000' },
  { name: 'YouTube',      colour: '#FF0000' },
  { name: 'iCloud',       colour: '#3B82F6' }
];
function computeSubs(rows){
  const items = {};
  rows.filter(r => r.payload.mtype === 'sub').forEach(r => {
    items[r.id] = {
      id: r.id, name: r.payload.name || 'Subscription',
      cost: Number(r.payload.cost) || 0,
      payer: r.payload.payer || r.from_id,
      members: Array.isArray(r.payload.members) ? r.payload.members : [],
      colour: r.payload.colour || '#8A8A8A',
      by: r.from_id, deleted: false, created_at: r.created_at
    };
  });
  rows.filter(r => r.payload.mtype === 'subdel').sort(byTimeAsc).forEach(ev => {
    const it = items[ev.payload.ref];
    if (it && (ev.from_id === it.by || ['owner','admin'].includes(myRole(ev.from_id)))) it.deleted = true;
  });
  return Object.values(items).filter(i => !i.deleted).sort(byTimeAsc);
}
/** What each person owes the payer, once every split is added up. */
function subBalances(){
  const bal = {};
  (state.subs || []).forEach(s => {
    const n = s.members.length || 1;
    const share = s.cost / n;
    s.members.forEach(id => {
      if (id === s.payer) return;
      bal[id] = bal[id] || {};
      bal[id][s.payer] = (bal[id][s.payer] || 0) + share;
    });
  });
  return bal;
}
const money = n => (Math.round(n * 100) / 100).toLocaleString(undefined, { maximumFractionDigits: 2 });
