function challengeCardHTML(c){
  const K = challengeKind(c.kind);
  const mine = c.by === me()?.id;
  const other = profileById(mine ? c.to : c.by);
  const n = challengeProgress(c);
  const pct = Math.min(100, Math.round(n / c.target * 100));
  const live = challengeLive(c);
  const left = Math.max(0, challengeEnds(c) - Date.now());
  const hrs = Math.round(left / 3600000);
  const when = !live && !c.done ? 'Expired' : (hrs > 48 ? `${Math.round(hrs / 24)}d left` : `${hrs}h left`);
  return `<div class="ch-card ${c.done ? 'is-done' : ''} ${!live && !c.done ? 'is-dead' : ''}" style="--cc:${esc(K.colour)}">
    <div class="ch-top">
      <span class="ch-face">${avatarMark(other, 'avatar-todo')}</span>
      <div class="ch-copy">
        <div class="ch-t">${esc(mine ? `${uname(other)} must ${K.label.toLowerCase()}` : `${uname(other)} dared you`)}</div>
        <div class="ch-d">${c.target} ${esc(K.unit)} &middot; ${esc((CHALLENGE_WINDOWS.find(w => w.id === c.window) || {}).label || '')}${c.stake ? ` &middot; ${esc(fmtMyl(c.stake))}` : ''}</div>
      </div>
      ${c.done ? '<span class="ch-badge">Won</span>' : `<span class="ch-when">${esc(when)}</span>`}
    </div>
    ${c.note ? `<div class="ch-note">${esc(c.note)}</div>` : ''}
    <div class="ch-bar"><i style="width:${pct}%"></i></div>
    <div class="ch-foot">
      <span class="ch-n">${n} of ${c.target}</span>
      ${!c.done && live && !mine && n >= c.target
        ? `<button type="button" class="ch-claim" data-ch-claim="${esc(c.id)}">Claim it</button>` : ''}
      ${mine && !c.done ? `<button type="button" class="ch-drop" data-ch-drop="${esc(c.id)}">Cancel</button>` : ''}
    </div>
  </div>`;
}
