/* ---------- Vibe ----------
   A feed for the room and nobody else: quotes, mostly, and the odd thought.
   Rows live in the space log like everything else, so only the people in the
   room can read them; there is no public anything here. A post can be liked,
   copied as text, or taken away as a picture with the Mylo mark on it. */
const VIBE_MAX = 280;
function computeVibe(rows){
  const posts = {};
  rows.filter(r => r.payload.mtype === 'post').forEach(r => {
    posts[r.id] = {
      id: r.id, by: r.from_id, text: r.payload.text || r.body || '', at: r.created_at,
      img: r.payload.img || '', w: Number(r.payload.w) || 0, h: Number(r.payload.h) || 0,
      likes: new Set(), deleted: false
    };
  });
  rows.filter(r => r.payload.mtype === 'like').sort(byTimeAsc).forEach(r => {
    const p = posts[r.payload.ref]; if (!p) return;
    if (r.payload.on === false) p.likes.delete(r.from_id); else p.likes.add(r.from_id);
  });
  // an edit rewrites the words but keeps the post, its likes and its replies
  rows.filter(r => r.payload.mtype === 'edit').sort(byTimeAsc).forEach(r => {
    const p = posts[r.payload.ref];
    if (p && r.from_id === p.by){ p.text = r.payload.text || p.text; p.edited = true; }
  });
  rows.filter(r => r.payload.mtype === 'del').forEach(r => {
    const p = posts[r.payload.ref];
    if (p && (r.from_id === p.by || ['owner','admin'].includes(myRole(r.from_id)))) p.deleted = true;
  });
  // replies, oldest first, the way a conversation reads
  const replies = {};
  rows.filter(r => r.payload.mtype === 'reply').sort(byTimeAsc).forEach(r => {
    (replies[r.payload.ref] = replies[r.payload.ref] || []).push({
      id: r.id, by: r.from_id, text: r.payload.text || r.body || '', at: r.created_at, deleted: false
    });
  });
  rows.filter(r => r.payload.mtype === 'repdel').forEach(r => {
    Object.values(replies).forEach(list => list.forEach(x => {
      if (x.id === r.payload.ref && (r.from_id === x.by || ['owner','admin'].includes(myRole(r.from_id)))) x.deleted = true;
    }));
  });
  Object.keys(posts).forEach(id => {
    posts[id].replies = (replies[id] || []).filter(x => !x.deleted);
  });
  return Object.values(posts).filter(p => !p.deleted).sort((a, b) => new Date(b.at) - new Date(a.at));
}
function openVibe(){
  state.appView = 'vibe';
  goMobileScreen('apps');
  renderAll();
}
function vibeShareText(v){
  if (!v) return '';
  const who = profileById(v.by);
  return `\u201C${v.text}\u201D \u2014 @${who?.username || 'mylo'}`;
}
function vibeWhen(iso){
  const d = Date.now() - +new Date(iso);
  const m = Math.floor(d / 60000);
  if (m < 1) return 'now';
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const days = Math.floor(h / 24);
  if (days < 7) return `${days}d`;
  return new Date(iso).toLocaleDateString([], { month: 'short', day: 'numeric' });
}
function vibePostHTML(v){
  const p = profileById(v.by);
  const mid = me()?.id;
  const liked = v.likes.has(mid);
  const mine = v.by === mid;
  const ratio = v.img && v.w && v.h ? Math.max(.6, Math.min(1.9, v.w / v.h)) : 0;
  return `<article class="vb-post" data-vibe-id="${esc(v.id)}">
    <span class="vb-rail" aria-hidden="true"><span class="vb-face">${avatarMark(p, 'avatar-40')}</span><i></i></span>
    <div class="vb-main">
      <div class="vb-head">
        ${nameWithBadge(planOf(p), `<span class="vb-name">${esc(uname(p))}</span>`, p)}
        <span class="vb-handle">@${esc(p?.username || '')}</span>
        <span class="vb-dot">&middot;</span>
        <span class="vb-when">${esc(vibeWhen(v.at))}</span>
      </div>
      ${v.text ? `<div class="vb-text">${myloRichText(v.text)}${v.edited ? '<i class="vb-edited">edited</i>' : ''}</div>` : ''}
      ${v.img ? `<button type="button" class="vb-img" data-open-image="${esc(v.img)}" style="${ratio ? `aspect-ratio:${ratio}` : ''}">
        <img src="${esc(v.img)}" alt="" loading="lazy" draggable="false">
      </button>` : ''}
      <div class="vb-acts">
        <button type="button" class="vb-act ${liked ? 'is-on' : ''}" data-vibe-like="${esc(v.id)}" aria-label="Like">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="${liked ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round"><path d="M12 20.3 4.6 13a4.4 4.4 0 0 1 6.2-6.2l1.2 1.2 1.2-1.2a4.4 4.4 0 0 1 6.2 6.2z"/></svg>
          ${v.likes.size ? `<b>${v.likes.size}</b>` : ''}
        </button>
        <button type="button" class="vb-act" data-vibe-open="${esc(v.id)}" aria-label="Replies">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M20.5 11.5a7.5 7.5 0 0 1-10.9 6.7L4.5 19.5l1.3-5a7.5 7.5 0 1 1 14.7-3z"/></svg>
          ${v.replies?.length ? `<b>${v.replies.length}</b>` : ''}
        </button>
        ${!mine && FEATURES.wallet ? `<button type="button" class="vb-act" data-vibe-tip="${esc(v.id)}" aria-label="Tip $MYL">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M14.2 9.4c-.5-.8-1.3-1.2-2.2-1.2-1.3 0-2.2.7-2.2 1.7 0 2.4 4.7 1.3 4.7 3.9 0 1.1-1 1.9-2.4 1.9-1 0-1.9-.4-2.4-1.2"/><path d="M12 6.6v10.8"/></svg>
        </button>` : ''}
        <button type="button" class="vb-act is-more" data-vibe-menu="${esc(v.id)}" aria-label="More">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><circle cx="5.5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="18.5" cy="12" r="1.6"/></svg>
        </button>
      </div>
      ${v.replies?.length ? `<button type="button" class="vb-replies" data-vibe-open="${esc(v.id)}">
        ${v.replies.slice(-3).map(r => `<span class="vb-rep-face">${avatarMark(profileById(r.by), 'avatar-todo')}</span>`).join('')}
        <span>${v.replies.length} ${v.replies.length === 1 ? 'reply' : 'replies'}</span>
      </button>` : ''}
    </div>
  </article>`;
}
