async function startGame(kind, invitees){
  const def = gameDefs()[kind];
  if (!def){ toast('Unknown game'); return; }
  if (busyLocked() || state._startingGame) return;
  state._startingGame = true;
  markBusy(true);
  try{
    const chat = await ensureMessageChat();
    if (!chat){ toast('Open a chat first'); return; }
    closeSheets();
    goMobileScreen('chat');
    const picked = Array.isArray(invitees) && invitees.length
      ? invitees
      : otherMembers().slice(0, (def.maxPlayers || 2) - 1).map(p => p.id);
    if (!picked.length){ toast('Needs at least one other person'); return; }
    const peer = profileById(picked[0]);
    let seed;
    if (def.group){
      seed = def.create([me().id, ...picked].slice(0, def.maxPlayers || 4));
    } else {
      seed = def.create();
    }
    const stake = Math.max(0, Number(state._gameStake) || 0);
    if (stake > mylOf()){ toast('That is more than you have'); return; }
    const payload = {
      game: kind,
      gameId: MyloGames.uid(),
      host_id: me().id,
      guest_id: peer?.id || null,
      state: seed,
      over: false,
      winner: null,
      stake
    };
    await insertMessage({ kind: 'text', body: def.name, payload });
    if (stake > 0) await putUpStake(payload.gameId, stake);
    state._gameFocus = payload.gameId;
    openGameOverlay(payload.gameId);
  }catch(e){ notify(errMsg(e)); }
  finally{
    state._startingGame = false;
    markBusy(false);
  }
}

/** Append the next state as a new message. */
async function pushGameState(pl, nextState, extra = {}){
  const def = gameDefs()[pl.game];
  const over = !!extra.over || (def && def.over(nextState));
  // Bot games are local: mutate in place, then let the bot answer.
  if (pl.bot){
    state._botGame = { ...pl, state: nextState, over, winner: extra.winner || null };
    renderGameOverlay();
    if (!over && botToMove(state._botGame)) setTimeout(runBotReply, 520);
    return state._botGame;
  }
  const seat = gameSeat(pl);
  const payload = {
    ...pl,
    state: nextState,
    over,
    winner: extra.winner || (over ? (extra.winner || null) : null),
    guest_id: pl.guest_id || (seat === 'guest' ? me().id : pl.guest_id),
    note: extra.note || null
  };
  await insertMessage({ kind: 'text', body: def ? def.name : 'Game', payload, silent: true });
  return payload;
}

/* ---- in-chat card ---- */
function gameCardHTML(m, pl){
  const def = gameDefs()[pl.game];
  if (!def) return '';
  if (!gameStateOk(pl)){
    return `<div class="msg-card game-card-msg is-stale">
      <div class="msg-card-kicker">${esc(def.name)}</div>
      <div class="msg-card-sub">From an older version &mdash; start a new game.</div>
    </div>`;
  }
  try{
    const mine = myTurn(pl);
    const status = pl.over
      ? (pl.winner ? `${esc(gameSeatName(pl, pl.winner))} won` : def.summary(pl.state))
      : def.summary(pl.state);
    const mini = pl.game === 'chess' ? chessMiniHTML(pl.state)
      : pl.game === 'rush' ? rushMiniHTML(pl.state)
      : pl.game === 'scrabble' ? scrabbleMiniHTML(pl.state)
      : pl.game === 'eights' ? cardsMiniHTML(pl.state)
      : '';
    return `<div class="msg-card game-card-msg" style="--gc:${esc(def.color)}">
      <div class="game-msg-head">
        <span class="game-msg-ic">${def.icon}</span>
        <div>
          <div class="msg-card-kicker">${esc(def.name)}</div>
          <div class="msg-card-sub">${esc(status)}</div>
        </div>
      </div>
      ${mini}
      ${potHTML(pl)}
      ${headToHeadHTML(pl)}
      <button type="button" class="game-open-btn ${mine ? 'is-turn' : ''}" data-open-game="${esc(pl.gameId)}">
        ${pl.over ? 'View board' : (mine ? 'Your move' : 'Open')}
      </button>
    </div>`;
  }catch(err){
    console.warn('gameCardHTML', pl.game, err);
    return `<div class="msg-card game-card-msg">
      <div class="msg-card-kicker">${esc(def.name)}</div>
      <div class="msg-card-sub">Tap to open</div>
      <button type="button" class="game-open-btn" data-open-game="${esc(pl.gameId)}">Open</button>
    </div>`;
  }
}

function chessMiniHTML(st){
  const C = MyloGames.chess;
  let cells = '';
  for (let i = 0; i < 64; i++){
    const [r, c] = C.rc(i);
    const dark = (r + c) % 2 === 1;
    const p = st.board[i];
    cells += `<span class="cmini-sq ${dark ? 'd' : ''}">${p ? C.pieceSVG(p) : ''}</span>`;
  }
  return `<div class="chess-mini" aria-hidden="true">${cells}</div>`;
}
function scrabbleMiniHTML(st){
  const scores = (st.players || []).map(id => st.scores?.[id] || 0).join(' · ');
  const bag = Array.isArray(st.bag) ? st.bag.length : 0;
  return `<div class="sc-mini">
    <span class="sc-mini-board" aria-hidden="true">Scrabble</span>
    <span class="sc-mini-scores">${esc(scores || '0 · 0')}</span>
    <span class="sc-mini-bag">${bag} left</span>
  </div>`;
}
function rushMiniHTML(st){
  const R = MyloGames.rush;
  if (!st?.pile?.length || !st.hands) return '';
  const top = st.pile[st.pile.length - 1];
  return `<div class="rush-mini">
    ${rushCardHTML(top)}
    <div class="rush-mini-seats">
      ${(st.players || []).map(id => `<span class="rush-mini-seat ${R.current(st) === id ? 'is-on' : ''}">
        ${avatarMark(profileById(id), 'avatar-rmini')}
        <b>${(st.hands[id] || []).length}</b>
      </span>`).join('')}
    </div>
  </div>`;
}
function cardsMiniHTML(st){
  const E = MyloGames.eights;
  if (!st?.pile?.length || !st.hands) return '';
  const top = st.pile[st.pile.length - 1];
  const hostN = (st.hands.host || []).length;
  const guestN = (st.hands.guest || []).length;
  return `<div class="cards-mini">
    <span class="pcard ${E.isRed(top) ? 'red' : ''}"><b>${top.r}</b><i>${top.s}</i></span>
    <span class="cards-mini-suit">suit ${esc(st.suit || '')}</span>
    <span class="cards-mini-count">${hostN} v ${guestN}</span>
  </div>`;
}

/* ---- playable overlay ---- */
function openGameOverlay(gameId){
  scResetDraft();
  const msg = latestGameMsg(gameId);
  if (!msg){ toast('Game not found'); return; }
  state._gameFocus = gameId;
  const el = $('#game-overlay');
  if (!el) return;
  el.classList.add('on');
  el.setAttribute('aria-hidden', 'false');
  const pl = payloadOf(msg);
  if (pl?.game === 'scrabble') MyloGames?.scrabble?.loadDict?.().catch(() => {});
  renderGameOverlay();
}
function closeGameOverlay(){
  state._scwOpen = false; state._scChip = null; state._scwFocus = null;
  $('#scw-host')?.remove();
  state._gameSel = null;
  const el = $('#game-overlay');
  el?.classList.remove('on');
  el?.setAttribute('aria-hidden', 'true');
  state._gameSel = null;
}
function gamePlayerHTML(pl, seat, sideLabel){
  const id = seat === 'host' ? pl.host_id : pl.guest_id;
  const p = (pl.bot && seat === 'guest') ? null : (id ? profileById(id) : null);
  const isBot = pl.bot && seat === 'guest';
  const active = !pl.over && (pl.game === 'chess'
    ? ((pl.state.turn === 'w') === (seat === 'host'))
    : pl.state.turn === seat);
  return `<div class="gplayer ${active ? 'is-active' : ''}">
    <span class="gplayer-av">${p ? avatarMark(p, 'avatar-gp') : `<span class="gplayer-ghost">${isBot ? '🤖' : '?'}</span>`}</span>
    <span class="gplayer-n">${esc(p ? uname(p) : (isBot ? 'Mylo bot' : 'Waiting'))}</span>
    <span class="gplayer-s">${esc(sideLabel)}</span>
  </div>`;
}
/** Standing record for this game, shown every time a board opens. */
function scoreboardHTML(pl){
  const ids = gamePlayerIds(pl);
  if (ids.length !== 2 || pl.bot) return '';
  return `<div class="scoreboard">${headToHeadHTML(pl, { big: true })}</div>`;
}

/** iMessage-style flourish when a game closes out. */
function gameEndHTML(pl){
  if (!pl.over) return '';
  const mid = me()?.id;
  const w = pl.winner || pl.state?.winner || null;
  const iWon = w && (w === mid || (pl.bot && w === 'host'));
  const drew = !w;
  // Mylo has a face for each of these. An emoji here looked borrowed.
  const art = drew ? 'happy-3' : (iWon ? 'wore-crown' : 'happy');
  const t = drew ? 'Draw' : (iWon ? 'You won!' : `${uname(profileById(w)) || 'They'} won`);
  const sub = drew ? 'Evenly matched.' : (iWon ? 'Nicely done.' : 'Rematch?');
  if (iWon && !state._confettiFor?.[pl.gameId]){
    state._confettiFor = state._confettiFor || {};
    state._confettiFor[pl.gameId] = true;
    try{
      if (window.confetti) setTimeout(() => confetti({
        particleCount: 90, spread: 72, origin: { y: 0.45 }, disableForReducedMotion: true
      }), 120);
    }catch(_){}
  }
  /* A win is the one moment anybody wants to show someone. The card is the
     same picture the streak makes, so a Mylo win is recognisable wherever it
     is posted. Only offered to whoever actually won. */
  const oppId = iWon ? (pl.bot ? null : Object.keys(pl.seats || {}).find(id => id !== mid) || pl.host === mid ? pl.guest : pl.host) : null;
  const opp = oppId ? profileById(oppId) : null;
  const gname = pl.kind ? (gameDefs()[pl.kind]?.name || pl.kind) : 'Mylo';
  return `<div class="game-end" aria-live="polite">
    <div class="game-end-card">
      <img class="game-end-ic" src="${esc(charSrc(art))}" alt="" draggable="false">
      <span class="game-end-t">${esc(t)}</span>
      <span class="game-end-s">${esc(sub)}</span>
      ${iWon ? `<button type="button" class="game-end-dl" data-win-card
        data-win-game="${esc(gname)}" data-win-opp="${esc(pl.bot ? 'the bot' : (opp?.username || ''))}">
        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v11"/><path d="m7 10 5 5 5-5"/><path d="M5 20h14"/></svg>
        Download the card
      </button>` : ''}
    </div>
  </div>`;
}
/* ══════════════════════════════════════════════════════════════════════════
   Scrabble — what did that word mean?

   Half the fun of Scrabble is the words you did not know existed, and the other
   half is not knowing what they mean. A slim tab on the side of the board opens
   every word played this game — yours and theirs — with its meaning. When a new
   word lands, a small chip says so; tap it for the meaning. The next word
   replaces the chip rather than stacking up. None of it sits on the board.

   Meanings come from the free dictionaryapi.dev and are cached for the session.
   Plenty of legal Scrabble words (QI, ZA, XU) are not in an ordinary dictionary;
   those say so rather than pretending.
   ══════════════════════════════════════════════════════════════════════════ */
const SC_DEFS = new Map();              // WORD -> { status, meanings }
function scMoveKey(lw){ return lw ? `${lw.by}|${(lw.words || []).join(',')}|${lw.score}` : ''; }
/** Words played in this game, newest first. Bot games only exist in memory, so
    those are collected as the overlay sees each move. */
function scWordsPlayed(gid){
  const out = [], seen = new Set();
  const take = (lw, at) => {
    if (!lw || lw.passed || lw.swapped || !(lw.words || []).length) return;
    const key = scMoveKey(lw);
    if (seen.has(key)) return;
    seen.add(key);
    lw.words.forEach(w => out.push({ word: String(w).toUpperCase(), by: lw.by, score: lw.score, at }));
  };
  gameMsgs(gid).forEach(m => take(payloadOf(m).state?.lastWord, m.created_at));
  (state._scLog?.[gid] || []).forEach(e => take(e.lw, e.at));
  return out.sort((a, b) => String(b.at).localeCompare(String(a.at)));
}
function syncScWords(gid, pl){
  const lw = pl.state?.lastWord;
  const key = scMoveKey(lw);
  state._scLog = state._scLog || {};
  state._scSeen = state._scSeen || {};
  if (key && !(lw.passed || lw.swapped)){
    const log = (state._scLog[gid] = state._scLog[gid] || []);
    if (!log.some(e => scMoveKey(e.lw) === key)) log.push({ lw, at: new Date().toISOString() });
    // A word arriving while you watch gets the chip. The word that was already
    // on the board when you opened the game does not.
    if (state._scSeen[gid] !== undefined && state._scSeen[gid] !== key){
      const word = String(lw.words[0] || '').toUpperCase();
      state._scChip = { gid, word, by: lw.by };
      clearTimeout(state._scChipTimer);
      state._scChipTimer = setTimeout(() => { state._scChip = null; paintScWords(); }, 9000);
      scLookup(word);
    }
  }
  state._scSeen[gid] = key;
  paintScWords();
}
function scByName(uid){
  if (uid === me()?.id) return 'You';
  if (uid === 'host' || uid === 'bot' || uid === 'guest') return 'Mylo';
  return uname(profileById(uid)) || 'Them';
}
/* dictionaryapi.dev stopped answering altogether — every request times out — so
   meanings never loaded. Wiktionary's REST API answers, allows browser requests,
   and knows far more Scrabble words (QI, ZA, XU). Its definitions are HTML with
   stray <style> blocks inside, so they are parsed, not regex-stripped, and
   entries like "ISO language code" are passed over for a real part of speech. */
const SC_POS_OK = /^(noun|verb|adjective|adverb|interjection|pronoun|preposition|conjunction|numeral|determiner|particle)$/i;
function scCleanDef(html){
  try{
    const doc = new DOMParser().parseFromString(`<div>${html || ''}</div>`, 'text/html');
    doc.querySelectorAll('style, sup, .citation-whole, .h-usage-example, .reference, ul, ol, dl').forEach(n => n.remove());
    return (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
  }catch(_){ return String(html || '').replace(/<[^>]+>/g, '').trim(); }
}
async function scFromWiktionary(W, signal){
  const res = await fetch(`https://en.wiktionary.org/api/rest_v1/page/definition/${encodeURIComponent(W.toLowerCase())}`, { signal });
  if (res.status === 404) return [];
  if (!res.ok) throw new Error('wiktionary ' + res.status);
  const data = await res.json();
  const out = [];
  const sections = (data.en || []).slice().sort((a, b) =>
    Number(SC_POS_OK.test(b.partOfSpeech || '')) - Number(SC_POS_OK.test(a.partOfSpeech || '')));
  for (const sec of sections){
    for (const d of (sec.definitions || [])){
      const text = scCleanDef(d.definition);
      if (!text || text.length < 3) continue;
      out.push({ pos: (sec.partOfSpeech || '').toLowerCase(), text });
      break;                              // one line per part of speech reads best
    }
    if (out.length >= 3) break;
  }
  return out;
}
async function scFromDictApi(W, signal){
  const res = await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(W.toLowerCase())}`, { signal });
  if (!res.ok) return [];
  const data = await res.json();
  const out = [];
  (Array.isArray(data) ? data : []).forEach(entry => (entry.meanings || []).forEach(mn => {
    const d = mn.definitions?.[0]?.definition;
    if (d && out.length < 3) out.push({ pos: mn.partOfSpeech || '', text: d });
  }));
  return out;
}
async function scLookup(word){
  const W = String(word || '').toUpperCase();
  if (!W) return;
  const had = SC_DEFS.get(W);
  // A failed lookup may try again, but not on every repaint — that would loop.
  if (had && !(had.status === 'error' && Date.now() - had.at > 30000)) return;
  SC_DEFS.set(W, { status: 'loading', meanings: [] });
  paintScWords();
  const ctl = new AbortController();
  const kill = setTimeout(() => ctl.abort(), 14000);   // Wiktionary is slow at times, not dead
  try{
    // Both at once; the first one with an actual meaning wins.
    const tries = [scFromWiktionary(W, ctl.signal), scFromDictApi(W, ctl.signal)];
    const meanings = await new Promise(resolve => {
      let left = tries.length;
      tries.forEach(p => p.then(m => {
        if (m && m.length){ resolve(m); return; }
        if (--left === 0) resolve([]);
      }).catch(() => { if (--left === 0) resolve(null); }));
    });
    if (meanings === null) SC_DEFS.set(W, { status: 'error', meanings: [], at: Date.now() });
    else SC_DEFS.set(W, { status: meanings.length ? 'ok' : 'none', meanings });
  }catch(_){
    SC_DEFS.set(W, { status: 'error', meanings: [], at: Date.now() });
  }finally{
    clearTimeout(kill);
    ctl.abort();                          // stop the slower one once we have an answer
  }
  paintScWords();
}
function scDefHTML(word){
  const d = SC_DEFS.get(word);
  if (!d || d.status === 'loading') return `<p class="scw-def is-wait">Looking it up…</p>`;
  if (d.status === 'error') return `<p class="scw-def is-wait">Could not reach the dictionary.</p>`;
  if (d.status === 'none') return `<p class="scw-def is-wait">A legal Scrabble word, but not in the everyday dictionary.</p>`;
  return d.meanings.map(m => `<p class="scw-def">${m.pos ? `<i>${esc(m.pos)}</i> ` : ''}${esc(m.text)}</p>`).join('');
}
/* Painted into its own host on the sheet, not into the board's body — so looking
   a word up never re-renders the board or loses a half-placed move. */
function paintScWords(){
  const gid = state._gameFocus;
  const sheet = $('#game-overlay .game-sheet');
  let host = $('#scw-host');
  const msg = gid && latestGameMsg(gid);
  const isSc = msg && payloadOf(msg).game === 'scrabble';
  if (!sheet || !isSc){ host?.remove(); return; }
  if (!host){
    host = document.createElement('div');
    host.id = 'scw-host';
    sheet.appendChild(host);
  }
  const words = scWordsPlayed(gid);
  const open = !!state._scwOpen;
  if (open) words.slice(0, 20).forEach(w => scLookup(w.word));
  const chip = state._scChip && state._scChip.gid === gid && !open ? state._scChip : null;
  // The Aa button is part of the board's own players row now (scrabbleTableHTML);
  // a tab floating on the edge sat right on top of the rack.
  const btnN = $('.sc-words-btn');
  if (btnN){
    const b = btnN.querySelector('b');
    if (words.length && !b) btnN.insertAdjacentHTML('beforeend', `<b>${words.length}</b>`);
    else if (b) b.textContent = String(words.length);
  }
  host.innerHTML = `
    ${chip ? `<button type="button" class="scw-chip glass" data-scw-word="${esc(chip.word)}">
      <b>${esc(chip.word)}</b><span>${esc(scByName(chip.by))} · what does it mean?</span>
    </button>` : ''}
    ${open ? `<div class="scw-scrim" data-scw-close></div>
    <aside class="scw-drawer" aria-label="Words played">
      <div class="scw-head"><b>Words played</b>
        <button type="button" class="scw-x" data-scw-close aria-label="Close">&times;</button></div>
      <div class="scw-list">
        ${words.map(w => `<div class="scw-item ${state._scwFocus === w.word ? 'is-focus' : ''}" data-scw-item="${esc(w.word)}">
          <div class="scw-word"><b>${esc(w.word)}</b><span>${esc(scByName(w.by))} · ${w.score}</span></div>
          ${scDefHTML(w.word)}
        </div>`).join('')}
      </div>
    </aside>` : ''}`;
  if (open && state._scwFocus){
    host.querySelector(`[data-scw-item="${CSS.escape(state._scwFocus)}"]`)?.scrollIntoView({ block: 'nearest' });
  }
}

function renderGameOverlay(){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  const body = $('#game-body');
  if (!body) return;
  if (!msg){ body.innerHTML = `<div class="empty"><span class="empty-t">Game not found</span></div>`; return; }
  const pl = payloadOf(msg);
  const def = gameDefs()[pl.game];
  $('#game-brand').textContent = def ? def.name : 'Game';
  if (!gameStateOk(pl)){
    body.innerHTML = `<div class="empty">
      <span class="empty-t">Can't open this game</span>
      It was created by an older version of Mylo. Start a new one and it will work.
    </div>`;
    return;
  }
  try{
    if (pl.game === 'rush'){ body.innerHTML = scoreboardHTML(pl) + potHTML(pl) + rushTableHTML(pl) + gameEndHTML(pl); return; }
    if (pl.game === 'scrabble'){
      if (!window.MyloGames?.scrabble){
        body.innerHTML = `<div class="empty"><span class="empty-t">Scrabble needs a refresh</span>Reload the page, then open again.</div>`;
        return;
      }
      body.innerHTML = scoreboardHTML(pl) + potHTML(pl) + scrabbleTableHTML(pl) + gameEndHTML(pl);
      syncScWords(gid, pl);
      return;
    }
    if (pl.game === 'chess'){
      if (!window.MyloGames?.chess?.pieceSVG){
        body.innerHTML = `<div class="empty"><span class="empty-t">Chess needs a refresh</span>Reload the page, then open again.</div>`;
        return;
      }
      const status = pl.over
        ? (pl.winner ? `${gameSeatName(pl, pl.winner)} won` : def_summary(pl))
        : def_summary(pl);
      body.innerHTML = `
        ${scoreboardHTML(pl) + potHTML(pl)}
        <div class="gplayers">
          ${gamePlayerHTML(pl, 'host', 'white')}
          <div class="gstatus">${esc(status)}</div>
          ${gamePlayerHTML(pl, 'guest', 'black')}
        </div>
        <div class="gboard-wrap">${chessBoardHTML(pl)}</div>
        ${gameEndHTML(pl)}`;
      return;
    }
    if (pl.game === 'eights'){
      body.innerHTML = `
        ${scoreboardHTML(pl) + potHTML(pl)}
        <div class="gplayers">
          ${gamePlayerHTML(pl, 'host', '')}
          <div class="gstatus">${esc(def_summary(pl))}</div>
          ${gamePlayerHTML(pl, 'guest', '')}
        </div>
        <div class="gboard-wrap">${cardsTableHTML(pl)}</div>
        ${gameEndHTML(pl)}`;
      return;
    }
    body.innerHTML = `<div class="empty"><span class="empty-t">Unknown game</span></div>`;
  }catch(err){
    console.warn('renderGameOverlay', pl.game, err);
    body.innerHTML = `<div class="empty"><span class="empty-t">Something went wrong</span>${esc(errMsg(err) || 'Close and try again.')}</div>`;
  }
}

/* ---------- Colour Rush: 2-4 players around a table ---------- */
function rushCardHTML(c, opts = {}){
  const R = MyloGames.rush;
  const cls = ['rcard', 'rc-' + c.c, opts.big ? 'big' : '', opts.dim ? 'dim' : ''].filter(Boolean).join(' ');
  const face = R.cardFace(c);
  const tag = opts.idx != null ? ` data-rush-card="${opts.idx}"` : '';
  const dis = opts.dim ? ' disabled' : '';
  const el = opts.idx != null ? 'button' : 'span';
  return `<${el} type="button" class="${cls}"${tag}${dis} aria-label="${esc(R.COLOUR_NAME[c.c])} ${esc(R.cardLabel(c))}">
    <span class="rcard-c">${esc(face)}</span>
    <span class="rcard-m">${esc(face)}</span>
  </${el}>`;
}
function rushSeatHTML(pl, id){
  const R = MyloGames.rush;
  const st = pl.state;
  const p = profileById(id);
  const n = (st.hands[id] || []).length;
  const active = !pl.over && R.current(st) === id;
  const low = n === 1;
  return `<div class="rseat ${active ? 'is-active' : ''}">
    <span class="rseat-av">${avatarMark(p, 'avatar-gp')}</span>
    <span class="rseat-n">${esc(uname(p))}</span>
    <span class="rseat-c ${low ? 'is-low' : ''}">${low ? 'Last card!' : n}</span>
  </div>`;
}
function rushTableHTML(pl){
  const R = MyloGames.rush;
  const st = pl.state;
  const mid = me()?.id;
  const seated = st.players.includes(mid);
  const others = st.players.filter(id => id !== mid);
  const hand = st.hands[mid] || [];
  const mine = myTurn(pl);
  const top = st.pile[st.pile.length - 1];
  const status = pl.over
    ? `${esc(uname(profileById(st.winner || pl.winner)))} won`
    : (mine ? (st.pendingDraw ? `Play a +2 or draw ${st.pendingDraw}` : 'Your turn')
            : `${esc(uname(profileById(R.current(st))))}'s turn`);
  const cards = hand.map((c, i) => rushCardHTML(c, { idx: i, dim: !(mine && R.playable(c, st)) })).join('');
  return `
    <div class="rush-table">
      <div class="rseats">${others.map(id => rushSeatHTML(pl, id)).join('')}</div>
      <div class="rush-mid">
        <div class="rush-deck" data-rush-draw ${mine && !pl.over ? '' : 'aria-disabled="true"'}>
          <span class="rush-deck-n">${st.deck.length}</span>
        </div>
        ${rushCardHTML(top, { big: true })}
        <div class="rush-colour rc-dot-${esc(st.colour)}" title="${esc(R.COLOUR_NAME[st.colour])}"></div>
      </div>
      <div class="rush-status ${mine ? 'is-you' : ''}">${status}</div>
      ${seated ? `<div class="rush-hand">${cards || '<span class="cards-empty">No cards</span>'}</div>` : ''}
      <div class="rush-actions">
        <button type="button" class="btn-secondary" data-rush-draw ${mine && !pl.over ? '' : 'disabled'}>
          ${st.pendingDraw ? 'Take ' + st.pendingDraw : 'Draw'}
        </button>
      </div>
      ${st.note ? `<div class="game-hint">${esc(st.note)}</div>` : ''}
    </div>`;
}
/* ---------- Scrabble table ---------- */
function scDraft(){
  state._scDraft = state._scDraft || { placed: [], sel: null };
  return state._scDraft;
}
function scResetDraft(){ state._scDraft = { placed: [], sel: null }; }

function scrabbleTableHTML(pl){
  const S = window.MyloGames?.scrabble;
  if (!S) return `<div class="empty"><span class="empty-t">Scrabble unavailable</span>Reload and try again.</div>`;
  const st = pl.state;
  if (!st || !Array.isArray(st.board) || !Array.isArray(st.players)){
    return `<div class="empty"><span class="empty-t">Broken Scrabble game</span>Start a new one.</div>`;
  }
  const mid = me()?.id;
  const seated = !!(mid && st.players.includes(mid));
  const mine = myTurn(pl);
  const d = scDraft();
  const draftAt = {};
  d.placed.forEach(p => { draftAt[p.idx] = p; });

  const cells = st.board.map((cell, i) => {
    const dr = draftAt[i];
    const prem = S.PREM[i];
    // Board cells use { l }, draft placements use { letter } — never show "undefined".
    const t = cell || (dr ? { l: dr.letter || dr.l, blank: !!dr.blank } : null);
    const letter = t && (t.l || t.letter);
    const cls = ['sc-sq', prem ? 'p-' + prem.toLowerCase() : '', dr ? 'is-draft' : '',
      (!t && mine && d.sel != null) ? 'is-open' : '', i === 112 && !t ? 'is-star' : ''].filter(Boolean).join(' ');
    return `<button type="button" class="${cls}" data-sc-sq="${i}" ${mine ? '' : 'disabled'}>
      ${letter
        ? `<span class="sc-tile ${t.blank ? 'is-blank' : ''}"><b>${esc(letter)}</b><i>${t.blank ? '' : (S.VALUE[letter] || 0)}</i></span>`
        : (prem ? `<span class="sc-prem">${prem}</span>` : (i === 112 ? '<span class="sc-prem">★</span>' : ''))}
    </button>`;
  }).join('');

  const rack = ((mid && st.racks && st.racks[mid]) || []).slice();
  d.placed.forEach(p => {
    const want = p.blank ? '?' : p.letter;
    const k = rack.indexOf(want);
    if (k >= 0) rack.splice(k, 1);
  });
  const rackHTML = rack.map((l, i) => `
    <button type="button" class="sc-rack-t ${d.sel === i ? 'is-on' : ''}" data-sc-rack="${i}" ${mine ? '' : 'disabled'}>
      <b>${l === '?' ? ' ' : esc(l)}</b><i>${S.VALUE[l] || 0}</i>
    </button>`).join('');

  const scores = st.players.map(id => `
    <div class="sc-score ${S.current(st) === id && !st.over ? 'is-active' : ''}">
      <span class="sc-score-av">${avatarMark(profileById(id), 'avatar-todo')}</span>
      <span class="sc-score-n">${esc(id === mid ? 'You' : uname(profileById(id)))}</span>
      <b>${(st.scores && st.scores[id]) || 0}</b>
    </div>`).join('');

  const last = st.lastWord;
  const note = last
    ? (last.passed ? `${esc(uname(profileById(last.by)))} passed`
      : last.swapped ? `${esc(uname(profileById(last.by)))} swapped ${last.swapped}`
      : `${esc(uname(profileById(last.by)))} played ${esc((last.words || []).join(', '))} for ${last.score}`)
    : 'First word must cross the centre star.';

  const wordsN = pl.gameId ? scWordsPlayed(pl.gameId).length : 0;
  return `
    <div class="sc-table">
      <div class="sc-scores">${scores}
        <button type="button" class="sc-words-btn" data-scw-open aria-label="Words played and their meanings">
          <span>Aa</span>${wordsN ? `<b>${wordsN}</b>` : ''}
        </button>
      </div>
      <div class="sc-board-wrap"><div class="sc-board">${cells}</div></div>
      <div class="sc-note">${note}${st.bag?.length ? ` · ${st.bag.length} in the bag` : ' · bag empty'}</div>
      ${seated ? `<div class="sc-rack">${rackHTML || '<span class="sc-note">No tiles left</span>'}</div>` : '<div class="sc-note">Spectating — you are not seated at this board.</div>'}
      <div class="sc-actions">
        <button type="button" class="btn-secondary" data-sc-recall ${d.placed.length ? '' : 'disabled'}>Recall</button>
        <button type="button" class="btn-secondary" data-sc-pass ${mine && !st.over ? '' : 'disabled'}>Pass</button>
        <button type="button" class="btn-primary" data-sc-submit ${mine && d.placed.length && !st.over ? '' : 'disabled'}>Play</button>
      </div>
    </div>`;
}

async function onScSquare(i){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const mid = me()?.id;
  if (!mid || !pl.state.racks?.[mid]){ toast('You are not in this game'); return; }
  const d = scDraft();
  const existing = d.placed.findIndex(p => p.idx === i);
  if (existing >= 0){ d.placed.splice(existing, 1); renderGameOverlay(); return; }
  if (pl.state.board[i]) return;
  if (d.sel == null){ toast('Pick a tile first'); return; }
  const rack = pl.state.racks[mid].slice();
  d.placed.forEach(p => {
    const k = rack.indexOf(p.blank ? '?' : p.letter);
    if (k >= 0) rack.splice(k, 1);
  });
  const letter = rack[d.sel];
  if (!letter) { d.sel = null; renderGameOverlay(); return; }
  if (letter === '?'){
    const chosen = await pickLetter();
    if (!chosen) return;
    d.placed.push({ idx: i, letter: chosen, blank: true });
  } else {
    d.placed.push({ idx: i, letter, blank: false });
  }
  d.sel = null;
  renderGameOverlay();
}
async function onScSubmit(){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!window.MyloGames?.scrabble){ toast('Reload to play Scrabble'); return; }
  const d = scDraft();
  if (!d.placed.length){ toast('Place a tile first'); return; }
  try{
    if (!MyloGames.scrabble.dictReady()){
      toast('Loading word list…');
      await MyloGames.scrabble.loadDict();
    }
  } catch{
    toast('Could not load the word list');
    return;
  }
  const res = MyloGames.scrabble.play(pl.state, me().id, d.placed);
  if (res.error){ toast(res.error); return; }
  scResetDraft();
  await pushGameState(pl, res.state, { over: !!res.state.over, winner: res.state.winner || null });
  toast(`+${res.total}`);
  renderGameOverlay();
}
async function onScPass(){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!window.MyloGames?.scrabble){ toast('Reload to play Scrabble'); return; }
  const next = MyloGames.scrabble.pass(pl.state, me().id);
  if (!next) return;
  scResetDraft();
  await pushGameState(pl, next, { over: !!next.over, winner: next.winner || null });
  renderGameOverlay();
}
/** Blank tiles need a letter before they can be placed.
    This used to be a block appended to the bottom of the game body — a flex column
    — so it was squeezed flat under the board and usually below the fold, and there
    was no way to back out of it. It is a panel over the board now, with Cancel. */
function pickLetter(){
  return new Promise(resolve => {
    const sheet = $('#game-overlay .game-sheet') || document.body;
    $('#letter-pick')?.remove();
    const bar = document.createElement('div');
    bar.id = 'letter-pick';
    bar.className = 'letter-pick';
    bar.innerHTML = `<div class="letter-pick-card" role="dialog" aria-label="Choose a letter for the blank tile">
        <div class="letter-pick-h"><b>Blank tile</b><span>Pick the letter it stands for</span></div>
        <div class="letter-grid">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l =>
          `<button type="button" data-letter="${l}">${l}</button>`).join('')}</div>
        <button type="button" class="letter-pick-x" data-letter-cancel>Cancel</button>
      </div>`;
    sheet.appendChild(bar);
    const done = v => { bar.remove(); resolve(v); };
    bar.addEventListener('click', e => {
      const b = e.target.closest('[data-letter]');
      if (b){ done(b.dataset.letter); return; }
      if (e.target.closest('[data-letter-cancel]') || e.target === bar) done(null);
    });
  });
}

async function onRushPlay(i){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const R = MyloGames.rush;
  const mid = me().id;
  const card = pl.state.hands[mid][i];
  let colour = null;
  if (card && card.c === 'w'){
    colour = await pickColour();
    if (!colour) return;
  }
  const next = R.play(pl.state, mid, i, colour);
  if (!next){ toast("That card doesn't match"); return; }
  await pushGameState(pl, next, { over: !!next.over, winner: next.winner || null });
  renderGameOverlay();
}
async function onRushDraw(){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const next = MyloGames.rush.draw(pl.state, me().id);
  if (!next) return;
  await pushGameState(pl, next);
  renderGameOverlay();
}
function pickColour(){
  return new Promise(resolve => {
    const body = $('#game-body');
    if (!body) return resolve(null);
    const bar = document.createElement('div');
    bar.className = 'colour-pick';
    bar.innerHTML = `<span>Pick a colour</span><div class="colour-pick-row">` +
      MyloGames.rush.COLOURS.map(c =>
        `<button type="button" class="rc-swatch rc-${c}" data-colour="${c}" aria-label="${esc(MyloGames.rush.COLOUR_NAME[c])}"></button>`
      ).join('') + `</div>`;
    body.appendChild(bar);
    bar.addEventListener('click', e => {
      const b = e.target.closest('[data-colour]');
      if (!b) return;
      bar.remove();
      resolve(b.dataset.colour);
    });
  });
}

function chessBoardHTML(pl){
  const C = MyloGames.chess;
  const st = pl.state;
  const seat = gameSeat(pl);
  const flip = seat === 'guest';                  // guest plays black, board flips
  const sel = state._gameSel;
  const targets = (sel != null) ? C.legalMoves(st, sel).map(m => m.to) : [];
  const mine = myTurn(pl);
  const order = [];
  for (let i = 0; i < 64; i++) order.push(flip ? 63 - i : i);
  const cells = order.map(i => {
    const [r, c] = C.rc(i);
    const dark = (r + c) % 2 === 1;
    const p = st.board[i];
    const isSel = sel === i;
    const isTarget = targets.includes(i);
    const wasLast = st.last && (st.last.from === i || st.last.to === i);
    return `<button type="button" class="csq ${dark ? 'd' : ''}${isSel ? ' sel' : ''}${isTarget ? ' tgt' : ''}${wasLast ? ' last' : ''}"
      data-csq="${i}" ${mine ? '' : 'disabled'} aria-label="${C.sq(i)}">${p ? `<span class="cpc ${C.colorOf(p) === 'w' ? 'w' : 'b'}">${C.pieceSVG(p)}</span>` : ''}</button>`;
  }).join('');
  return `
    <div class="cboard" role="grid" aria-label="Chess board">${cells}</div>
    <div class="game-hint">${pl.over ? 'Game over.' : (mine ? (sel != null ? 'Pick a highlighted square.' : 'Tap a piece to move.') : 'Waiting for their move…')}</div>`;
}
function def_summary(pl){
  const def = gameDefs()[pl.game];
  return def ? def.summary(pl.state) : '';
}

function cardsTableHTML(pl){
  const E = MyloGames.eights;
  const st = pl.state;
  const seat = gameSeat(pl) || 'guest';
  const hand = st.hands[seat] || [];
  const theirs = st.hands[seat === 'host' ? 'guest' : 'host'] || [];
  const top = st.pile[st.pile.length - 1];
  const mine = myTurn(pl);
  const cards = hand.map((c, i) => {
    const ok = mine && E.playable(c, st);
    return `<button type="button" class="pcard hand ${E.isRed(c) ? 'red' : ''}${ok ? '' : ' dim'}"
      data-card="${i}" ${ok ? '' : 'disabled'}><b>${c.r}</b><i>${c.s}</i></button>`;
  }).join('');
  return `
    <div class="cards-table">
      <div class="cards-opp">Opponent holds ${theirs.length}</div>
      <div class="cards-pile">
        <span class="pcard big ${E.isRed(top) ? 'red' : ''}"><b>${top.r}</b><i>${top.s}</i></span>
        <span class="cards-suit">Suit in play <b>${st.suit}</b></span>
      </div>
      <div class="cards-hand">${cards || '<span class="cards-empty">No cards</span>'}</div>
      <div class="cards-actions">
        <button type="button" class="btn-secondary" data-card-draw ${mine && !pl.over ? '' : 'disabled'}>Draw</button>
      </div>
      <div class="game-hint">${pl.over
        ? `${esc(gameSeatName(pl, st.winner || pl.winner))} won.`
        : (mine ? 'Play a card that matches the suit or rank. Eights are wild.' : 'Waiting for their move…')}</div>
    </div>`;
}

async function onChessSquare(i){
  if (state._chessBusy) return;
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const C = MyloGames.chess;
  const st = pl.state;
  const sel = state._gameSel;
  if (sel != null){
    const mv = C.legalMoves(st, sel).find(m => m.to === i);
    if (mv){
      const next = C.apply(st, mv);
      state._gameSel = null;
      const status = C.status(next);
      const over = ['checkmate','stalemate','draw'].includes(status);
      const winner = status === 'checkmate' ? gameSeat(pl) : null;
      state._chessBusy = true;
      try{
        renderGameOverlay();
        await pushGameState(pl, next, { over, winner, note: C.moveLabel(st, mv) });
        renderGameOverlay();
      } finally {
        state._chessBusy = false;
      }
      return;
    }
  }
  const p = st.board[i];
  state._gameSel = (p && C.colorOf(p) === st.turn && C.legalMoves(st, i).length) ? i : null;
  renderGameOverlay();
}

async function onCardPlay(i){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const E = MyloGames.eights;
  const seat = gameSeat(pl);
  const card = pl.state.hands[seat][i];
  let suit = null;
  if (card && card.r === '8'){
    suit = await pickSuit();
    if (!suit) return;
  }
  const next = E.play(pl.state, seat, i, suit);
  if (!next){ toast("That card doesn't match"); return; }
  await pushGameState(pl, next, { over: !!next.over, winner: next.winner || null });
  renderGameOverlay();
}
async function onCardDraw(){
  const gid = state._gameFocus;
  const msg = gid && latestGameMsg(gid);
  if (!msg) return;
  const pl = payloadOf(msg);
  if (!myTurn(pl) || pl.over) return;
  const next = MyloGames.eights.draw(pl.state, gameSeat(pl));
  await pushGameState(pl, next);
  renderGameOverlay();
}
/** Tiny inline suit chooser for a wild eight. */
function pickSuit(){
  return new Promise(resolve => {
    const body = $('#game-body');
    if (!body) return resolve(null);
    const bar = document.createElement('div');
    bar.className = 'suit-pick';
    bar.innerHTML = `<span>Pick a suit</span>` + MyloGames.eights.SUITS
      .map(s => `<button type="button" data-suit="${s}" class="pcard ${s === '♥' || s === '♦' ? 'red' : ''}"><i>${s}</i></button>`).join('');
    body.appendChild(bar);
    bar.addEventListener('click', e => {
      const b = e.target.closest('[data-suit]');
      if (!b) return;
      bar.remove();
      resolve(b.dataset.suit);
    });
  });
}

async function ensureMessageChat(){
  const cur = activeChat();
  if (cur?.id && cur.id !== 'pending-dm') return cur;
  const gid = room()?.group_room_id;
  if (gid){
    try{
      await openChatRoom(gid);
      if (activeChat()?.id) return activeChat();
    }catch(_){}
  }
  const peers = otherMembers();
  if (peers.length === 1){
    try{
      await openDmWith(peers[0].id);
      if (activeChat()?.id) return activeChat();
    }catch(_){}
  }
  const ids = chatRoomIds();
  if (ids[0]){
    try{
      await openChatRoom(ids[0]);
      if (activeChat()?.id) return activeChat();
    }catch(_){}
  }
  return null;
}


function syncMyloFace(){
  const src = charSrc(MYLO_FACE);
  const fab = $('#m-mylo-face');
  const sheet = $('#mylo-sheet-face');
  if (fab) fab.src = src;
  if (sheet) sheet.src = src;
  updateMyloMood();
}
// Mascot reads your day: happy when today's goals are done, sad/angry when they're slipping.
function myloMood(){
  const list = (state.goals || []).filter(inToday);
  const total = list.length;
  const done = list.filter(g => g.done).length;
  const remaining = total - done;
  const streak = Number(localStorage.getItem('mylo:streak') || 0);
  const hour = new Date().getHours();
  if (total > 0 && remaining === 0) return { mood:'happy', msg: streak > 1 ? `${streak}-day streak` : 'All done today' };
  if (total === 0) return { mood:'neutral', msg: "Set today's goals?" };
  if (hour >= 18 && remaining > 0) return { mood:'angry', msg: `${remaining} goal${remaining>1?'s':''} still waiting` };
  if (remaining > 0) return { mood:'sad', msg: `${remaining} to go` };
  return { mood:'neutral', msg: 'Keep going' };
}
function updateMyloMood(){
  const fab = $('#m-mylo-fab');
  if (!fab) return;
  const { mood, msg } = myloMood();
  fab.setAttribute('data-mood', mood);
  const bub = $('#m-mylo-bubble'); if (bub){ bub.textContent = msg; bub.hidden = false; }
  // Greet with the reaction bubble once per app open, then tuck it away
  if (!fab.classList.contains('hidden') && !state._myloMoodShown){
    state._myloMoodShown = true;
    fab.classList.add('show-bubble');
    clearTimeout(state._myloBubbleT);
    state._myloBubbleT = setTimeout(() => { $('#m-mylo-fab')?.classList.remove('show-bubble'); }, 4500);
  }
}
function updateAddVisibility(){
  const mobileId = ($('.m-screen.active')||{}).id || 'm-today';
  const mobileScreen = mobileId.replace(/^m-/,'');
  const deskView = currentDeskView();
  const sheetOn = !!document.querySelector('.sheet.on');
  const scrim = $('#scrim');
  // Don't let a lone scrim lock the UI — that freezes scroll/taps on chat + nav.
  if (!sheetOn && scrim?.classList.contains('on')) scrim.classList.remove('on');
  const sheetOpen = sheetOn;
  const onChatList = mobileScreen === 'chat' && state.chatView !== 'thread' && state.chatView !== 'mylo' && state.chatView !== 'msboard';
  // Goals are set on Goals (and scheduled on Calendar). Today is for working through
  // what is already there, so it keeps only the Quick to-do "+" inside the card.
  // v1 redesign: the + sits in the middle of the tab bar on every main screen.
  const mobileAdd = !sheetOpen && ['today', 'goals', 'calendar', 'cats', 'chat', 'apps'].includes(mobileScreen);
  const deskAdd = !sheetOpen && (deskView === 'today' || deskView === 'goals' || deskView === 'calendar' || deskView === 'categories');
  const onChat = mobileScreen === 'chat' || deskView === 'chat';
  const inThread = onChat && ((state.chatView === 'thread' && !!activeChat()) || state.chatView === 'msboard' || state.chatView === 'mylo');
  // Mylo lives inside the Today + chooser — not as a separate face FAB
  const showMylo = false;
  $('#m-fab')?.classList.toggle('hidden', !mobileAdd);
  $('#m-fab')?.classList.toggle('is-milestone', false);
  $('#m-mylo-fab')?.classList.toggle('hidden', true);
  document.body.classList.toggle('dual-fab', false);
  $('#btn-add-desk')?.classList.toggle('hidden', !deskAdd);
  document.body.classList.toggle('chat-screen', onChat);
  document.body.classList.toggle('chat-thread', inThread);
  document.body.classList.toggle('sheet-open', sheetOpen);
  syncMyloFace();
}
