async function insertMessage({ kind, body, payload, silent }){
  const chat = activeChat();
  if (!chat) throw new Error('Open a chat first');
  const temp = {
    id: 'tmp-'+Date.now(),
    room_id: chat.id,
    from_id: me().id,
    kind,
    body,
    payload: payload || {},
    created_at: new Date().toISOString(),
    _pending: true
  };
  state.messages.push(temp);
  appendChatMessage(temp);
  if (!silent) playMessageSound('send');
  state.lastMsgByRoom[chat.id] = temp;
  refreshChatListIfNeeded();
  const { data, error } = await sb.from('messages').insert({
    room_id: chat.id,
    from_id: me().id,
    kind,
    body,
    payload: payload || {}
  }).select().single();
  if (error){
    state.messages = state.messages.filter(m => m.id !== temp.id);
    document.querySelectorAll(`[data-msg-id="${CSS.escape(temp.id)}"]`).forEach(el => el.remove());
    notify(errMsg(error));
    throw error;
  }
  // Prefer realtime's copy if it landed first — never append the same id twice.
  const alreadyIdx = state.messages.findIndex(m => m.id === data.id);
  const tempIdx = state.messages.findIndex(m => m.id === temp.id);
  if (alreadyIdx >= 0){
    if (tempIdx >= 0) state.messages.splice(tempIdx, 1);
  } else if (tempIdx >= 0){
    state.messages[tempIdx] = data;
  } else {
    state.messages.push(data);
  }
  document.querySelectorAll(`[data-msg-id="${CSS.escape(temp.id)}"]`).forEach(el => el.remove());
  if (!document.querySelector(`[data-msg-id="${CSS.escape(data.id)}"]`)){
    appendChatMessage(data);
  }
  if (isPlayMsg(data) && state._chanceMsgId === temp.id){
    state._chanceMsgId = data.id;
    const gid = payloadOf(data).gameId;
    if (gid) state._chanceFocus = gid;
    state._chanceDraft = { ...(state._chanceDraft || {}), ...payloadOf(data), _msgId: data.id };
    if ($('#chance-overlay')?.classList.contains('on')){
      renderChanceOverlay(payloadOf(data), data);
    }
  }
  return data;
}

async function sendMsg(root){
  const scope = root || chatSurface();
  const i = scope.querySelector('#chat-in') || $('#chat-in');
  if (!i) return;
  if (!activeChat()){ toast('Open a chat first'); return; }
  // An attached photo can go on its own — an empty field is not "nothing to send".
  if (state.pendingPhoto){
    const cap = i.value.trim();
    i.value = '';
    syncSendAffordance(i);
    await sendPendingPhoto(cap);
    return;
  }
  if (!i.value.trim()) return;
  const body = i.value.trim();
  const reply = state.replyTo;
  i.value = '';
  i.closest('.chat-compose')?.querySelector('.mention-pop')?.remove();
  state.replyTo = null;
  syncReplyBars();
  try{
    i.focus();
  }catch{}
  try{
    await insertMessage({ kind:'text', body, payload: reply ? { reply } : {} });
    if (mentionsMylo(body)) handleMyloMention(body);
  }catch(err){
    i.value = body;
    state.replyTo = reply || null;
    syncReplyBars();
    notify(errMsg(err));
  }
}
function renderIconGrid(query){
  const grid = $('#cat-icon-grid');
  if (!grid) return;
  const L = window.lucide;
  let names;
  const q = (query || '').trim().toLowerCase().replace(/\s+/g, '');
  if (q && L && L.icons){
    names = Object.keys(L.icons).filter(n => n.toLowerCase().includes(q)).slice(0, 60);
  } else {
    names = COMMON_ICONS.filter((n, i) => COMMON_ICONS.indexOf(n) === i);
  }
  grid.innerHTML = names.map(n =>
    `<button type="button" class="icon-opt ${pickedIcon === n ? 'is-on' : ''}" data-set-icon="${esc(n)}" aria-label="${esc(n)}">${lucideSvg(n, 20) || esc(n[0])}</button>`
  ).join('') || `<div style="grid-column:1/-1;color:var(--muted);font-size:13px;padding:8px 2px">No icons match.</div>`;
}
