async function saveCat(){
  const name = $('#cat-name').value.trim();
  if (!name){ toast('Add a name'); return; }
  try{
    if (editCatId){
      const { error } = await sb.from('categories').update({ name, color: pickedColor }).eq('id', editCatId).eq('room_id', room().id);
      if (error) throw error;
      setCatIconName(editCatId, pickedIcon);
      toast('Category updated');
    } else {
      const { data, error } = await sb.from('categories').insert({
        room_id: room().id,
        owner_id: me().id,
        name,
        color: pickedColor
      }).select().single();
      if (error) throw error;
      if (data?.id) setCatIconName(data.id, pickedIcon);
      toast('Category saved');
    }
    editCatId = null;
    await reloadGoalsAndCats();
    closeSheets();
    renderAll();
  }catch(e){ notify(errMsg(e)); }
}

async function deleteCat(id){
  const cat = state.categories.find(c => c.id === id);
  if (!cat) return;
  if (!confirm(`Delete “${cat.name}”? Goals keep their times.`)) return;
  closeSheets();
  try{
    const { error, count } = await sb.from('categories').delete({ count: 'exact' }).eq('id', id).eq('room_id', room().id);
    if (error) throw error;
    setCatIconName(id, '');
    state.categories = state.categories.filter(c => c.id !== id);
    state.goals.forEach(g => { if (g.category_id === id) g.category_id = null; });
    renderAll();
    toast(count === 0 ? 'Could not delete — try again' : 'Category deleted');
    if (count !== 0) await reloadGoalsAndCats();
  }catch(e){ notify(errMsg(e)); }
}

async function saveGoal(keepOpen){
  const title = $('#in-title').value.trim();
  if (!title){ toast('Add a title'); return false; }
  const scope = $('#in-scope button.is-active').dataset.scope;
  let dueDate = $('#in-date').value || TODAY_ISO;
  if (scope === 'year') dueDate = null;
  if (scope === 'week' && dueDate){
    const d = new Date(dueDate+'T00:00:00');
    const day = (d.getDay()+6)%7;
    d.setDate(d.getDate()-day);
    dueDate = iso(d);
  }
  // Day goals can't start in the past; week/month use period end (Monday alone is fine mid-week).
  if (scope === 'day' && dueDate && dueDate < TODAY_ISO && !editGoalId){
    toast('Past days are locked');
    return false;
  }
  if ((scope === 'week' || scope === 'month') && dueDate && !editGoalId){
    const probe = { scope, due_date: dueDate, done: false };
    if (goalPeriodEnded(probe)){
      toast('Past days are locked');
      return false;
    }
  }
  const isShared = ($('#in-share-mode button.is-active')?.dataset?.share === 'shared');
  let durationMin = null;
  let startTime = null;
  let endTime = null;
  const categoryId = $('#in-cat')?.value || null;
  if (scope !== 'year'){
    const raw = ($('#in-duration')?.value || '').trim();
    durationMin = raw ? Number(raw) : null;
    if (!durationMin || durationMin <= 0){
      toast('Pick a duration');
      return false;
    }
    startTime = fmtTime($('#in-start')?.value || '') || null;
    if (!startTime){
      toast('Pick a start time');
      return false;
    }
    endTime = endTimeFrom(startTime, durationMin) || null;
  }
  try{
    if (editGoalId){
      const g = state.goals.find(x => x.id === editGoalId);
      if (!g || !canWrite(g)){ toast('Open a room to edit'); return false; }
      let q = sb.from('goals').update({
        title, scope, due_date: dueDate, category_id: categoryId,
        duration_min: durationMin, start_time: startTime, end_time: endTime, is_shared: isShared
      }).eq('id', editGoalId);
      const { error } = await q;
      if (error) throw error;
      toast('Saved');
      await reloadGoalsAndCats();
      closeSheets();
      renderAll();
      scheduleGcalSync();
      return true;
    }
    const { data, error } = await sb.from('goals').insert({
      room_id: room().id,
      owner_id: me().id,
      title, scope,
      due_date: dueDate,
      category_id: categoryId,
      duration_min: durationMin,
      start_time: startTime,
      end_time: endTime,
      is_shared: isShared,
      done: false
    }).select('id').single();
    if (error) throw error;
    const newId = data?.id;
    const drafts = [...(state.draftSubgoals || [])];
    state.draftSubgoals = [];
    if (newId && drafts.length){
      for (const step of drafts){
        try{ await addSubgoal(newId, step); }catch(_){}
      }
    }
    toast(isShared ? 'Shared goal added' : 'Goal added');
    if (newId) awardXp('goaladd', 'goaladd:' + newId);
    await reloadGoalsAndCats();
    closeSheets();
    renderAll();
    scheduleGcalSync();
    return true;
  }catch(e){
    notify(errMsg(e));
    return false;
  }
}

async function toggleGoal(id){
  const g = state.goals.find(x => x.id === id);
  if (!g || !canWrite(g)){ toast('Open a room to edit'); return; }
  const block = goalToggleBlockReason(g);
  if (block){ toast(block); return; }
  const next = !g.done;
  g.done = next;
  // Surgical DOM update — avoid full renderAll (that reloads avatars / causes blink)
  const checkSvg = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"><path d="M4 12.5l5.5 5.5L20 6.5"/></svg>';
  const calSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M20 6L9 17l-5-5"/></svg>';
  document.querySelectorAll(`[data-toggle="${CSS.escape(id)}"], [data-goal-id="${CSS.escape(id)}"]`).forEach(el => {
    const row = el.closest('.task, .goal, .tcard, .goal-card, .cal-task-row') || el;
    row.classList.toggle('done', next);
    row.classList.toggle('is-done', next);
    row.classList.remove('is-missed');
    const tick = row.querySelector('.tcheck, .tick, .cal-task-check')
      || (el.classList?.contains('tcheck') || el.classList?.contains('tick') || el.classList?.contains('cal-task-check') ? el : null);
    if (tick){
      tick.classList.toggle('on', next);
      tick.disabled = false;
      if (tick.classList.contains('cal-task-check')){
        tick.innerHTML = next ? calSvg : `<span class="cal-task-ring"></span>`;
        tick.setAttribute('aria-label', next ? 'Reopen' : 'Complete');
      } else {
        tick.innerHTML = next ? checkSvg : '';
        if (next){ tick.classList.remove('pop'); void tick.offsetWidth; tick.classList.add('pop'); }
      }
    }
    const status = row.querySelector('.cal-task-d span:not(.cal-task-cat)');
    if (status && status.textContent){
      status.textContent = status.textContent
        .replace(/\b(Done|Not done|Open|Waiting)\b/, next ? 'Done' : 'Open');
      status.classList.remove('is-missed-label');
    }
  });
  // Animate the Today progress bar forward immediately
  updateProgressBar();
  try{
    const { error } = await sb.from('goals').update({ done: next }).eq('id', id);
    if (error) throw error;
    if (next) awardXp('goal', 'goal:' + id);
    scheduleGcalSync(1800);
    // Re-list Today so open/done sections and Later stay accurate
    const tab = state.todayFilter || 'todo';
    if (tab === 'todo' || tab === 'completed' || tab === 'pending' || tab === 'later') renderAll();
  }catch(e){
    g.done = !next;
    renderAll();
    notify(errMsg(e));
  }
}

