/* Onboarding interactions */
document.getElementById('onboard')?.addEventListener('click', (e) => {
  if (e.target.closest('#onboard-skip')){ onboardSkip(); return; }
  if (e.target.closest('[data-onboard-signin]')){
    startLoginFlow();
    return;
  }
  if (e.target.closest('[data-onboard-next]')){ onboardNext(); return; }
  const finish = e.target.closest('[data-onboard-finish]');
  if (finish){
    if (finish.dataset.forceFree === '1') onboard.answers.planPick = 'free';
    finishOnboardFlow();
    return;
  }
  const path = e.target.closest('[data-onboard-path]');
  if (path){
    onboard.answers.path = path.dataset.onboardPath;
    if (onboard.answers.path === 'browse'){
      onboard.answers.focus = null;
      onboard.answers.who = null;
    }
    renderOnboard();
    return;
  }
  const focus = e.target.closest('[data-onboard-focus]');
  if (focus){ onboard.answers.focus = focus.dataset.onboardFocus; renderOnboard(); return; }
  const who = e.target.closest('[data-onboard-who]');
  if (who){ onboard.answers.who = who.dataset.onboardWho; renderOnboard(); return; }
  const ch = e.target.closest('[data-onboard-char]');
  if (ch){ onboard.answers.character = ch.dataset.onboardChar; pickedChar = ch.dataset.onboardChar; renderOnboard(); return; }
  const plan = e.target.closest('[data-onboard-plan]');
  if (plan){ onboard.answers.planPick = plan.dataset.onboardPlan; renderOnboard(); return; }
});
// Sign-in shortcut from onboarding skip isn't enough — link on auth still works

async function signInWithProvider(provider){
  if (busyLocked()) return;
  markBusy(true);
  try{
    const redirectTo = `${location.origin}${location.pathname || '/'}`.replace(/\/?$/, '/');
    const { error } = await sb.auth.signInWithOAuth({
      provider,
      options: {
        redirectTo,
        skipBrowserRedirect: false,
        queryParams: provider === 'google' ? { prompt: 'select_account' } : undefined
      }
    });
    if (error) throw error;
    // Browser navigates to provider — stay busy until unload
  }catch(e){
    markBusy(false);
    const msg = errMsg(e);
    if (/provider is not enabled|not enabled/i.test(msg)){
      toast('Google Sign In isn’t enabled yet — turn it on in Supabase Auth → Providers');
    } else {
      toast(msg);
    }
  }
}
async function linkGoogleIdentity(){
  if (busyLocked()) return;
  if (hasGoogleIdentity()){ toast('Google is already connected'); return; }
  markBusy(true);
  try{
    const redirectTo = `${location.origin}${location.pathname || '/'}`.replace(/\/?$/, '/');
    const { error } = await sb.auth.linkIdentity({
      provider: 'google',
      options: {
        redirectTo,
        queryParams: { prompt: 'select_account' }
      }
    });
    if (error) throw error;
  }catch(e){
    markBusy(false);
    const msg = errMsg(e);
    if (/provider is not enabled|not enabled/i.test(msg)){
      toast('Google Sign In isn’t enabled yet — turn it on in Supabase Auth → Providers');
    } else if (/already|linked|identity/i.test(msg)){
      toast('That Google account is already linked elsewhere');
    } else {
      toast(msg);
    }
  }
}
