$('#auth-submit').addEventListener('click', async () => {
  if (busyLocked()) return;
  const raw = $('#auth-user').value.trim();
  const pass = $('#auth-pass').value;
  const signingUp = authMode === 'signup';
  /* Sign-up is always username + email. Sign-in takes whichever the person
     remembers, so the same box accepts both and we resolve it below. */
  const username = raw.toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,20);
  if (signingUp && !/^[a-z0-9_]{3,20}$/.test(username)){ toast('Username: 3–20 letters, numbers, _'); return; }
  if (!signingUp && !raw){ toast('Enter your username or email'); return; }
  if (pass.length < (signingUp ? 8 : 4)){
    toast(signingUp ? 'Password needs 8+ characters' : 'Password needs 4+ characters'); return;
  }
  markBusy(true);
  $('#auth-submit').disabled = true;
  try{
    let email;
    if (signingUp){
      email = ($('#auth-email')?.value || '').trim().toLowerCase();
      if (!isEmail(email)){ toast('Enter an email you can actually open'); return; }
    } else {
      email = await resolveLoginEmail(raw);
    }
    if (authMode === 'signup'){
      const { data: available, error: availErr } = await sb.rpc('username_available', { p_username: username });
      if (availErr) throw availErr;
      if (!available){ toast('Username taken'); return; }
      const { data: freeEmail, error: emailErr } = await sb.rpc('email_available', { p_email: email });
      if (emailErr) throw emailErr;
      if (!freeEmail){ toast('That email already has an account — sign in instead'); return; }
      const seedChar = loadOnboardSeed()?.character || onboard.answers.character || pickedChar || 'happy';
      pickedChar = seedChar;
      const { data, error } = await sb.auth.signUp({
        email,
        password: pass,
        options: {
          data: { username, character: seedChar },
          emailRedirectTo: `${location.origin}${location.pathname || '/'}`.replace(/\/?$/, '/')
        }
      });
      if (error) throw error;
      if (!data.session){
        /* Email confirmation is on. That is a legitimate setting, not a
           misconfiguration, so say what happened rather than telling the
           person to go and change a Supabase toggle they cannot reach. */
        notify('Account created. Check your email to confirm it, then sign in.');
        setAuthMode('login');
        return;
      }
      state.user = data.user;
      state.profile = await loadProfile(data.user.id);
      setAuthCookie(state.profile);
      toast('Account created');
      const seed = loadOnboardSeed();
      if (seed?.character && state.profile){
        pickedChar = seed.character;
        try{ await saveCharacter(seed.character); }catch(_){}
      }
      setPostOnboard('walk');
      const joined = await joinWithInvite();
      if (joined){
        subscribeMessages();
        await applyOnboardSeed().catch(() => {});
        if (maybeStartPostOnboard()) return;
        enterApp(); goMobileScreen('chat');
      } else if (maybeStartPostOnboard()){
        return;
      } else enterHome();
    } else {
      const { data, error } = await sb.auth.signInWithPassword({ email, password: pass });
      if (error) throw error;
      state.user = data.user;
      state.profile = await loadProfile(data.user.id);
      if (state.profile?.banned_at || state.profile?.disabled_at){
        const msg = state.profile.banned_at ? 'This account is banned' : 'This account is disabled';
        state.user = null; state.profile = null;
        await sb.auth.signOut();
        clearAuthCookie();
        throw new Error(msg);
      }
      setAuthCookie(state.profile);
      applyTheme();
      await refreshApp();
    }
  }catch(e){
    notify(errMsg(e));
  }finally{
    markBusy(false);
    $('#auth-submit').disabled = false;
  }
});

async function createRoomWithTitle(){
  const title = ($('#room-title')?.value || '').trim();
  if (!title){ toast('Enter a room name'); return; }
  const isPublic = !!$('#room-public-toggle')?.classList.contains('on');
  const blurb = ($('#room-blurb')?.value || '').trim();
  const category = $('#room-cat')?.value || null;
  /* Caught here as well as in the function, so the message lands next to the
     empty box rather than as a toast after a round trip. */
  if (isPublic && blurb.length < 8){ toast('Add one line on what the room is for'); $('#room-blurb')?.focus(); return; }
  if (busyLocked()) return; markBusy(true);
  $('#room-create').disabled = true;
  try{
    const { data: gate, error: gateErr } = await sb.rpc('can_create_room');
    if (gateErr) throw gateErr;
    if (gate && gate.ok === false){
      state.billing = gate.state || state.billing;
      toast('Room limit reached — upgrade in You → Plan');
      return;
    }
    if (gate?.state) state.billing = gate.state;
    const { data, error } = await sb.rpc('create_room', {
      p_title: title, p_public: isPublic, p_blurb: isPublic ? blurb : null, p_category: isPublic ? category : null
    });
    if (error) throw error;
    if (!data?.id) throw new Error('Room was not created');
    state.chatView = 'list';
    state.chatTab = 'chats';
    state.chatRoom = null;
    toast('Room created — you are the admin');
    await loadRoomsList();
    await refreshBilling();
    closeSheets();
    if ($('#room-title')) $('#room-title').value = '';
    await loadRoomBundle(data.id);
    await applyOnboardSeed().catch(() => {});
    enterApp();
    goMobileScreen('today');
  }catch(e){ notify(errMsg(e)); }
  finally{
    markBusy(false);
    $('#room-create').disabled = false;
  }
}

async function joinRoomWithCode(){
  const code = ($('#room-code')?.value || '').trim().toUpperCase();
  if (!code){ toast('Enter a room code'); return; }
  if (busyLocked()) return; markBusy(true);
  $('#room-join').disabled = true;
  try{
    const status = await requestRoomAccess(code);
    state.chatView = 'list';
    state.chatTab = 'chats';
    state.chatRoom = null;
    closeSheets();
    if ($('#room-code')) $('#room-code').value = '';
    if (status === 'joined'){
      toast('Joined room');
      if (room()){ enterApp(); goMobileScreen('today'); }
      else enterHome();
    } else if (status === 'pending'){
      toast('Request sent — open Home until an admin allows you');
      enterHome();
    }
  }catch(e){ notify(errMsg(e)); }
  finally{
    markBusy(false);
    $('#room-join').disabled = false;
  }
}

async function regenerateInviteCode(customCode){
  if (!room()?.id || !isRoomAdmin()){ toast('Only admins can rotate the code'); return; }
  const clean = String(customCode || '').trim().toUpperCase();
  if (clean && !/^[A-Z0-9]{6,12}$/.test(clean)){
    toast('Code must be 6–12 letters or numbers');
    return;
  }
  const msg = clean
    ? `Set invite code to ${clean}? Old links stop working.`
    : 'Generate a new random invite code? Old links stop working.';
  if (!confirm(msg)) return;
  try{
    let data, error;
    ({ data, error } = await sb.rpc('regenerate_room_code', {
      p_room_id: room().id,
      p_code: clean || null
    }));
    // Fallback if 2-arg RPC not applied yet
    if (error && /could not find|does not exist|function/i.test(error.message || '')){
      if (clean){
        toast('Run the rotate SQL in Supabase to enable custom codes');
        return;
      }
      ({ data, error } = await sb.rpc('regenerate_room_code', { p_room_id: room().id }));
    }
    if (error) throw error;
    if (state.room) state.room.code = data;
    const row = state.rooms.find(r => r.id === room().id);
    if (row) row.code = data;
    $$('#invite-custom-code').forEach(el => { el.value = ''; });
    renderAll();
    toast(clean ? `Code set to ${data}` : `New code: ${data}`);
  }catch(e){ notify(errMsg(e)); }
}

function bindTap(el, fn){
  if (!el || el._tapBound) return;
  el._tapBound = true;
  let lock = false;
  const run = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (lock) return;
    lock = true;
    Promise.resolve(fn(e)).finally(() => setTimeout(() => { lock = false; }, 320));
  };
  el.addEventListener('pointerup', run);
}

