document.addEventListener('change', async e => {
  if (e.target.id === 'photo-file'){
    const file = e.target.files?.[0];
    e.target.value = '';
    await attachPendingPhoto(file);
    return;
  }
  if (e.target.id === 'story-file'){
    const file = e.target.files?.[0];
    e.target.value = '';
    // Backing out of the gallery must not leave an empty composer behind.
    if (!file){ if (!state._storyDraft?.blob) closeStoryComposer(); return; }
    // 1600 was upscaled to fill a 1080x1920 story and came out soft.
    const { blob, w, h } = await shrinkImage(file, 2160);
    const d = state._storyDraft || {};
    if (d.url) URL.revokeObjectURL(d.url);
    const url = URL.createObjectURL(blob);
    let tone = { g1: '#2A2A2E', g2: '#111114' };
    try{
      const probe = new Image();
      probe.src = url;
      await probe.decode();
      tone = sampleStoryGradient(probe);
    }catch(_){}
    state._storyDraft = { ...d, blob, w, h, url, zoom: 1, ox: 0, oy: 0, ...tone };
    document.body.classList.add('story-compose-open');
    renderStoryComposer();
    return;
  }
  if (e.target.id === 'chat-audio-file'){
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !activeChat()) return;
    showComposerBusy('Sending voice note…');
    try{
      const ext = (file.type.split('/')[1] || 'm4a').split(';')[0];
      const url = await uploadChatFile(file, ext, file.type || 'audio/mp4');
      await insertMessage({ kind: 'text', body: 'Voice note', payload: { voice: { url, ms: 0 } } });
    }catch(err){ notify(errMsg(err)); }
    finally{ hideComposerBusy(); }
    return;
  }
  if (e.target.id === 'chat-bg-file'){
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !activeChat()) return;
    openCropper({
      file, aspect: 9 / 16, title: 'Chat background', outW: 900,
      done: async blob => {
        const url = await uploadChatFile(blob, 'jpg', 'image/jpeg');
        await setChatBg(url);
        toast('Background set');
      }
    });
    return;
  }
  if (e.target.id === 'cover-file'){
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !me()) return;
    // The cover is a wide, short strip, so it is the crop that matters most —
    // handing the raw photo over meant the middle band of it won by accident.
    openCropper({
      file, aspect: 1200 / 450, title: 'Your cover', outW: 1200,
      done: async blob => {
        const path = `${me().id}/covers/${Date.now()}.jpg`;
        const { error: upErr } = await sb.storage.from('avatars').upload(path, blob, { upsert: true, contentType: 'image/jpeg' });
        if (upErr) throw upErr;
        const { data: pub } = sb.storage.from('avatars').getPublicUrl(path);
        await setCover(`center/cover no-repeat url("${pub.publicUrl}")`);
        toast('Cover updated');
      }
    });
    return;
  }
  if (e.target.id === 'group-avatar-file'){
    const file = e.target.files?.[0];
    if (!file || !me() || !room()) return;
    if (file.size > 2_500_000){ toast('Keep photos under 2.5MB'); return; }
    try{
      const targetId = room().group_room_id || room().id;
      const path = `${me().id}/rooms/${targetId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'')}`;
      const { error: upErr } = await sb.storage.from('avatars').upload(path, file, { upsert: true, contentType: file.type });
      if (upErr) throw upErr;
      const { data: pub } = sb.storage.from('avatars').getPublicUrl(path);
      const avatar_url = pub.publicUrl;
      const { data, error } = await sb.rpc('set_room_avatar', { p_room_id: targetId, p_avatar_url: avatar_url });
      if (error) throw error;
      // also set on space for home list
      if (room().id !== targetId){
        await sb.rpc('set_room_avatar', { p_room_id: room().id, p_avatar_url: avatar_url });
        state.room = { ...state.room, avatar_url };
      }
      await loadRoomsList();
      renderAll();
      toast('Group photo updated');
    }catch(err){ notify(errMsg(err)); }
    e.target.value = '';
    return;
  }
  if (e.target.id === 'room-avatar-file'){
    const file = e.target.files?.[0];
    if (!file || !me() || !room()) return;
    if (file.size > 2_500_000){ toast('Keep photos under 2.5MB'); return; }
    try{
      const targetId = room().id;
      const path = `${me().id}/rooms/${targetId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'')}`;
      const { error: upErr } = await sb.storage.from('avatars').upload(path, file, { upsert: true, contentType: file.type });
      if (upErr) throw upErr;
      const { data: pub } = sb.storage.from('avatars').getPublicUrl(path);
      const avatar_url = pub.publicUrl;
      const { error } = await sb.rpc('set_room_avatar', { p_room_id: targetId, p_avatar_url: avatar_url });
      if (error) throw error;
      state.room = { ...state.room, avatar_url };
      await loadRoomsList();
      renderAll();
      toast('Room photo updated');
    }catch(err){ notify(errMsg(err)); }
    e.target.value = '';
    return;
  }
  if (e.target.id !== 'avatar-file') return;
  const file = e.target.files?.[0];
  e.target.value = '';
  if (!file || !me()) return;
  openCropper({
    file, aspect: 1, round: true, title: 'Your picture', outW: 640,
    done: async blob => {
      const path = `${me().id}/avatar-${Date.now()}.jpg`;
      const { error: upErr } = await sb.storage.from('avatars').upload(path, blob, { upsert: true, contentType: 'image/jpeg' });
      if (upErr) throw upErr;
      const { data: pub } = sb.storage.from('avatars').getPublicUrl(path);
      const avatar_url = pub.publicUrl;
      const { error } = await sb.from('profiles').update({ avatar_url }).eq('id', me().id);
      if (error) throw error;
      state.profile = { ...state.profile, avatar_url };
      const mine = state.members.find(m => m.id === me().id);
      if (mine) mine.avatar_url = avatar_url;
      renderAll();
      toast('Picture updated');
    }
  });
});

document.addEventListener('click', async e => {
  /* The ring around a face in the chat list is a story, and it has to be asked
     first — it sits inside the row button, which would otherwise open the chat. */
  const ringStory = e.target.closest('.chat-av-story[data-story-open]');
  if (ringStory){
    e.preventDefault(); e.stopPropagation();
    if (focusActive()){ notify(`Statuses are shut — ${fmtDur(focusLeftMs())} left`); return; }
    openStoryViewer(ringStory.dataset.storyOpen, 0);
    return;
  }
  if (e.target.closest('[data-reaction-close]') || e.target.id === 'reaction-overlay'){
    closeReactionPopup();
    return;
  }
  if (e.target.closest('[data-chance-close]') || e.target.id === 'chance-overlay'){
    if (e.target.id === 'chance-overlay' || e.target.closest('[data-chance-close]')){
      closeChanceOverlay();
      return;
    }
  }
  const chanceChoose = e.target.closest('[data-chance-choose]');
  if (chanceChoose){
    const pick = chanceChoose.dataset.chanceChoose;
    const gid = chanceChoose.dataset.chanceGid || state._chanceFocus || null;
    try{ await applyChancePick(pick, state._chanceMsgId, gid); }catch(err){ notify(errMsg(err)); }
    return;
  }
  const chanceRematchLive = e.target.closest('[data-chance-rematch-live]');
  if (chanceRematchLive){
    closeChanceOverlay();
    startChanceGame(chanceRematchLive.dataset.chanceRematchLive).catch(err => notify(errMsg(err)));
    return;
  }

  const toggleNav = e.target.closest('[data-nav-toggle]');
  if (toggleNav){
    const key = toggleNav.dataset.navToggle;
    const sub = $(`#nav-sub-${key}`);
    const open = !toggleNav.classList.contains('is-open');
    toggleNav.classList.toggle('is-open', open);
    toggleNav.setAttribute('aria-expanded', open ? 'true' : 'false');
    sub?.classList.toggle('is-open', open);
    return;
  }

  const subNav = e.target.closest('.nav-sub-item[data-view]');
  if (subNav){
    setDeskView(subNav.dataset.view, { goalScope: subNav.dataset.goalScope || 'day' });
    return;
  }

  const nav = e.target.closest('.nav-item[data-view]');
  if (nav){
    setDeskView(nav.dataset.view);
    return;
  }

  const lookPreset = e.target.closest('[data-look-preset]');
  if (lookPreset){
    const p = LOOK_PRESETS.find(x => x.id === lookPreset.dataset.lookPreset);
    if (p){
      state.lookDraft = { ...draftLook(), ...p.look };
      delete state.lookDraft.character;
      state.lookDirty = true;
      renderAll();
    }
    return;
  }
  const lookStudio = e.target.closest('[data-look-studio]');
  if (lookStudio){
    const tab = lookStudio.dataset.lookStudio;
    state.lookStudioTab = tab;
    state.lookMode = tab === 'photo' ? 'photo' : 'avatar';
    if (tab === 'avatar'){
      state.lookCat = 'color';
      // Clean Mylo base only — strip suit id + accidental party hat
      if (window.avatarKit){
        const saved = avatarKit.lookFromProfile(me());
        const bg = (state.lookDraft && state.lookDraft.bg) || currentLookBg();
        const clean = saved ? avatarKit.normalizeLook(saved) : avatarKit.defaultLook();
        clean.bg = bg;
        clean.accessories = 'none';
        delete clean.character;
        state.lookDraft = clean;
        state.lookDirty = false;
      }
    } else if (tab === 'suits' && !state.lookDraft){
      state.lookDraft = window.avatarKit
        ? { ...avatarKit.defaultLook(), bg: currentLookBg(), character: resolveChar(me()) }
        : { character: resolveChar(me()), bg: currentLookBg() };
    } else if (!state.lookDraft && window.avatarKit){
      const layered = avatarKit.lookFromProfile(me());
      state.lookDraft = layered
        ? { ...avatarKit.normalizeLook(layered), bg: currentLookBg() }
        : { ...avatarKit.defaultLook(), bg: currentLookBg(), character: resolveChar(me()) };
    }
    renderAll();
    return;
  }

  const lookMode = e.target.closest('[data-look-mode]');
  if (lookMode){
    state.lookMode = lookMode.dataset.lookMode;
    state.lookStudioTab = lookMode.dataset.lookMode === 'photo' ? 'photo' : 'avatar';
    if (!state.lookDraft && window.avatarKit){
      state.lookDraft = { ...avatarKit.defaultLook(), bg: currentLookBg(), character: resolveChar(me()) };
    }
    renderAll();
    return;
  }

  const lookTab = e.target.closest('[data-look-tab]');
  if (lookTab){
    state.lookTab = lookTab.dataset.lookTab;
    const tab = AVATAR_KIT.tabs.find(t => t.id === state.lookTab);
    state.lookCat = tab?.cats?.[0] || 'color';
    renderAll();
    return;
  }

  const lookCat = e.target.closest('[data-look-cat]');
  if (lookCat){
    state.lookCat = lookCat.dataset.lookCat;
    renderAll();
    return;
  }

  const setLook = e.target.closest('[data-set-look]');
  if (setLook && me()){
    const layer = setLook.dataset.setLook;
    const id = setLook.dataset.lookId;
    const base = { ...(state.lookDraft || (window.avatarKit ? avatarKit.defaultLook() : {})), bg: currentLookBg() };
    if (layer === 'bg'){
      base.bg = id;
      try{ localStorage.setItem('mylo:lookBg', id); }catch(_){}
    } else if (layer === 'color' || layer === 'base' || layer === 'eyes' || layer === 'mouth' || layer === 'accessories'){
      base[layer] = id;
      delete base.character; // editing parts → layered look
    } else if (layer === 'character'){
      base.character = id;
    }
    state.lookDraft = base;
    state.lookDirty = true;
    state.lookMode = 'avatar';
    state.lookStudioTab = 'avatar';
    renderAll();
    return;
  }

  const saveLookBtn = e.target.closest('[data-save-look]');
  if (saveLookBtn && me()){
    try{
      const draft = state.lookDraft || draftLook();
      if (draft.bg) try{ localStorage.setItem('mylo:lookBg', String(draft.bg).replace('#','')); }catch(_){}
      const charId = draft.character;
      const isPersona = charId && (CHARS.includes(charId) || LEGACY_CHARS.includes(charId));
      if ((state.lookStudioTab === 'suits') && isPersona){
        await saveCharacter(charId);
      } else if (window.avatarKit){
        await saveLook(draft);
      } else if (isPersona){
        await saveCharacter(charId);
      }
      state.lookDirty = false;
      toast('Look saved');
      if ((state.accountPanel || '') === 'look') openAccountPanel('profile');
      else renderAll();
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  if (e.target.closest('#btn-avatar-clear')){
    try{
      const { error } = await sb.from('profiles').update({ avatar_url: null }).eq('id', me().id);
      if (error) throw error;
      state.profile.avatar_url = null;
      state.lookMode = 'avatar';
      renderAll();
      toast('Photo removed');
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const badgeDemo = e.target.closest('[data-badge-demo]');
  if (badgeDemo){
    if (badgeDemo.dataset.badgeDemo === 'streak') openStreakClaimDemo();
    else openBadgeUnlockDemo('streak_30');
    return;
  }
  const badgeClaim = e.target.closest('[data-badge-claim]');
  if (badgeClaim){
    const id = badgeClaim.dataset.badgeClaim;
    const d = badgeDemoState();
    if (!Array.isArray(d.claimed)) d.claimed = [];
    if (!d.earned.includes(id)) d.earned.push(id);
    if (!d.claimed.includes(id)) d.claimed.push(id);
    d.pinned = id;
    saveBadgeDemo(d);
    closeSheets();
    renderAll();
    toast('Streak claimed — pinned on profile');
    return;
  }
  const badgePin = e.target.closest('[data-badge-pin]');
  if (badgePin){
    const id = badgePin.dataset.badgePin;
    const d = badgeDemoState();
    d.pinned = id;
    if (!d.earned.includes(id)) d.earned.push(id);
    saveBadgeDemo(d);
    closeSheets();
    renderAll();
    toast('Pinned on profile');
    return;
  }
  if (e.target.closest('[data-toggle-profile-badges]')){
    setProfileBadges(!profileBadgesOn());
    renderAll();
    return;
  }
  const badgeDetail = e.target.closest('[data-badge-detail]');
  if (badgeDetail){
    openBadgeDetail(badgeDetail.dataset.badgeDetail);
    return;
  }

  if (e.target.closest('[data-open-look]')){
    state.lookMode = me()?.avatar_url ? 'photo' : 'avatar';
    state.lookStudioTab = me()?.avatar_url ? 'photo' : 'avatar';
    if (window.avatarKit){
      const layered = avatarKit.lookFromProfile(me());
      state.lookDraft = layered
        ? { ...avatarKit.normalizeLook(layered), bg: currentLookBg() }
        : { ...avatarKit.defaultLook(), bg: currentLookBg(), character: resolveChar(me()) };
    } else {
      state.lookDraft = { character: resolveChar(me()), bg: currentLookBg() };
    }
    state.lookDirty = false;
    state.lookTab = 'body';
    state.lookCat = 'color';
    if (isDesk()){
      setDeskView('you');
      setTimeout(() => document.getElementById('desk-look')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 60);
    } else if (isOnYouScreen()){
      navigateAccountPanel('look');
      renderAll();
    } else {
      openPrivateProfile('look');
      renderAll();
    }
    return;
  }

  const setChar = e.target.closest('[data-set-char]');
  if (setChar && me()){
    const cid = setChar.dataset.setChar;
    state.lookDraft = { ...(state.lookDraft || {}), character: cid, bg: currentLookBg() };
    state.lookDirty = true;
    state.lookMode = 'avatar';
    state.lookStudioTab = 'avatar';
    renderAll();
    return;
  }

  const mnav = e.target.closest('.m-nav-item[data-mscreen]');
  if (mnav){
    goMobileScreen(mnav.dataset.mscreen);
    return;
  }

  if (state._rec && e.target.closest('[data-chat-back]')) cancelVoiceNote();
  if (e.target.closest('#m-top-back')){
    if (state.walletView && state.walletView !== 'main' && state.walletView !== 'board'){
      state.walletView = 'main';
      renderAll();
      syncMobileTopBar('today');
      return;
    }
    if (state.walletView){
      const back = state.beforeWallet;
      closeWallet();
      if (back && back !== 'today') goMobileScreen(back);
      return;
    }
    if (state.notifView === 'settings'){
      state.notifView = 'list';
      renderAll();
      syncMobileTopBar('today');
      return;
    }
    if (state.notifView){
      closeNotifPage();
      return;
    }
    if (activeMobileScreen() === 'calendar'){
      goMobileScreen('goals');
      renderAll();
      return;
    }
    if (state.beforeCats === 'drawer'){
      state.beforeCats = null;
      goMobileScreen(state.beforeProfile || 'today');
      openProfileDrawer();
      return;
    }
    const backTo = state.beforeCats || state.beforeProfile || 'apps';
    goMobileScreen(backTo === 'cats' ? 'apps' : backTo);
    return;
  }
  if (e.target.closest('#m-avatar-btn')){
    if (document.body.classList.contains('drawer-open')) closeProfileDrawer();
    else openProfileDrawer();
    return;
  }
  const topAction = e.target.closest('#m-top-action');
  if (topAction){
    const kind = topAction.dataset.topAction;
    if (kind === 'notif-settings'){
      state.notifView = 'settings';
      renderAll();
      syncMobileTopBar('today');
      return;
    }
    if (kind === 'goal-scope'){ openGoalScopeMenu(); return; }
    if (kind === 'wallet-earn'){ state.walletView = 'earn'; renderAll(); syncMobileTopBar('today'); return; }
    if (kind === 'notifications' || kind === 'notify'){ openNotifSheet(); return; }
    if (kind === 'discover'){
      const feat = document.querySelector('.apps-feature');
      if (feat) feat.scrollIntoView({ behavior: 'smooth', block: 'start' });
      else toast('Discover mini apps here');
    } else if (kind === 'search') toast('Search · coming soon');
    return;
  }
  if (e.target.closest('#drawer-scrim')){
    closeProfileDrawer();
    return;
  }
  if (e.target.closest('[data-open-profile]') || e.target.closest('[data-drawer="profile"]')){
    openPrivateProfile('profile');
    renderAll();
    return;
  }
  if (e.target.closest('[data-account-back]')){
    accountGoBack();
    return;
  }
  if (e.target.closest('[data-profile-back]')){
    closeSheets();
    const back = state.beforeProfile || 'today';
    state.accountStack = [];
    state.accountPanel = 'profile';
    if (isDesk()) setDeskView(back === 'you' ? 'today' : back);
    else goMobileScreen(back);
    return;
  }
  if (e.target.closest('.look-x')){
    accountGoBack();
    return;
  }
  if (e.target.closest('[data-open-level]')){ openWallet('main'); return; }
  if (e.target.closest('[data-open-streak]')){ closeProfileDrawer?.(); openStreakPage(); return; }
  if (e.target.closest('[data-streak-close]')){ closeStreakPage(); return; }
  if (e.target.closest('[data-streak-download]')){ downloadStreakCard(); return; }
  const drawerAct = e.target.closest('[data-drawer]');
  if (drawerAct){
    const act = drawerAct.dataset.drawer;
    if (act === 'profile'){ openPrivateProfile('profile'); renderAll(); }
    else if (act === 'plan'){
      if (!FEATURES.plans){ goMobileScreen('today'); return; }
      openPrivateProfile('plan'); state.accountReturn = 'drawer'; renderAll();
    }
    else if (act === 'integrations'){
      if (!FEATURES.integrations){ goMobileScreen('today'); return; }
      openPrivateProfile('integrations'); state.accountReturn = 'drawer'; renderAll();
    }
    else if (act === 'room'){ openPrivateProfile('room'); state.accountReturn = 'drawer'; renderAll(); }
    else if (act === 'cats'){ closeProfileDrawer(); goMobileScreen('cats'); state.beforeCats = 'drawer'; }
    else if (act === 'wallet'){ if (FEATURES.wallet) openWallet('main'); else goMobileScreen('today'); }
    else if (act === 'theme'){
      await toggleTheme();
      const inner = $('#drawer-inner');
      if (inner) inner.innerHTML = vDrawer();
    }
    else if (act === 'home' || act === 'leave'){ closeProfileDrawer(); await loadRoomsList(); enterHome(); }
    else if (act === 'signout'){
      closeProfileDrawer();
      await sb.auth.signOut();
      clearAuthCookie();
      state.user = null; state.profile = null;
      showGate('auth');
    }
    return;
  }
  const appsTab = e.target.closest('[data-apps-tab]');
  if (appsTab){
    state.appsTab = appsTab.dataset.appsTab;
    renderAll();
    return;
  }
  const mini = e.target.closest('[data-mini-app]');
  if (mini){
    openMiniApp(mini.dataset.miniApp);
    return;
  }

  if (e.target.closest('[data-open-cats]')){
    goMobileScreen('cats');
    state.deskView = 'categories';
    syncDeskNav();
    renderAll();
    return;
  }
  const jump = e.target.closest('[data-mscreen-jump]');
  if (jump){
    goMobileScreen(jump.dataset.mscreenJump);
    renderAll();
    return;
  }

  const tg = e.target.closest('[data-toggle]');
  if (tg){
    if (tg.disabled) return;
    await toggleGoal(tg.dataset.toggle);
    return;
  }
  if (e.target.closest('[data-toggle-clock-24]')){
    setUse24HourClock(!use24HourClock());
    renderAll();
    return;
  }
  const gExpand = e.target.closest('[data-goal-expand]');
  if (gExpand){ toggleGoalExpand(gExpand.dataset.goalExpand); return; }
  const sgTick = e.target.closest('[data-sg-tick]');
  if (sgTick){ if (!sgTick.disabled) await toggleSubgoal(sgTick.dataset.sgTick); return; }
  const sgDel = e.target.closest('[data-sg-del]');
  if (sgDel){ await deleteSubgoal(sgDel.dataset.sgDel); return; }
  const sgAddBtn = e.target.closest('[data-sg-add-btn]');
  if (sgAddBtn){
    const pid = sgAddBtn.dataset.sgAddBtn;
    const inp = document.querySelector(`[data-sg-add="${CSS.escape(pid)}"]`);
    const val = inp?.value || '';
    if (val.trim()){ if (inp) inp.value=''; await addSubgoal(pid, val); }
    return;
  }
  // System session steps — edited only inside the system sheet
  const rstepAdd = e.target.closest('[data-rstep-add]');
  if (rstepAdd){ await addRoutineStepFromSheet(); return; }
  const rstepDel = e.target.closest('[data-rstep-del]');
  if (rstepDel){ await deleteRoutineSub(rstepDel.dataset.rstepDel); renderRoutineSheetSteps(); return; }
  const rstepDelI = e.target.closest('[data-rstep-del-i]');
  if (rstepDelI){
    const sheet = $('#routine-sheet');
    if (sheet?._draftSteps){ sheet._draftSteps.splice(Number(rstepDelI.dataset.rstepDelI), 1); renderRoutineSheetSteps(); }
    return;
  }
  const info = e.target.closest('[data-goal-info]');
  if (info){ openGoalInfo(info.dataset.goalInfo); return; }
  const editFromInfo = e.target.closest('[data-edit-from-info]');
  if (editFromInfo){
    const g = state.goals.find(x => x.id === editFromInfo.dataset.editFromInfo);
    closeSheets();
    if (g) openGoalSheet(g);
    return;
  }
  const delGoal = e.target.closest('[data-del-goal]');
  if (delGoal){
    await deleteGoal(delGoal.dataset.delGoal);
    return;
  }
  const ed = e.target.closest('[data-edit]');
  if (ed){
    const g = state.goals.find(x=>x.id===ed.dataset.edit);
    if (g){
      if (goalPeriodEnded(g)){ toast('Past days are locked'); return; }
      openGoalSheet(g);
    }
    return;
  }

  if (e.target.closest('#m-mylo-fab')){ openMylo(); return; }
  if (e.target.closest('#btn-add-desk') || e.target.closest('#m-fab')){
    const mScreen = (($('.m-screen.active')||{}).id || '').replace(/^m-/,'');
    const deskV = currentDeskView();
    const onChatList = (mScreen === 'chat' || deskV === 'chat') && state.chatView !== 'thread';
    const onGoals = mScreen === 'goals' || deskV === 'goals';
    const onToday = mScreen === 'today' || deskV === 'today';
    const onCats = mScreen === 'cats' || deskV === 'categories';
    // On the phone the centre + is one capture button everywhere (v1 redesign).
    if (e.target.closest('#m-fab') && (mScreen === 'chat' || mScreen === 'apps')){ openAddChooser(); return; }
    if (onChatList) openMilestoneSheet();
    else if (onCats){
      if ((state.catTab || 'categories') === 'system') openRoutineSheet();
      else openCatSheet();
    }
    else if (onGoals || onToday) openAddChooser();
    else openGoalSheet(null);            // calendar → date-specific goal
    return;
  }
  const addChoice = e.target.closest('[data-add-choice]');
  if (addChoice){
    const c = addChoice.dataset.addChoice;
    closeSheets();
    if (c === 'mylo') openMylo();
    else if (c === 'routine') openRoutineSheet();
    else if (c === 'todo') openTodoSheet();
    else openGoalSheet(null);
    return;
  }
  if (e.target.closest('[data-todo-open]')){ openTodoSheet(); return; }
  const todoTick = e.target.closest('[data-todo-tick]');
  if (todoTick){ await toggleTodo(todoTick.dataset.todoTick); return; }
  const todoDel = e.target.closest('[data-todo-del]');
  if (todoDel){ await deleteTodo(todoDel.dataset.todoDel); return; }
  const tWhen = e.target.closest('[data-todo-when]');
  if (tWhen){
    $$('#todo-when .todo-chip').forEach(b => b.classList.toggle('is-on', b === tWhen));
    const v = tWhen.dataset.todoWhen;
    const day = v === 'today' ? todayFocusIso()
      : v === 'tomorrow' ? iso(addDays(new Date(todayFocusIso() + 'T00:00:00'), 1))
      : '';
    const f = $('#todo-day'); if (f) f.value = day;
    return;
  }
  if (e.target.closest('#todo-save')){ await saveTodoFromSheet(); return; }
  if (e.target.closest('[data-open-mylo]') || e.target.closest('[data-open-mylo-thread]')){ openMyloThread(); return; }
  if (e.target.closest('[data-mylo-back]')){
    state.chatView = 'list';
    saveNav({ chatView: 'list', screen: 'chat' });
    renderAll();
    return;
  }
  if (e.target.closest('[data-mylo-add-drafts]')){ await confirmMyloIntake(); return; }
  const myloHint = e.target.closest('[data-mylo-hint]');
  if (myloHint){
    const send = myloHint.dataset.myloHint || '';
    if (send === '__ADD_GOALS__' || send === '__CONFIRM_INTAKE__'){ await askMylo(send); return; }
    if (send === '__OPEN_PLAN__'){
      openPrivateProfile('plan');
      renderAll();
      toast('Pick a plan or token pack');
      return;
    }
    if (send === '__OPEN_YOU__'){
      openPrivateProfile('integrations');
      renderAll();
      toast('Integrations is in your profile');
      return;
    }
    await askMylo(send);
    return;
  }
  const buySku = e.target.closest('[data-buy-sku]');
  if (buySku){
    if (buySku.hasAttribute('data-pay-soon') || e.target.closest('[data-pay-soon]')){
      toast('Live payments coming soon');
      return;
    }
    await startCheckout(buySku.dataset.buySku);
    return;
  }
  const setThemeBtn = e.target.closest('[data-set-theme]');
  if (setThemeBtn){
    if (setThemeBtn.dataset.themeLocked === '1'){
      toast('Color themes are on Pro & Pod');
      return;
    }
    await setTheme(setThemeBtn.dataset.setTheme);
    return;
  }
  const themeMood = e.target.closest('[data-theme-mood]');
  if (themeMood){
    const mood = themeMood.dataset.themeMood;
    if (mood === 'system' || mood === 'light' || mood === 'dark'){
      await setThemeMood(mood);
    }
    return;
  }
  const setChatThemeBtn = e.target.closest('[data-set-chat-theme]');
  if (setChatThemeBtn){
    if (setChatThemeBtn.dataset.themeLocked === '1'){
      toast('Chat color themes are on Pro & Pod');
      return;
    }
    const peer = setChatThemeBtn.closest('[data-dm-theme-peer]')?.dataset?.dmThemePeer
      || state.chatPeerId
      || $('#person-sheet')?.dataset?.pid;
    if (!peer){ toast('Open a private chat to set its theme'); return; }
    await setDmTheme(peer, setChatThemeBtn.dataset.setChatTheme);
    return;
  }
  const chatMood = e.target.closest('[data-chat-theme-mood]');
  if (chatMood){
    if (chatMood.disabled) return;
    const peer = chatMood.closest('[data-dm-theme-peer]')?.dataset?.dmThemePeer
      || state.chatPeerId
      || $('#person-sheet')?.dataset?.pid;
    if (!peer){ toast('Open a private chat to set its theme'); return; }
    const cur = getRoomChatTheme(activeChat()?.id, peer) || document.documentElement.getAttribute('data-theme') || 'light';
    const { fam } = themeParts(cur);
    const next = chatMood.dataset.chatThemeMood === 'dark' ? fam.dark : fam.light;
    await setDmTheme(peer, next);
    return;
  }
  const openAcct = e.target.closest('[data-open-account-panel]');
  if (openAcct){
    openAccountPanel(openAcct.dataset.openAccountPanel);
    return;
  }
  const goScreen = e.target.closest('[data-go-screen]');
  if (goScreen){
    goMobileScreen(goScreen.dataset.goScreen);
    return;
  }
  const personActions = e.target.closest('[data-person-actions]');
  if (personActions){
    openPersonActions(personActions.dataset.personActions);
    return;
  }
  const jrApprove = e.target.closest('[data-jr-approve]');
  if (jrApprove){
    try{
      const { error } = await sb.rpc('approve_join_request', { p_request_id: jrApprove.dataset.jrApprove });
      if (error) throw error;
      toast('Request approved');
      await loadRoomBundle(room()?.id);
      loadDrawerJoinRequests();
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  const jrDecline = e.target.closest('[data-jr-decline]');
  if (jrDecline){
    try{
      const { error } = await sb.rpc('decline_join_request', { p_request_id: jrDecline.dataset.jrDecline });
      if (error) throw error;
      toast('Request declined');
      loadDrawerJoinRequests();
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('[data-go-plan]')){
    openPrivateProfile('plan');
    renderAll();
    return;
  }
  if (e.target.closest('[data-gcal-connect]')){
    await connectGoogleCalendar();
    return;
  }
  if (e.target.closest('[data-gcal-sync]')){
    await syncGoogleCalendar({ quiet: false });
    return;
  }
  if (e.target.closest('[data-gcal-disconnect]')){
    await disconnectGoogleCalendar();
    return;
  }
  if (e.target.closest('[data-notion-connect]')){
    await connectNotion();
    return;
  }
  if (e.target.closest('[data-notion-reconnect]')){
    await reconnectNotion();
    return;
  }
  if (e.target.closest('[data-notion-push]')){
    await pushTodayToNotion({ quiet: false });
    return;
  }
  if (e.target.closest('[data-notion-disconnect]')){
    await disconnectNotion();
    return;
  }
  if (e.target.closest('[data-telegram-connect]')){
    await connectTelegram();
    return;
  }
  if (e.target.closest('[data-telegram-link-help]')){
    if (state.telegramPending){
      state.telegramPending = { ...state.telegramPending, showHelp: true };
      renderAll();
    }
    return;
  }
  if (e.target.closest('[data-telegram-copy-code]')){
    const code = state.telegramPending?.code;
    if (!code){ toast('Connect again first'); return; }
    try{
      await navigator.clipboard.writeText(code);
      toast('Code copied — paste it in the Mylo bot');
    }catch{
      toast(`Send this in Telegram: ${code}`);
    }
    return;
  }
  if (e.target.closest('[data-telegram-reminders]')){
    const btn = e.target.closest('[data-telegram-reminders]');
    await setTelegramReminders(btn.dataset.telegramReminders === '1');
    return;
  }
  if (e.target.closest('[data-telegram-disconnect]')){
    await disconnectTelegram();
    return;
  }
  if (e.target.closest('[data-whatsapp-connect]')){
    await connectWhatsapp();
    return;
  }
  if (e.target.closest('[data-whatsapp-reminders]')){
    const btn = e.target.closest('[data-whatsapp-reminders]');
    await setWhatsappReminders(btn.dataset.whatsappReminders === '1');
    return;
  }
  if (e.target.closest('[data-whatsapp-disconnect]')){
    await disconnectWhatsapp();
    return;
  }
  if (e.target.closest('#mylo-send') || e.target.closest('#mylo-chat-send')){
    // Handled by bindChatComposer (pointerup) — needed for mobile
    return;
  }
  const voiceAct = e.target.closest('[data-mylo-voice]');
  if (voiceAct){
    e.preventDefault();
    await handleMyloVoiceAction(voiceAct.dataset.myloVoice);
    return;
  }
  if (e.target.closest('#mylo-mic') || e.target.closest('#mylo-chat-mic')){ toggleMyloMic(); return; }
  if (e.target.closest('#mylo-add')){ await confirmMyloGoals(); return; }
  if (e.target.closest('#mylo-discard')){
    myloDrafts = [];
    myloRenderDrafts([]);
    myloAppendBubble('ai', 'Okay — tell me something else whenever you’re ready.');
    return;
  }
  const catTab = e.target.closest('[data-cat-tab]');
  if (catTab){ state.catTab = catTab.dataset.catTab; renderAll(); return; }
  if (e.target.closest('#btn-add-routine') || e.target.closest('[data-add-routine]')){ openRoutineSheet(); return; }
  const rEdit = e.target.closest('[data-routine-edit]');
  if (rEdit){ openRoutineSheet(rEdit.dataset.routineEdit); return; }
  const rTick = e.target.closest('[data-routine-tick]');
  if (rTick){ await toggleRoutineCheck(rTick.dataset.routineTick); return; }
  const rDel = e.target.closest('[data-routine-del]');
  if (rDel){ await deleteRoutineItem(rDel.dataset.routineDel); return; }
  if (e.target.closest('#routine-save')){ await saveRoutineFromSheet(); return; }
  if (e.target.closest('[data-edit-bio]') || e.target.closest('[data-edit-profile]')){ openBioSheet(); return; }
  if (e.target.closest('[data-share-profile]')){ await shareMyProfile(); return; }
  if (e.target.closest('#bio-save')){ await saveBioFromSheet(); return; }
  const editJump = e.target.closest('[data-edit-jump]');
  if (editJump){
    const to = editJump.dataset.editJump;
    stashEditDraft();
    closeSheets();
    if (to === 'look'){
      state.lookStudioTab = me()?.avatar_url ? 'photo' : 'avatar';
      state.lookMode = state.lookStudioTab === 'photo' ? 'photo' : 'avatar';
      if (window.avatarKit){
        const layered = avatarKit.lookFromProfile(me());
        state.lookDraft = layered
          ? { ...avatarKit.normalizeLook(layered), bg: currentLookBg() }
          : { ...avatarKit.defaultLook(), bg: currentLookBg(), character: resolveChar(me()) };
      } else {
        state.lookDraft = { character: resolveChar(me()), bg: currentLookBg() };
      }
      state.lookDirty = false;
      state.lookCat = 'color';
    }
    navigateAccountPanel(to === 'look' ? 'look' : to);
    renderAll();
    return;
  }
  const setCoverBtn = e.target.closest('[data-set-cover]');
  if (setCoverBtn){ await setCover(setCoverBtn.dataset.setCover); return; }
  if (e.target.closest('[data-cover-reset]')){ await setCover(''); return; }
  if (e.target.closest('#cover-upload-btn')){ (e.target.closest('#m-you, #view')||document).querySelector('#cover-file')?.click(); return; }
  const intgMore = e.target.closest('[data-intg-more]');
  if (intgMore){
    const k = intgMore.dataset.intgMore;
    state.intgOpen = state.intgOpen || {};
    if (state.intgOpen[k]) delete state.intgOpen[k]; else state.intgOpen[k] = true;
    renderAll();
    return;
  }
  const personBtn = e.target.closest('[data-person]');
  if (personBtn){ openPersonSheet(personBtn.dataset.person); return; }
  if (e.target.closest('#person-nick-save')){
    const sheet = $('#person-sheet');
    const pid = sheet?.dataset.pid;
    const val = (sheet?.querySelector('#person-nick')?.value || '');
    if (pid){ setNickname(pid, val); closeSheets(); renderAll(); toast(val.trim() ? 'Name saved' : 'Name reset'); }
    return;
  }
  if (e.target.closest('#chat-nick-save')){
    const btn = e.target.closest('#chat-nick-save');
    const pid = btn?.dataset?.pid || state.chatPeerId;
    const val = ($('#chat-nick')?.value || '');
    if (pid){
      setNickname(pid, val);
      renderAll();
      openChatSettings();
      toast(val.trim() ? 'Name saved' : 'Name reset');
    }
    return;
  }
  const viewFromChat = e.target.closest('[data-chat-view-profile]');
  if (viewFromChat){
    const pid = viewFromChat.dataset.chatViewProfile;
    closeSheets();
    openPersonSheet(pid, { fromChat: true });
    return;
  }
  if (e.target.closest('#sec-pass-save')){
    const a = (youEl('sec-pass')?.value || '');
    const b = (youEl('sec-pass2')?.value || '');
    if (a.length < 8){ toast('Password needs 8+ characters'); return; }
    if (a !== b){ toast('Passwords don’t match'); return; }
    try{
      const { error } = await sb.auth.updateUser({ password: a });
      if (error) throw error;
      if (youEl('sec-pass')) youEl('sec-pass').value = '';
      if (youEl('sec-pass2')) youEl('sec-pass2').value = '';
      toast('Password updated');
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('#sec-google-link')){
    await linkGoogleIdentity();
    return;
  }
  if (e.target.closest('[data-ms-new]')){ openMilestoneSheet(); return; }
  const msOpen = e.target.closest('[data-ms-open]');
  if (msOpen){ openMsBoard(msOpen.dataset.msOpen); return; }
  if (e.target.closest('[data-ms-back]')){ state.chatView = 'mslist'; renderAll(); return; }
  if (e.target.closest('[data-ms-exit]')){ state.chatView = 'list'; goMobileScreen('chat'); renderAll(); return; }
  const msTick = e.target.closest('[data-ms-tick]');
  if (msTick){ if (!msTick.disabled) await toggleItem(msTick.dataset.msTick); return; }
  const msEdit = e.target.closest('[data-ms-edit]');
  if (msEdit){ openMilestoneSheet(msEdit.dataset.msEdit); return; }
  if (e.target.closest('#ms-item-add')){
    const inp = (chatSurface().querySelector('#ms-item-in')) || $('#ms-item-in');
    const val = inp?.value || '';
    if (inp) inp.value = '';
    if (val.trim() && state.msBoardId){ await addItem(state.msBoardId, val); setTimeout(()=>inp?.focus(),10); }
    return;
  }
  if (e.target.closest('#ms-save')){ await saveMilestoneFromSheet(); return; }
  const addDay = e.target.closest('[data-add-day]');
  if (addDay){
    const day = addDay.dataset.addDay;
    if (day && day < TODAY_ISO){ toast('Past days are locked'); return; }
    selectedDay = day;
    openGoalSheet(null, selectedDay);
    return;
  }
  const addShared = e.target.closest('[data-add-shared]');
  if (addShared){ const prev = state.goalScope; state.goalScope = 'shared'; openGoalSheet(null); state.goalScope = prev; return; }
  if (e.target.closest('[data-add-goal]')){
    openGoalSheet(null, isViewingToday() ? TODAY_ISO : todayFocusIso());
    return;
  }

  const pick = e.target.closest('[data-pick-day]');
  if (pick && !e.target.closest('[data-add-day]')){
    selectedDay = pick.dataset.pickDay;
    const d=new Date(selectedDay+'T00:00:00');
    calCursor=new Date(d.getFullYear(),d.getMonth(),1);
    renderAll();
    return;
  }
  const calExpand = e.target.closest('[data-cal-expand]');
  if (calExpand){
    const key = calExpand.dataset.calExpand;
    state.calExpand = state.calExpand || {};
    const [dateIso, uid] = String(key).split(':');
    const preferOpen = (uid === me()?.id)
      || calFilter === 'mine'
      || (calFilter && calFilter.startsWith('user:'));
    const cur = Object.prototype.hasOwnProperty.call(state.calExpand, key)
      ? !!state.calExpand[key]
      : preferOpen;
    state.calExpand[key] = !cur;
    renderAll();
    return;
  }

  const cal = e.target.closest('[data-cal]');
  if (cal){
    const v = +cal.dataset.cal;
    if (v===0){ calCursor=new Date(TODAY.getFullYear(),TODAY.getMonth(),1); selectedDay=TODAY_ISO; }
    else calCursor=new Date(calCursor.getFullYear(), calCursor.getMonth()+v, 1);
    renderAll(); return;
  }
  const cf = e.target.closest('[data-cfilter]');
  if (cf){ calFilter = cf.dataset.cfilter; renderAll(); return; }

  const todayFilter = e.target.closest('[data-today-filter]');
  if (todayFilter){
    state.todayFilter = todayFilter.dataset.todayFilter;
    if (state.todayFilter === 'todo') state.todayShowDone = false;
    renderAll();
    return;
  }
  if (e.target.closest('[data-goal-scope-menu]')){
    openGoalScopeMenu();
    return;
  }
  if (e.target.closest('[data-goal-scope-close]')){
    closeGoalScopeMenu();
    return;
  }
  const scopeOpt = e.target.closest('[data-set-goal-scope]');
  if (scopeOpt){
    state.goalScope = scopeOpt.dataset.setGoalScope || 'day';
    saveNav({ goalScope: state.goalScope });
    closeGoalScopeMenu();
    renderAll();
    return;
  }

  const todayFocus = e.target.closest('[data-today-focus]');
  if (todayFocus){
    const next = todayFocus.dataset.todayFocus || TODAY_ISO;
    state.todayFocus = next === TODAY_ISO ? null : next;
    state.todayFilter = 'todo';
    state.todayShowDone = false;
    renderAll();
    // Keep the selected chip in view on the scrollable strip
    requestAnimationFrame(() => {
      document.querySelectorAll('.wk-day.on').forEach(el => {
        el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
      });
    });
    return;
  }

  const goalTab = e.target.closest('[data-goal-tab]');
  if (goalTab){ state.goalTab = goalTab.dataset.goalTab; renderAll(); return; }

  if (e.target.closest('#btn-add-cat') || e.target.closest('[data-add-cat]')){ openCatSheet(); return; }
  if (e.target.closest('[data-open-edit-profile]')){ openBioSheet(); return; }
  if (e.target.closest('[data-open-security]')){ openAccountPanel('security'); return; }
  if (
    e.target.closest('#sheet-close') || e.target.closest('#sheet-done') ||
    e.target.closest('#cat-close') || e.target.closest('#cat-cancel') ||
    e.target.closest('#plus-close') || e.target.closest('[data-sheet-close]') ||
    e.target.closest('#scrim')
  ){ closeSheets(); return; }
  if (e.target.closest('#sheet-save')){ await saveGoal(false); return; }
  if (e.target.closest('#sheet-sub-add')){
    const val = ($('#in-subgoal')?.value || '').trim();
    if (!val){ toast('Write a step first'); return; }
    if (editGoalId){
      await addSubgoal(editGoalId, val);
      if ($('#in-subgoal')) $('#in-subgoal').value = '';
      renderSheetSubs();
    } else {
      state.draftSubgoals = [...(state.draftSubgoals || []), val];
      if ($('#in-subgoal')) $('#in-subgoal').value = '';
      renderSheetSubs();
    }
    return;
  }
  const subRemove = e.target.closest('[data-sub-remove]');
  if (subRemove){
    const saved = subRemove.dataset.subSaved === '1';
    const ref = subRemove.dataset.subRemove;
    if (saved){
      await deleteSubgoal(ref);
      renderSheetSubs();
    } else {
      const i = Number(ref);
      state.draftSubgoals = (state.draftSubgoals || []).filter((_, idx) => idx !== i);
      renderSheetSubs();
    }
    return;
  }
  if (e.target.closest('#cat-save')){ await saveCat(); return; }
  if (e.target.closest('#chat-plus')){
    // Handled by bindChatComposer
    return;
  }
  if (e.target.closest('#chat-send')){
    // Handled by bindChatComposer
    return;
  }

  if (e.target.closest('[data-install-later]')){ dismissInstall(); return; }
  if (e.target.closest('[data-install-go]')){ await runInstall(); return; }

  if (e.target.closest('[data-scw-open]')){ state._scwOpen = !state._scwOpen; state._scwFocus = null; paintScWords(); return; }
  if (e.target.closest('[data-scw-close]')){ state._scwOpen = false; paintScWords(); return; }
  const scwWord = e.target.closest('[data-scw-word]');
  if (scwWord){
    state._scwOpen = true; state._scwFocus = scwWord.dataset.scwWord; state._scChip = null;
    paintScWords();
    return;
  }
  if (e.target.closest('[data-daydone-close]')){ closeDayDone(); return; }
  if (e.target.closest('[data-daydone-share]')){ await shareDayDone(); return; }
  // ---- lock in ----
  if (e.target.closest('[data-focus-open]')){ openFocusSheet(); return; }
  if (e.target.closest('[data-focus-cancel]')){ closeFocusSheet(); return; }
  const fMins = e.target.closest('[data-focus-mins]');
  if (fMins){
    if (state._focusPick){ state._focusPick.mins = Number(fMins.dataset.focusMins); renderFocusSheet(); }
    return;
  }
  const fTodo = e.target.closest('[data-focus-todo]');
  if (fTodo){
    const p = state._focusPick; if (!p) return;
    const id = fTodo.dataset.focusTodo;
    const i = p.todos.indexOf(id);
    if (i >= 0) p.todos.splice(i, 1); else p.todos.push(id);
    renderFocusSheet();
    return;
  }
  if (e.target.closest('[data-focus-go]')){
    const p = state._focusPick; if (!p) return;
    const mins = p.mins, todos = p.todos.slice();
    closeFocusSheet();
    await startFocus(mins, todos);
    return;
  }
  if (e.target.closest('[data-focus-end]')){
    if (focusDone()){ await endFocus({ finished: true }); return; }
    if (!confirm('End the session early? No XP for this one.')) return;
    await endFocus();
    return;
  }

  if (e.target.closest('[data-app-back]')){ state.appView = null; renderAll(); return; }
  if (e.target.closest('#jr-save')){ await saveJournalFromView(); return; }
  const jrTab = e.target.closest('[data-jr-tab]');
  if (jrTab){ state.jrTab = jrTab.dataset.jrTab; renderAll(); return; }
  const notePin = e.target.closest('[data-note-pin]');
  if (notePin){ const n = (state.notes || []).find(x => x.id === notePin.dataset.notePin); pinNote(notePin.dataset.notePin, !n?.pinned); return; }
  const noteCopy = e.target.closest('[data-note-copy]');
  if (noteCopy){
    const n = (state.notes || []).find(x => x.id === noteCopy.dataset.noteCopy);
    try{ await navigator.clipboard.writeText(n?.text || ''); toast('Copied'); }catch(_){ toast('Could not copy'); }
    return;
  }
  const noteDel = e.target.closest('[data-note-del]');
  if (noteDel){ if (confirm('Delete this note?')) deleteNote(noteDel.dataset.noteDel); return; }
  // ---- vibe ----
  if (e.target.closest('[data-vibe-new]')){ openVibeSheet(); return; }
  if (e.target.closest('[data-vibe-post]')){ await postVibe(); return; }
  const vLike = e.target.closest('[data-vibe-like]');
  if (vLike){ toggleVibeLike(vLike.dataset.vibeLike); return; }
  const vCopy = e.target.closest('[data-vibe-copy]');
  if (vCopy){
    const v = (state.vibe || []).find(x => x.id === vCopy.dataset.vibeCopy);
    try{ await navigator.clipboard.writeText(vibeShareText(v)); toast('Copied'); }catch(_){ toast('Could not copy'); }
    return;
  }
  if (e.target.closest('[data-cardprev-close]')){ closeCardPreview(); return; }
  if (e.target.closest('[data-cardprev-save]')){ await saveCardPreview(); return; }
  if (e.target.closest('[data-cardprev-story]')){ await cardPreviewToStory(); return; }
  const cardTh = e.target.closest('[data-card-theme]');
  if (cardTh && state._cardPreview){
    state._cardPreview.theme = cardTh.dataset.cardTheme;
    rememberCardTheme(cardTh.dataset.cardTheme);
    paintCardPreview();
    return;
  }
  if (e.target.closest('[data-vibe-back]')){ closeVibeThread(); return; }
  const vOpen = e.target.closest('[data-vibe-open]');
  if (vOpen){ openVibeThread(vOpen.dataset.vibeOpen); return; }
  if (e.target.closest('[data-vibe-reply]')){ await sendVibeReply(); return; }
  const vRepDel = e.target.closest('[data-vibe-repdel]');
  if (vRepDel){ if (confirm('Delete this reply?')) deleteVibeReply(vRepDel.dataset.vibeRepdel); return; }
  const vMenu = e.target.closest('[data-vibe-menu]');
  if (vMenu){ openVibeMenu(vMenu.dataset.vibeMenu); return; }
  const vTip = e.target.closest('[data-vibe-tip]');
  if (vTip){ openVibeTip(vTip.dataset.vibeTip); return; }
  const vTipAmt = e.target.closest('[data-vibe-tip-amt]');
  if (vTipAmt){ await tipVibe(vTipAmt.dataset.vibeTipId, vTipAmt.dataset.vibeTipAmt); return; }
  const vEdit = e.target.closest('[data-vibe-edit]');
  if (vEdit){ openVibeEdit(vEdit.dataset.vibeEdit); return; }
  const vSave = e.target.closest('[data-vibe-save]');
  if (vSave){ await saveVibeEdit(vSave.dataset.vibeSave); return; }
  const vShare = e.target.closest('[data-vibe-share]');
  if (vShare){ await copyVibeLink(vShare.dataset.vibeShare); return; }
  if (e.target.closest('[data-vibe-pick]')){ $('#vibe-file')?.click(); return; }
  if (e.target.closest('[data-vibe-unpick]')){
    state._vibeShot = null;
    const box = $('#vibe-shot'); if (box) box.hidden = true;
    return;
  }
  const vStory = e.target.closest('[data-vibe-story]');
  if (vStory){ closeSheets(); vibeToStory(vStory.dataset.vibeStory).catch(err => notify(errMsg(err))); return; }
  const vDl = e.target.closest('[data-vibe-dl]');
  if (vDl){ closeSheets(); downloadVibeCard(vDl.dataset.vibeDl).catch(err => notify(errMsg(err))); return; }
  const vDel = e.target.closest('[data-vibe-del]');
  if (vDel){
    closeSheets();
    if (confirm('Delete this post?')){
      if (state.vibeThread === vDel.dataset.vibeDel) state.vibeThread = null;
      deleteVibe(vDel.dataset.vibeDel);
    }
    return;
  }
  if (e.target.closest('[data-import-todos]')){ openImportTodos(); return; }
  const impFrom = e.target.closest('[data-import-from]');
  if (impFrom){ await importTodosFrom(impFrom.dataset.importFrom); return; }
  if (e.target.closest('[data-jr-ask]')){
    /* The plus used to leave the page for the Mylo chat, which read as a bug —
       you tapped + on a journal and lost the journal. Now it puts the cursor in
       the line. Asking Mylo is still there, as the link in the empty state. */
    const box = $('#jr-in');
    if (box){ box.focus(); box.scrollIntoView({ block: 'center', behavior: 'smooth' }); }
    return;
  }
  if (e.target.closest('[data-jr-mylo]')){ state.appView = null; renderAll(); openMylo(); return; }
  if (e.target.closest('[data-sub-new]')){ openSubSheet(); return; }
  if (e.target.closest('#sub-save')){ await saveSubFromSheet(); return; }
  const subDel = e.target.closest('[data-sub-del]');
  if (subDel){ await deleteSub(subDel.dataset.subDel); return; }
  const subPreset = e.target.closest('[data-sub-preset]');
  if (subPreset){
    const n = $('#sub-name'); if (n) n.value = subPreset.dataset.subPreset;
    const c = $('#sub-colour'); if (c) c.value = subPreset.dataset.subColour || '#8A8A8A';
    $$('.sub-chip').forEach(b => b.classList.toggle('is-on', b === subPreset));
    return;
  }
  const subPerson = e.target.closest('[data-sub-person]');
  if (subPerson){ subPerson.classList.toggle('is-on'); return; }

  // ---- wallet ----
  if (e.target.closest('#m-myl-pill') || e.target.closest('[data-open-wallet]')){
    if (FEATURES.wallet) openWallet('main');
    return;
  }
  if (e.target.closest('[data-wallet-send]')){ state.walletView = 'send'; renderAll(); syncMobileTopBar('today'); return; }
  if (e.target.closest('[data-wallet-earn]')){ state.walletView = 'earn'; renderAll(); syncMobileTopBar('today'); return; }
  const wTab = e.target.closest('[data-wallet-tab]');
  if (wTab){
    const want = wTab.dataset.walletTab;
    state.walletView = (want === 'board' && !FEATURES.leaderboard) ? 'main' : want;
    renderAll(); syncMobileTopBar('today'); return;
  }
  if (e.target.closest('[data-wallet-store]')){
    // Spend shows where the $MYL went. The store is a button inside it.
    state.walletView = 'history';
    state.walletFilter = 'spent';
    renderAll(); syncMobileTopBar('today');
    return;
  }
  if (e.target.closest('[data-wallet-shop]')){
    closeWallet();
    state.appsTab = 'store';
    goMobileScreen('apps');
    renderAll();
    return;
  }
  const wFilter = e.target.closest('[data-wallet-filter]');
  if (wFilter){ state.walletFilter = wFilter.dataset.walletFilter; renderAll(); return; }
  if (e.target.closest('[data-wallet-history]')){
    state.walletView = 'history'; renderAll(); syncMobileTopBar('today'); return;
  }
  const wTo = e.target.closest('[data-wallet-to]');
  if (wTo){
    state.walletTo = wTo.dataset.walletTo;
    $$('[data-wallet-to]').forEach(b => b.classList.toggle('on', b.dataset.walletTo === state.walletTo));
    return;
  }
  const wAmt = e.target.closest('[data-wallet-amt]');
  if (wAmt){
    const f = $('#wal-amount');
    if (f){ f.value = wAmt.dataset.walletAmt; f.focus(); }
    return;
  }
  if (e.target.closest('[data-wallet-confirm]')){ await sendMyl(); return; }
  const buy = e.target.closest('[data-buy-app]');
  if (buy){ await buyApp(buy.dataset.buyApp); return; }

  // ---- calls ----
  const callStart = e.target.closest('[data-call-start]');
  if (callStart){
    // Calls are parked. STUN-only calling fails on too many real networks to
    // ship as a working feature, so the button says so instead of half-working.
    notify('Voice calls are coming soon');
    return;
  }
  if (e.target.closest('[data-call-accept]')){ await acceptCall(); return; }
  if (e.target.closest('[data-call-decline]')){ declineCall(); return; }
  if (e.target.closest('[data-call-end]')){ endCall(); return; }
  if (e.target.closest('[data-call-mute]')){ toggleCallMute(); return; }

  // ---- chat list edit mode ----
  if (e.target.closest('[data-chat-edit]')){
    state.chatEdit = !state.chatEdit;
    state.chatSel = new Set();
    renderChatOnly();
    syncChatHeader('chat');
    return;
  }
  const chatPick = e.target.closest('[data-chat-pick]');
  if (chatPick){
    state.chatSel = state.chatSel || new Set();
    const id = chatPick.dataset.chatPick;
    if (state.chatSel.has(id)) state.chatSel.delete(id); else state.chatSel.add(id);
    renderChatOnly();
    return;
  }
  const bulk = e.target.closest('[data-chat-bulk]');
  if (bulk){
    const ids = [...(state.chatSel || [])];
    if (!ids.length) return;
    const what = bulk.dataset.chatBulk;
    if (what === 'read'){
      ids.forEach(id => { delete state.unreadByRoom[id]; });
      updateChatBadge();
    } else if (what === 'archive'){
      for (const id of ids) await setChatPref(id, 'archive', 1);
    } else if (what === 'delete'){
      // No server-side delete for a room, so this hides it for you only —
      // the same personal archive flag, flying under a blunter name.
      for (const id of ids) await setChatPref(id, 'archive', 1);
      notify(ids.length === 1 ? 'Chat hidden' : `${ids.length} chats hidden`);
    }
    state.chatEdit = false;
    state.chatSel = new Set();
    renderChatOnly();
    syncChatHeader('chat');
    return;
  }
  if (e.target.closest('[data-new-chat]')){
    state.chatTab = 'people';
    renderChatOnly();
    return;
  }

  // ---- stories ----
  if (e.target.closest('[data-story-peek]')){
    if (focusActive()){ notify(`Statuses are shut — ${fmtDur(focusLeftMs())} left`); return; }
    setStoryOpen(!state.storyOpen);
    return;
  }
  if (e.target.closest('[data-story-new]')){ openStorySheet(null); return; }
  const storyRef = e.target.closest('[data-open-story-ref]');
  if (storyRef){
    const id = storyRef.dataset.openStoryRef;
    const item = (state.stories || []).find(x => x.id === id);
    if (!item){ toast('That story has gone'); return; }
    const idx = (state.stories || []).filter(x => x.by === item.by).findIndex(x => x.id === id);
    openStoryViewer(item.by, Math.max(0, idx));
    return;
  }
  const storyOpen = e.target.closest('[data-story-open]');
  if (storyOpen){
    if (focusActive()){ notify(`Statuses are shut — ${fmtDur(focusLeftMs())} left`); return; }
    openStoryViewer(storyOpen.dataset.storyOpen, 0);
    return;
  }
  if (e.target.closest('[data-story-close]')){ closeStoryViewer(); return; }
  if (e.target.closest('[data-story-viewers]')){ openStoryViewers(); return; }
  if (e.target.closest('[data-story-viewers-close]')){ closeStoryViewers(); return; }
  if (e.target.closest('[data-story-scope]')){
    const d = state._storyDraft;
    if (d){
      d.scope = d.scope === 'public' ? 'room' : 'public';
      renderStoryComposer();
      toast(d.scope === 'public' ? 'Public — shows on the rooms feed' : 'This room only');
    }
    return;
  }
  if (e.target.closest('[data-feed-story-close]')){ closeFeedStory(); return; }
  const fStep = e.target.closest('[data-feed-story-step]');
  if (fStep){
    const n = (state.feedStoryIdx || 0) + Number(fStep.dataset.feedStoryStep);
    if (n < 0 || n >= (state.homeStories || []).length) closeFeedStory();
    else openFeedStory(n);
    return;
  }
  const likeBtn = e.target.closest('[data-story-like]');
  if (likeBtn){ toggleStoryLike(likeBtn.dataset.storyLike); return; }
  const replyBtn = e.target.closest('[data-story-reply]');
  if (replyBtn){
    const box = $('#story-reply-in');
    const text = box?.value || '';
    if (!text.trim()){ box?.focus(); return; }
    replyToStory(replyBtn.dataset.storyReply, text);
    return;
  }
  // Typing a reply must not count as "tap to advance".
  if (e.target.closest('.story-reply, .story-viewers')) return;
  const storyStepBtn = e.target.closest('[data-story-step]');
  if (storyStepBtn){ storyStep(Number(storyStepBtn.dataset.storyStep)); return; }
  const storyDel = e.target.closest('[data-story-del]');
  if (storyDel){ await deleteStory(storyDel.dataset.storyDel); return; }
  if (e.target.closest('[data-story-pick]')){ $('#story-file')?.click(); return; }
  if (e.target.closest('[data-photo-replay]')){
    const d = state._storyDraft; if (!d) return;
    d.replay = !d.replay;
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    renderStoryComposer();
    return;
  }
  if (e.target.closest('[data-photo-streak]')){
    const d = state._storyDraft; if (!d) return;
    d.streak = !d.streak;
    if (!d.streak) d.replay = false;      // no streak, nothing to replay
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    if (d.streak) try{ navigator.vibrate?.(10); }catch(_){}
    renderStoryComposer();
    return;
  }
  if (e.target.closest('[data-story-cancel]')){ closeStoryComposer(); return; }
  const ovDel = e.target.closest('[data-ov-del]');
  if (ovDel){
    const d = state._storyDraft; if (!d) return;
    d.overlays.splice(Number(ovDel.dataset.ovDel), 1);
    renderStoryComposer();
    return;
  }
  const trayBtn = e.target.closest('[data-story-tray]');
  if (trayBtn){
    const d = state._storyDraft; if (!d) return;
    const want = trayBtn.dataset.storyTray || null;
    d.tray = (d.tray === want || !want) ? null : want;
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    renderStoryComposer();
    return;
  }
  const storyTodo = e.target.closest('[data-story-todo]');
  if (storyTodo){
    const d = state._storyDraft; if (!d) return;
    const id = storyTodo.dataset.storyTodo;
    d.overlays = d.overlays.filter(o => o.kind !== 'todo');
    d.overlays.push({ kind: 'todo', id, text: storyTodo.textContent.trim(), x: 50, y: 62 });
    d.todo = id; d.todoTitle = storyTodo.textContent.trim();
    d.tray = null;
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    renderStoryComposer();
    return;
  }
  const stickerPick = e.target.closest('[data-story-sticker]');
  if (stickerPick){
    const d = state._storyDraft; if (!d) return;
    d.overlays.push({ kind: 'sticker', id: stickerPick.dataset.storySticker, x: 50, y: 45 });
    d.tray = null;
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    renderStoryComposer();
    return;
  }
  const timerPick = e.target.closest('[data-story-timer]');
  if (timerPick){
    const d = state._storyDraft; if (!d) return;
    const [n, l] = timerPick.dataset.storyTimer.split('|');
    d.overlays.push({ kind: 'timer', text: n, label: l, x: 50, y: 30 });
    d.tray = null;
    d.caption = ($('#sy-cap')?.value ?? d.caption);
    renderStoryComposer();
    return;
  }
  if (e.target.closest('[data-story-post]')){
    const d = state._storyDraft || {};
    if (!d.blob){ notify('Pick a photo first'); return; }
    d.caption = ($('#sy-cap')?.value || '').trim();
    const baked = await bakeStoryCrop();
    const ok = d.mode === 'chat'
      ? await sendComposedPhoto({ ...d, blob: baked || d.blob, w: 1080, h: 1920 })
      : await postStory({ ...d, blob: baked || d.blob, w: 1080, h: 1920 });
    if (ok) closeStoryComposer();
    return;
  }
  const snapOpen = e.target.closest('[data-open-snap]');
  if (snapOpen){ await openSnap(snapOpen.dataset.openSnap); return; }

  const prefBtn = e.target.closest('[data-chat-pref]');
  if (prefBtn){
    const id = prefBtn.dataset.chatPref, key = prefBtn.dataset.key;
    const val = prefBtn.dataset.value ? 1 : null;
    if (key === 'lock' && val && !chatLockCode()){
      const code = String(prompt('Set a passcode for locked chats') || '').trim();
      if (!/^\d{4,8}$/.test(code)){ notify('Use 4 to 8 digits'); return; }
      setChatLockCode(code);
    }
    $$('.chat-swipe').forEach(w => { w.classList.remove('is-open-l','is-open-r'); w.style.setProperty('--sx','0px'); });
    await setChatPref(id, key, val);
    return;
  }
  const lockOpen = e.target.closest('[data-lock-open]');
  if (lockOpen){
    const entered = ($('#lock-code')?.value || '').trim();
    if (entered !== chatLockCode()){ notify('Wrong passcode'); return; }
    state._unlocked = state._unlocked || {};
    state._unlocked[lockOpen.dataset.lockOpen] = true;
    closeSheets();
    const go = state._lockThen; state._lockThen = null;
    if (go) go();
    return;
  }

  const todoFold = e.target.closest('[data-todo-fold]');
  if (todoFold){
    const k = todoFold.dataset.todoFold;
    state.todoOpen = state.todoOpen || {};
    state.todoOpen[k] = !state.todoOpen[k];
    renderAll();
    return;
  }

  const deskPanel = e.target.closest('[data-desk-panel]');
  if (deskPanel){
    const k = deskPanel.dataset.deskPanel;
    state.deskPanels = state.deskPanels || {};
    state.deskPanels[k] = !state.deskPanels[k];
    renderAll();
    if (state.deskPanels[k]){
      setTimeout(() => $('#desk-' + k)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }), 40);
    }
    return;
  }

  const winX = e.target.closest('[data-win-seen]');
  if (winX){ winSeen(winX.dataset.winSeen, true); renderAll(); return; }

  // ---- media ----
  const imgOpen = e.target.closest('[data-open-image]');
  if (imgOpen){ openImageViewer(imgOpen.dataset.openImage); return; }
  if (e.target.closest('[data-close-image]') || e.target.id === 'img-viewer'){ closeImageViewer(); return; }
  const vPlay = e.target.closest('[data-voice-play]');
  if (vPlay){ toggleVoice(vPlay.dataset.voicePlay); return; }
  if (e.target.closest('[data-voice-cancel]')){ cancelVoiceNote(); return; }
  if (e.target.closest('[data-voice-send]')){ await stopVoiceNote(true); return; }
  if (e.target.closest('#chat-mic')){ await startVoiceNote(); return; }
  if (e.target.closest('#chat-cam')){ $('#photo-file')?.click(); return; }
  if (e.target.closest('[data-nudge-off]')){ hideNudge(); return; }
  if (e.target.closest('[data-nudge-on]')){ await setAlerts(true); renderChatOnly(); return; }
  if (e.target.closest('[data-pend-drop]')){ clearPendingPhoto(); renderChatOnly(); return; }
  if (e.target.closest('[data-pend-edit]')){
    // Hand the attachment to the full editor, then forget the strip.
    const p = state.pendingPhoto;
    if (!p) return;
    openPhotoComposer({ from: p });
    return;
  }

  // ---- challenges ----
  if (e.target.closest('[data-ch-new]')){ openChallengeSheet(); return; }
  const chWho = e.target.closest('[data-ch-who]');
  if (chWho){
    state._chDraft.to = chWho.dataset.chWho;
    $$('#ch-who .launch-friend').forEach(b => b.classList.toggle('is-on', b === chWho));
    return;
  }
  const chKind = e.target.closest('[data-ch-kind]');
  if (chKind){
    const k = challengeKind(chKind.dataset.chKind);
    state._chDraft.kind = k.id;
    state._chDraft.target = k.def;
    $$('#ch-kinds .ch-kind').forEach(b => b.classList.toggle('on', b === chKind));
    const t = $('#ch-target'); if (t) t.textContent = k.def;
    return;
  }
  const chStep = e.target.closest('[data-ch-step]');
  if (chStep){
    const k = challengeKind(state._chDraft.kind);
    state._chDraft.target = Math.max(1, Math.min(k.max, state._chDraft.target + Number(chStep.dataset.chStep)));
    const t = $('#ch-target'); if (t) t.textContent = state._chDraft.target;
    return;
  }
  const chWin = e.target.closest('[data-ch-win]');
  if (chWin){
    state._chDraft.window = chWin.dataset.chWin;
    $$('[data-ch-win]').forEach(b => b.classList.toggle('on', b === chWin));
    return;
  }
  const chStake = e.target.closest('[data-ch-stake]');
  if (chStake){
    state._chDraft.stake = Number(chStake.dataset.chStake) || 0;
    $$('[data-ch-stake]').forEach(b => b.classList.toggle('on', b === chStake));
    return;
  }
  if (e.target.closest('[data-ch-send]')){
    const d = { ...state._chDraft, note: ($('#ch-note')?.value || '').trim() };
    closeSheets();
    await sendChallenge(d);
    return;
  }
  const chClaim = e.target.closest('[data-ch-claim]');
  if (chClaim){ await claimChallenge(chClaim.dataset.chClaim); return; }
  const chDrop = e.target.closest('[data-ch-drop]');
  if (chDrop){ await cancelChallenge(chDrop.dataset.chDrop); return; }

  // ---- milestones ----
  const msPeople = e.target.closest('[data-ms-people]');
  if (msPeople){ openMsPeople(msPeople.dataset.msPeople); return; }
  const msCrew = e.target.closest('[data-ms-crew]');
  if (msCrew){
    const id = msCrew.dataset.msCrew;
    const set = state._msCrewPick || new Set();
    if (set.has(id)) set.delete(id); else set.add(id);
    msCrew.classList.toggle('is-on', set.has(id));
    return;
  }
  const msSave = e.target.closest('[data-ms-crew-save]');
  if (msSave){
    const board = msSave.dataset.msCrewSave;
    closeSheets();
    await setMsCrew(board, [...(state._msCrewPick || [])]);
    return;
  }
  const msDel = e.target.closest('[data-ms-del]');
  if (msDel){ await deleteMilestone(msDel.dataset.msDel); return; }

  const menuReply = e.target.closest('[data-menu-reply]');
  if (menuReply){ closeSheets(); startReply(menuReply.dataset.menuReply); return; }
  const menuCopy = e.target.closest('[data-menu-copy]');
  if (menuCopy){
    const m = (state.messages || []).find(x => String(x.id) === menuCopy.dataset.menuCopy);
    try{ await navigator.clipboard.writeText(m?.body || ''); }catch(_){}
    closeSheets();
    return;
  }
  const menuDel = e.target.closest('[data-menu-del]');
  if (menuDel){
    closeSheets();
    await deleteMessage(menuDel.dataset.menuDel, menuDel.dataset.scope);
    return;
  }

  const mentionPick = e.target.closest('[data-mention]');
  if (mentionPick){
    const input = mentionPick.closest('.chat-compose')?.querySelector('.chat-in') || $('#chat-in');
    applyMention(input, mentionPick.dataset.mention);
    return;
  }

  // ---- reply ----
  if (e.target.closest('[data-reply-cancel]')){ cancelReply(); return; }
  const quoteJump = e.target.closest('[data-jump-msg]');
  if (quoteJump){ jumpToMsg(quoteJump.dataset.jumpMsg); return; }

  // ---- notifications ----
  if (e.target.closest('[data-open-notifs]')){ openNotifSheet(); return; }
  if (e.target.closest('[data-notif-close]')){ closeNotifPage(); return; }
  if (e.target.closest('[data-notif-settings]')){
    state.notifView = 'settings';
    renderAll();
    syncMobileTopBar('today');
    return;
  }
  if (e.target.closest('[data-notif-back]')){
    state.notifView = 'list';
    renderAll();
    syncMobileTopBar('today');
    return;
  }
  if (e.target.closest('[data-notif-clear]')){
    notifItems().forEach(n => notifDone(n.id));
    updateNotifBadge();
    renderAll();
    return;
  }
  const alertSw = e.target.closest('[data-alerts-toggle]');
  if (alertSw){ await setAlerts(alertSw.checked); return; }
  const nPref = e.target.closest('[data-notif-pref]');
  if (nPref){ setNotifPref(nPref.dataset.notifPref, nPref.checked); return; }
  const msInv = e.target.closest('[data-ms-invite]');
  if (msInv){
    await answerMsInvite(msInv.dataset.msInvite, msInv.dataset.yes === '1');
    return;
  }
  const nGo = e.target.closest('[data-notif-go]');
  if (nGo && !e.target.closest('button:not([data-notif-go])')){
    const dest = nGo.dataset.notifGo;
    notifDone(nGo.dataset.notifId);
    closeNotifPage();
    if (dest === 'challenge') openChallenges();
    else if (dest === 'wallet'){ if (FEATURES.wallet) openWallet('main'); else goMobileScreen('today'); }
    else if (dest === 'chat'){
      const rid = nGo.dataset.notifRef;
      const r = (state.rooms || []).find(x => x.id === rid);
      if (r){ openChatRoom ? openChatRoom(rid) : (state.chatRoom = r, state.chatView = 'thread'); }
      goMobileScreen('chat');
      renderAll();
    }
    else if (dest === 'milestone'){
      state.msBoardId = nGo.dataset.notifRef || null;
      state.chatView = state.msBoardId ? 'msboard' : 'mslist';
      goMobileScreen('chat');
      renderAll();
    }
    return;
  }
  const nAccept = e.target.closest('[data-notif-accept]');
  if (nAccept){
    notifDone(nAccept.dataset.notifAccept);          // never shows again
    closeNotifPage();
    openGameOverlay(nAccept.dataset.notifGame);
    updateNotifBadge();
    return;
  }
  const nReject = e.target.closest('[data-notif-reject]');
  if (nReject){ notifDone(nReject.dataset.notifReject); updateNotifBadge(); renderAll(); return; }
  const nDismiss = e.target.closest('[data-notif-dismiss]');
  if (nDismiss){ notifDone(nDismiss.dataset.notifDismiss); updateNotifBadge(); renderAll(); return; }

  // ---- games ----
  const gStep = e.target.closest('[data-game-step]');
  if (gStep && $('#game-launch-sheet')){
    state._gameStep = gStep.dataset.gameStep || null;
    renderGameLauncher();
    return;
  }
  const gFriend = e.target.closest('[data-game-friend]');
  if (gFriend){
    state._gamePick = state._gamePick || new Set();
    const id = gFriend.dataset.gameFriend;
    const def = gameDefs()[state._gameKind];
    const max = (def?.maxPlayers || 2) - 1;
    if (state._gamePick.has(id)) state._gamePick.delete(id);
    else if (state._gamePick.size < max) state._gamePick.add(id);
    else { toast(`Up to ${max + 1} players`); return; }
    renderGameLauncher();
    return;
  }
  const stakeBtn = e.target.closest('[data-stake]');
  if (stakeBtn){
    state._gameStake = Number(stakeBtn.dataset.stake) || 0;
    $$('#stake-row .stake-btn').forEach(b => b.classList.toggle('on', b === stakeBtn));
    return;
  }
  const gSend = e.target.closest('[data-game-send]');
  if (gSend){
    const picked = [...(state._gamePick || [])];
    if (!picked.length){ toast('Pick who you are playing'); return; }
    await startGame(gSend.dataset.gameSend, picked);
    return;
  }
  const matchStake = e.target.closest('[data-match-stake]');
  if (matchStake){
    const ok = await putUpStake(matchStake.dataset.matchStake, Number(matchStake.dataset.stakeAmt) || 0);
    if (ok){ renderGameOverlay(); renderChatOnly(); }
    return;
  }
  if (e.target.closest('[data-games-store]')){
    closeSheets();
    state.appsTab = 'store';
    goMobileScreen('apps');
    renderAll();
    return;
  }
  const botGame = e.target.closest('[data-game-bot]');
  if (botGame){ startBotGame(botGame.dataset.gameBot); return; }
  const newGame = e.target.closest('[data-new-game]');
  if (newGame){ await startGame(newGame.dataset.newGame); return; }
  const openGame = e.target.closest('[data-open-game]');
  if (openGame){ openGameOverlay(openGame.dataset.openGame); return; }
  const guestLink = e.target.closest('[data-guest-link]');
  if (guestLink){ await createGuestLink(guestLink.dataset.guestLink); return; }
  const glinkCopy = e.target.closest('[data-glink-copy]');
  if (glinkCopy){
    try{ await navigator.clipboard.writeText(glinkCopy.dataset.glinkCopy); toast('Link copied'); }
    catch(_){ $('#glink-in')?.select(); toast('Copy the link'); }
    return;
  }
  const glinkOpen = e.target.closest('[data-glink-open]');
  if (glinkOpen){ location.href = glinkOpen.dataset.glinkOpen; return; }
  const winCard = e.target.closest('[data-win-card]');
  if (winCard){
    downloadWinCard({ game: winCard.dataset.winGame, opponent: winCard.dataset.winOpp })
      .catch(err => notify(errMsg(err)));
    return;
  }
  if (e.target.closest('[data-game-close]')){ closeGameOverlay(); return; }
  const csq = e.target.closest('[data-csq]');
  if (csq && !csq.disabled){ await onChessSquare(Number(csq.dataset.csq)); return; }
  const scSq = e.target.closest('[data-sc-sq]');
  if (scSq && !scSq.disabled){ await onScSquare(Number(scSq.dataset.scSq)); return; }
  const scRack = e.target.closest('[data-sc-rack]');
  if (scRack && !scRack.disabled){
    const d = scDraft();
    const k = Number(scRack.dataset.scRack);
    d.sel = d.sel === k ? null : k;
    renderGameOverlay();
    return;
  }
  if (e.target.closest('[data-sc-recall]')){ scResetDraft(); renderGameOverlay(); return; }
  if (e.target.closest('[data-sc-submit]')){ await onScSubmit(); return; }
  if (e.target.closest('[data-sc-pass]')){ await onScPass(); return; }
  const rcard = e.target.closest('[data-rush-card]');
  if (rcard && !rcard.disabled){ await onRushPlay(Number(rcard.dataset.rushCard)); return; }
  const rdraw = e.target.closest('[data-rush-draw]');
  if (rdraw && !rdraw.disabled && rdraw.getAttribute('aria-disabled') !== 'true'){ await onRushDraw(); return; }
  const pcard = e.target.closest('[data-card]');
  if (pcard && !pcard.disabled){ await onCardPlay(Number(pcard.dataset.card)); return; }
  const cdraw = e.target.closest('[data-card-draw]');
  if (cdraw && !cdraw.disabled){ await onCardDraw(); return; }

  const plus = e.target.closest('[data-plus]');
  if (plus){
    const action = plus.dataset.plus;
    if (action === 'photo'){ closeSheets(); $('#photo-file')?.click(); }
    else if (action === 'streak'){ closeSheets(); openPhotoComposer({ streak: true }); }
    else if (action === 'story'){ closeSheets(); openStorySheet(null); }
    else if (action === 'voice'){ closeSheets(); startVoiceNote(); }
    else if (action === 'myl'){ closeSheets(); openWallet('send'); }
    else if (action === 'sticker') openStickerSheet();
    else if (action === 'cheer') openCheerSheet();
    else if (action === 'poll') openPollSheet();
    else if (action === 'game') openGamesSheet();
    else if (action === 'note') await openNoteSheet();
    else if (action === 'task') openTaskSheet();
    else if (action === 'mylo'){ closeSheets(); openMylo(); }
    else if (action === 'settings') openChatSettings();
    else if (action === 'group'){
      if (!canUseGroupChat()){
        toast('Groups need 3+ people in the room');
        return;
      }
      closeSheets();
      openSheet('#group-sheet');
      if (window.matchMedia('(hover:hover) and (pointer:fine)').matches){
        setTimeout(() => $('#group-title')?.focus(), 40);
      }
    }
    return;
  }

  const chatTab = e.target.closest('[data-chat-tab]');
  if (chatTab){
    state.chatTab = chatTab.dataset.chatTab;
    state.chatView = 'list';
    state.chatRoom = null;
    state.chatPeerId = null;
    state.messages = [];
    renderAll();
    return;
  }
  const enterRoomBtn = e.target.closest('[data-enter-room]');
  if (enterRoomBtn){
    try{
      await openRoom(enterRoomBtn.dataset.enterRoom);
      toast('Opened '+ (room()?.title || 'room'));
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('[data-go-home]')){
    await loadRoomsList();
    enterHome();
    return;
  }
  if (e.target.closest('[data-open-room-gate]')){
    syncBrowseLink();
    openSheet('#room-sheet');
    return;
  }
  const openDmBtn = e.target.closest('[data-open-dm]');
  if (openDmBtn){
    try{ await openDmWith(openDmBtn.dataset.openDm); }
    catch(err){ notify(errMsg(err)); }
    return;
  }
  const openChatBtn = e.target.closest('[data-open-chat]');
  if (openChatBtn){
    // A swipe that ended open must not also count as a tap on the row.
    if (openChatBtn.closest('.chat-swipe.is-open-l, .chat-swipe.is-open-r')) return;
    const gateId = openChatBtn.dataset.openChat;
    if (chatPref(gateId, 'lock') && !chatUnlocked(gateId)){
      promptChatLock(gateId, () => document.querySelector(`[data-open-chat="${CSS.escape(gateId)}"]`)?.click());
      return;
    }
    try{
      const rid = openChatBtn.dataset.openChat;
      const row = state.rooms.find(r => r.id === rid);
      if (row?.kind === 'group' && !canUseGroupChat()){
        const peer = otherMembers()[0];
        if (peer){ await openDmWith(peer.id); return; }
        toast('Private chats only until 3+ people share this room');
        return;
      }
      await openChatRoom(rid);
      goMobileScreen('chat');
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('[data-open-group]')){
    try{
      if (!canUseGroupChat()){
        const peer = otherMembers()[0];
        if (peer){ await openDmWith(peer.id); return; }
        toast('Groups need 3+ people');
        return;
      }
      const gid = room()?.group_room_id;
      if (!gid){ toast('No group yet'); return; }
      state.chatTab = 'group';
      await openChatRoom(gid);
      goMobileScreen('chat');
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  const openRoomBtn = e.target.closest('[data-open-room]');
  if (openRoomBtn){
    try{
      await openRoom(openRoomBtn.dataset.openRoom);
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  const bgPick = e.target.closest('[data-chat-bg]');
  if (bgPick){ setChatBg(bgPick.dataset.chatBg); return; }
  if (e.target.closest('[data-chat-bg-pick]')){ $('#chat-bg-file')?.click(); return; }
  if (e.target.closest('[data-chat-profile]')){
    openChatSettings();
    return;
  }
  if (e.target.closest('[data-chat-back]')){
    state.chatView = 'list';
    state.chatRoom = null;
    state.chatPeerId = null;
    state.messages = [];
    if (msgChannel){ sb.removeChannel(msgChannel); msgChannel = null; }
    document.body.classList.remove('kb-open','chat-focus','chat-thread');
    document.documentElement.style.setProperty('--kb','0px');
    saveNav({ chatView: 'list', chatRoomId: null, chatPeerId: null, screen: 'chat' });
    renderAll();
    return;
  }
  if (e.target.closest('#group-create')){
    // Handled by bindTap — first tap must work on mobile
    return;
  }
  const memberMenu = e.target.closest('[data-member-menu]');
  if (memberMenu){
    openMemberMenu(memberMenu.dataset.memberMenu);
    return;
  }
  const makeAdmin = e.target.closest('[data-make-admin]');
  if (makeAdmin){
    try{
      if (!room()) return;
      const { error } = await sb.rpc('set_member_role', {
        p_room_id: room().id,
        p_user_id: makeAdmin.dataset.makeAdmin,
        p_role: 'admin'
      });
      if (error) throw error;
      state.memberRoles[makeAdmin.dataset.makeAdmin] = 'admin';
      toast('Admin added');
      closeSheets();
      renderAll();
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  const makeMember = e.target.closest('[data-make-member]');
  if (makeMember){
    try{
      if (!room()) return;
      const { error } = await sb.rpc('set_member_role', {
        p_room_id: room().id,
        p_user_id: makeMember.dataset.makeMember,
        p_role: 'member'
      });
      if (error) throw error;
      state.memberRoles[makeMember.dataset.makeMember] = 'member';
      toast('Admin removed');
      closeSheets();
      renderAll();
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('#btn-avatar-upload')){
    const rootEl = e.target.closest('#m-you, #view') || document;
    rootEl.querySelector('#avatar-file')?.click();
    return;
  }
  if (e.target.closest('#cookie-accept')){ acceptCookies(); return; }
  if (e.target.closest('#cookie-dismiss')){ dismissCookieBar(); return; }
  if (e.target.closest('#invite-copy-you')){
    await copyInviteLink(room()?.code);
    return;
  }
  if (e.target.closest('#invite-rotate')){
    await regenerateInviteCode(null);
    return;
  }
  if (e.target.closest('#invite-set-code')){
    await regenerateInviteCode(youEl('invite-custom-code')?.value || '');
    return;
  }
  const openToggle = e.target.closest('#room-open-toggle');
  if (openToggle){
    const on = !openToggle.classList.contains('on');
    openToggle.classList.toggle('on', on);
    openToggle.setAttribute('aria-checked', on ? 'true' : 'false');
    youEl('room-open-fields')?.classList.toggle('hidden', !on);
    if (!on) await saveRoomListing();
    return;
  }
  if (e.target.closest('#room-open-save')){ await saveRoomListing(); return; }
  const bcat = e.target.closest('[data-browse-cat]');
  if (bcat){ browseCat = bcat.dataset.browseCat || ''; renderBrowseCats(); await loadBrowseRooms(); return; }
  const breq = e.target.closest('[data-browse-request]');
  if (breq){ await requestJoinRoomById(breq.dataset.browseRequest, breq); return; }
  if (e.target.closest('#invite-copy')){
    const chat = activeChat();
    if (chat?.kind !== 'group'){ toast('Open group settings to copy the group link'); return; }
    await copyInviteLink(chat.code || groupInviteCode());
    return;
  }

  const archiveBtn = e.target.closest('[data-archive-room]');
  if (archiveBtn){
    const rid = archiveBtn.dataset.archiveRoom;
    const archived = archiveBtn.dataset.archived === '1';
    try{
      if (archived){
        const { error } = await sb.from('room_members').update({ archived_at: null }).eq('room_id', rid).eq('user_id', me().id);
        if (error) throw error;
      } else {
        const { error } = await sb.rpc('archive_room', { p_room_id: rid });
        if (error) throw error;
      }
      await loadRoomsList();
      if (state.room?.id === rid && !archived){
        state.chatView = 'list';
      }
      renderAll();
      toast(archived ? 'Unarchived' : 'Archived');
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const sticker = e.target.closest('[data-send-sticker]');
  if (sticker){
    const s = STICKERS.find(x => x.id === sticker.dataset.sendSticker);
    try{
      await insertMessage({ kind:'sticker', body: s.label, payload:{ sticker: s.id, label: s.label } });
      closeSheets();
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const moodBtn = e.target.closest('[data-send-mood]');
  if (moodBtn){
    const mood = moodBtn.dataset.sendMood;
    const meta = MOODS.find(x => x.id === mood);
    try{
      await sb.from('profiles').update({ mood }).eq('id', me().id);
      state.profile.mood = mood;
      await insertMessage({ kind:'mood', body: meta.label, payload:{ mood } });
      closeSheets();
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const taskBtn = e.target.closest('[data-send-task]');
  if (taskBtn){
    const g = state.goals.find(x => x.id === taskBtn.dataset.sendTask);
    if (!g) return;
    const nudge = !g.done && g.scope === 'day' && g.due_date === TODAY_ISO;
    try{
      await insertMessage({
        kind:'task_card',
        body: g.title,
        payload:{
          goal_id: g.id,
          title: g.title,
          owner_id: g.owner_id,
          done: g.done,
          scope: g.scope,
          due_date: g.due_date,
          nudge
        }
      });
      closeSheets();
      toast(nudge ? 'Nudge sent' : 'Task shared');
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const todoShare = e.target.closest('[data-send-todo]');
  if (todoShare){
    const t = (state.todos || []).find(x => x.id === todoShare.dataset.sendTodo);
    if (!t) return;
    try{
      await insertMessage({
        kind: 'task_card', body: t.title,
        payload: { todo_id: t.id, title: t.title, owner_id: t.by, done: t.done, day: todoDay(t) }
      });
      closeSheets();
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const cheerBtn = e.target.closest('[data-send-cheer]');
  if (cheerBtn){
    const g = state.goals.find(x => x.id === cheerBtn.dataset.sendCheer);
    if (!g) return;
    try{
      await insertMessage({
        kind:'cheer',
        body: g.title,
        payload:{ goal_id: g.id, goal_title: g.title, note: 'Proud of you' }
      });
      closeSheets();
      fireCheer();
      toast('Cheered');
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  if (e.target.closest('#poll-send')){
    const q = $('#poll-q').value.trim();
    const a = $('#poll-a').value.trim();
    const b = $('#poll-b').value.trim();
    if (!q || !a || !b){ toast('Add question and both options'); return; }
    try{
      await insertMessage({
        kind:'poll',
        body: q,
        payload:{
          question: q,
          options:[
            { id:'a', label:a, votes:[] },
            { id:'b', label:b, votes:[] }
          ]
        }
      });
      closeSheets();
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  const chancePlay = e.target.closest('[data-chance-play], [data-chance-open]');
  if (chancePlay){
    const mid = chancePlay.dataset.chancePlay || chancePlay.dataset.chanceOpen;
    const card = chancePlay.closest('[data-chance-game]');
    const gid = card?.dataset?.chanceGame || null;
    if (gid) state._chanceFocus = gid;
    openChanceOverlay(mid, gid);
    return;
  }
  const chanceRematch = e.target.closest('[data-chance-rematch]');
  if (chanceRematch){
    startChanceGame(chanceRematch.dataset.chanceRematch).catch(err => notify(errMsg(err)));
    return;
  }

  const vote = e.target.closest('[data-vote-poll]');
  if (vote){
    const mid = vote.dataset.votePoll;
    const oid = vote.dataset.option;
    const msg = state.messages.find(m => m.id === mid);
    const prev = msg ? JSON.parse(JSON.stringify(msg.payload || {})) : null;
    if (msg?.payload?.options && me()){
      msg.payload = {
        ...msg.payload,
        options: (msg.payload.options || []).map(o => ({
          ...o,
          votes: o.id === oid
            ? Array.from(new Set([...(o.votes||[]).filter(v => v !== me().id), me().id]))
            : (o.votes || []).filter(v => v !== me().id)
        }))
      };
      renderChatOnly();
    }
    try{
      const { data, error } = await sb.rpc('vote_poll', {
        p_message_id: mid,
        p_option_id: oid
      });
      if (error) throw error;
      const i = state.messages.findIndex(m => m.id === data.id);
      if (i >= 0) state.messages[i] = data;
      renderChatOnly();
    }catch(err){
      if (msg && prev){ msg.payload = prev; renderChatOnly(); }
      notify(errMsg(err));
    }
    return;
  }

  if (e.target.closest('#note-save')){
    try{
      const body = $('#note-body').value;
      const noteRoomId = activeChat()?.id || room()?.id;
      const { data, error } = await sb.from('shared_notes').update({
        body,
        updated_by: me().id,
        updated_at: new Date().toISOString()
      }).eq('room_id', noteRoomId).select().single();
      if (error) throw error;
      state.sharedNote = data;
      closeSheets();
      toast('Note saved');
    }catch(err){ notify(errMsg(err)); }
    return;
  }

  if (e.target.closest('#chat-theme-toggle')){
    await toggleTheme();
    openChatSettings();
    return;
  }

  const scopeBtn = e.target.closest('#in-scope button');
  if (scopeBtn){
    $$('#in-scope button').forEach(b=>b.classList.remove('is-active'));
    scopeBtn.classList.add('is-active');
    const year = scopeBtn.dataset.scope==='year';
    $('#date-field')?.classList.toggle('hidden', year);
    $('#duration-field')?.classList.toggle('hidden', year);
    $('#date-duration-row')?.classList.toggle('hidden', year);
    $('#time-duration-row')?.classList.toggle('hidden', year);
    $('#daypart-field')?.classList.toggle('hidden', year);
    $('#start-field')?.classList.toggle('hidden', year);
    return;
  }
  const daypartBtn = e.target.closest('#in-daypart button');
  if (daypartBtn){
    setDaypartUI(daypartBtn.dataset.daypart, { setStart: true });
    return;
  }
  const shareBtn = e.target.closest('#in-share-mode button');
  if (shareBtn && !shareBtn.disabled){
    $$('#in-share-mode button').forEach(b=>b.classList.remove('is-active'));
    shareBtn.classList.add('is-active');
    return;
  }
  const delCat = e.target.closest('[data-del-cat]');
  if (delCat){
    await deleteCat(delCat.dataset.delCat);
    return;
  }
  const editCat = e.target.closest('[data-edit-cat]');
  if (editCat){
    const cat = state.categories.find(c => c.id === editCat.dataset.editCat);
    if (cat) openCatSheet(cat);
    return;
  }
  const col = e.target.closest('[data-color]');
  if (col){
    pickedColor = col.dataset.color;
    $$('#color-row .color-dot').forEach(d=>d.classList.toggle('is-on', d.dataset.color===pickedColor));
    renderIconGrid($('#cat-icon-search')?.value || '');
    return;
  }
  const iconBtn = e.target.closest('[data-set-icon]');
  if (iconBtn){
    pickedIcon = pickedIcon === iconBtn.dataset.setIcon ? '' : iconBtn.dataset.setIcon; // tap again to clear
    $$('#cat-icon-grid .icon-opt').forEach(b => b.classList.toggle('is-on', b.dataset.setIcon === pickedIcon));
    return;
  }
  const catMenu = e.target.closest('[data-cat-menu]');
  if (catMenu){ openCatMenu(catMenu.dataset.catMenu); return; }
  if (e.target.closest('#btn-theme') || e.target.closest('#theme-switch')){ await toggleTheme(); return; }
  if (e.target.closest('#btn-room-avatar')){
    (e.target.closest('#m-you, #view') || document).querySelector('#room-avatar-file')?.click();
    return;
  }
  if (e.target.closest('#btn-signout')){
    try{ await sb.auth.signOut(); }catch(_){}
    return;
  }
  if (e.target.closest('#btn-leave')){
    await loadRoomsList();
    enterHome();
    toast('Back to rooms');
    return;
  }
  const kickRoom = e.target.closest('[data-kick-room]');
  if (kickRoom){
    try{
      if (!room()) return;
      const uid = kickRoom.dataset.kickRoom;
      const who = profileById(uid);
      if (!confirm(`Kick ${uname(who)} from this room?`)) return;
      const { error } = await sb.rpc('kick_member', { p_room_id: room().id, p_user_id: uid });
      if (error) throw error;
      state.members = state.members.filter(p => p.id !== uid);
      delete state.memberRoles[uid];
      closeSheets();
      renderAll();
      toast('Removed from room');
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  const kickGroup = e.target.closest('[data-kick-group]');
  if (kickGroup){
    try{
      // Prefer space id so room owner/admin role always applies
      const spaceId = room()?.id;
      const gid = room()?.group_room_id || (activeChat()?.kind === 'group' ? activeChat().id : null);
      const targetRoom = spaceId || gid;
      if (!targetRoom){ toast('No group'); return; }
      const uid = kickGroup.dataset.kickGroup;
      const who = profileById(uid);
      if (!confirm(`Kick ${uname(who)} from this room?`)) return;
      const { error } = await sb.rpc('kick_member', { p_room_id: targetRoom, p_user_id: uid });
      if (error) throw error;
      state.members = state.members.filter(p => p.id !== uid);
      delete state.memberRoles[uid];
      closeSheets();
      toast('Removed from room');
      renderAll();
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('#btn-rename-room')){
    try{
      const rootEl = e.target.closest('#m-you, #view') || document;
      const title = (rootEl.querySelector('#room-rename-input')?.value || '').trim();
      if (!title){ toast('Enter a name'); return; }
      const { data, error } = await sb.rpc('rename_room', { p_room_id: room().id, p_title: title });
      if (error) throw error;
      state.room = { ...state.room, ...data };
      await loadRoomsList();
      renderAll();
      toast('Room renamed');
    }catch(err){ notify(errMsg(err)); }
    return;
  }
  if (e.target.closest('#btn-group-avatar')){
    $('#group-avatar-file')?.click();
    return;
  }
  if (e.target.id === 'avatar-file' || e.target.closest('#avatar-file')){
    return;
  }
  if (e.target.closest('#open-you')){
    openPrivateProfile();
    renderAll();
    return;
  }
});

document.addEventListener('input', e => {
  if (e.target.id === 'cat-icon-search') renderIconGrid(e.target.value);
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape'){
    if (document.body.classList.contains('drawer-open')){ closeProfileDrawer(); return; }
    closeSheets();
  }
  if (e.key === 'Enter' && e.target.id === 'in-subgoal'){
    e.preventDefault();
    $('#sheet-sub-add')?.click();
    return;
  }
  if (e.key === 'Enter' && e.target.id === 'in-title'){ e.preventDefault(); saveGoal(false); }
  if (e.key === 'Enter' && e.target.id === 'ms-name'){ e.preventDefault(); saveMilestoneFromSheet(); }
  if (e.key === 'Enter' && e.target.id === 'ms-item-in'){
    e.preventDefault();
    const val = e.target.value; e.target.value = '';
    if (val.trim() && state.msBoardId) addItem(state.msBoardId, val);
  }
  if (e.key === 'Enter' && e.target.matches?.('[data-sg-add]')){
    e.preventDefault();
    const pid = e.target.dataset.sgAdd; const val = e.target.value; e.target.value = '';
    if (val.trim()) addSubgoal(pid, val);
  }
  if (e.key === 'Enter' && e.target.id === 'routine-step-in'){ e.preventDefault(); addRoutineStepFromSheet(); return; }
  if (e.key === 'Enter' && e.target.id === 'routine-name'){ e.preventDefault(); $('#routine-step-in')?.focus(); }
  if (e.key === 'Enter' && (e.target.id === 'auth-user' || e.target.id === 'auth-pass')) $('#auth-submit').click();
});

sb.auth.onAuthStateChange(async (event, session) => {
  if (event === 'SIGNED_OUT'){
    state.user = null; state.profile = null; state.room = null; state.rooms = [];
    clearAuthCookie();
    authPanel = 'welcome';
    showGate('auth');
    showAuthPanel('welcome');
  } else if (event === 'TOKEN_REFRESHED' && session){
    state.user = session.user;
  }
});

captureInvite();
resetSpaceMeta();
authPanel = 'welcome';
authMode = 'login';
showAuthPanel('welcome');
applyTheme();
try{
  const mq = window.matchMedia('(prefers-color-scheme: dark)');
  const onScheme = () => { if (getThemeMoodPref() === 'system') applyTheme(); };
  if (mq.addEventListener) mq.addEventListener('change', onScheme);
  else if (mq.addListener) mq.addListener(onScheme);
}catch(_){}
showCookieBar();
updateChatBadge();
document.addEventListener('pointerdown', unlockAudio, { once: true });
setTimeout(hideBoot, 2200); // safety: never get stuck on the splash
document.addEventListener('change', e => {
  if (e.target?.id === 'in-start'){
    syncDaypartFromStart();
    return;
  }
  if (e.target?.id === 'routine-start'){
    syncRoutineDaypartLabel();
    return;
  }
  if (e.target?.id === 'in-duration'){
    syncGoalEndLabel();
  }
});
document.addEventListener('input', e => {
  if (e.target?.id === 'in-start'){
    syncDaypartFromStart();
  }
  if (e.target?.id === 'routine-start'){
    syncRoutineDaypartLabel();
  }
});

/* Capture phase so the flag is set before the handler that triggers the
   re-render — pills and the week pill only animate in response to a tap. */
document.addEventListener('click', e => {
  const inWeek = !!e.target.closest?.('.wk-strip, [data-today-focus]');
  if (!inWeek && !e.target.closest?.('.status-seg, .chat-tabs, .seg')) return;
  state._segAnimate = true;
  state._wkAnimate = inWeek;
}, true);
document.addEventListener('click', e => {
  if (!e.target.closest?.('.status-seg, .chat-tabs, .seg, .wk-strip, [data-today-focus]')) return;
  // Covers sheets, which toggle classes in place instead of re-rendering.
  requestAnimationFrame(() => {
    positionSegIndicators({ animate: true });
    positionWeekSlider({ animate: true });
  });
});
let _deskBp = typeof window !== 'undefined' && window.matchMedia('(min-width:901px)').matches;
window.addEventListener('resize', () => {
  positionSegIndicators();
  positionWeekSlider();
  const desk = window.matchMedia('(min-width:901px)').matches;
  if (desk !== _deskBp){
    _deskBp = desk;
    renderAll();
  }
});

/* ── Catching up after being away ────────────────────────────────────────
   A phone suspends the realtime socket the moment the app is in the background,
   and anything that happened while it was asleep is NOT replayed when it wakes —
   Supabase only streams live events. Nothing here used to catch up, so a move
   your partner made while you were away just never arrived until something else
   happened to reload that chat. Now, every time the app comes back, it re-opens
   the live channels and re-reads what it might have missed. */
let resyncBusy = false, resyncAt = 0;
async function resyncLive(reason){
  if (!me() || resyncBusy) return;
  if (Date.now() - resyncAt < 4000) return;         // focus + visibility fire together
  resyncBusy = true; resyncAt = Date.now();
  try{
    subscribeInbox();
    if (activeChat()) subscribeMessages();
    if (room()) subscribeMilestones();
    const tasks = [loadChatPreviews().catch(() => {}), loadSpaceMeta().catch(() => {}), loadWallet().catch(() => {})];
    const chat = activeChat();
    if (chat && state.chatView === 'thread') tasks.push(loadChatMessages(chat.id).catch(() => {}));
    // a game that is open on screen reads from the caches, so refresh its room too
    const gid = state._gameFocus;
    const gmsg = gid && latestGameMsg(gid);
    if (gmsg?.room_id && gmsg.room_id !== chat?.id) tasks.push(refreshRoomCache(gmsg.room_id));
    await Promise.all(tasks);
    renderAll();
    if ($('#game-overlay')?.classList.contains('on')) renderGameOverlay();
    pumpAlerts();
  }catch(_){}
  finally{ resyncBusy = false; }
}
async function refreshRoomCache(roomId){
  try{
    const { data } = await sb.from('messages').select('*').eq('room_id', roomId)
      .order('created_at', { ascending: false }).limit(120);
    if (!data) return;
    state.msgCacheByRoom = state.msgCacheByRoom || {};
    state.msgCacheByRoom[roomId] = data.slice().reverse();
  }catch(_){}
}
window.addEventListener('online', () => resyncLive('online'));
window.addEventListener('focus', () => resyncLive('focus'));

document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible'){
    resyncLive('visible');
    pollTelegramLinkOnce();
    if (dayStateChanged()) renderAll();
    // rAF is paused while hidden, so indicators can be left unpositioned.
    positionSegIndicators();
    positionWeekSlider();
  }
});
// The app can sit open across midnight; visibilitychange alone never fires then.
setInterval(() => { if (dayStateChanged()) renderAll(); }, 60000);
window.addEventListener('pageshow', () => {
  resyncLive('pageshow');
  pollTelegramLinkOnce();
  if (dayStateChanged()) renderAll();
});

/* Hold + swipe down on an open To do card: peel the stack to reveal done tasks underneath. */
const _todayPull = { y: 0, active: false, front: null, stack: null, pulling: false };
document.addEventListener('touchstart', e => {
  if ((state.todayFilter || 'todo') !== 'todo') return;
  if (e.target.closest?.('.tcheck, [data-toggle], [data-routine-tick], [data-goal-info], [data-routine-edit], [data-goal-expand]')) return;
  const card = e.target.closest?.('.today-pull-front .tcard, .today-pull-front .tcard-wrap');
  const front = e.target.closest?.('[data-today-pull-front]');
  const stack = e.target.closest?.('[data-today-pull]');
  if (!card || !front || !stack || !stack.querySelector('[data-today-pull-done]')) return;
  _todayPull.y = e.touches[0]?.clientY ?? 0;
  _todayPull.front = front;
  _todayPull.stack = stack;
  _todayPull.active = true;
  _todayPull.pulling = false;
}, { passive: true });
document.addEventListener('touchmove', e => {
  if (!_todayPull.active || !_todayPull.front) return;
  const y = e.touches[0]?.clientY ?? _todayPull.y;
  let dy = y - _todayPull.y;
  if (state.todayShowDone) dy = Math.min(0, dy); // swipe up to hide
  else dy = Math.max(0, dy); // swipe down to reveal
  if (Math.abs(dy) < 8) return;
  _todayPull.pulling = true;
  const capped = Math.max(-120, Math.min(140, dy));
  _todayPull.stack.classList.add('is-pulling');
  _todayPull.front.style.transform = `translateY(${capped}px)`;
  const done = _todayPull.stack.querySelector('[data-today-pull-done]');
  if (done && !state.todayShowDone){
    const pct = Math.min(1, Math.max(0, capped / 90));
    done.style.maxHeight = `${Math.round(pct * 420)}px`;
    done.style.opacity = String(0.35 + pct * 0.65);
  }
}, { passive: true });
document.addEventListener('touchend', () => {
  if (!_todayPull.active) return;
  const front = _todayPull.front;
  const stack = _todayPull.stack;
  const pulling = _todayPull.pulling;
  const dy = (() => {
    const t = front?.style.transform || '';
    const m = /translateY\((-?\d+(?:\.\d+)?)px\)/.exec(t);
    return m ? Number(m[1]) : 0;
  })();
  _todayPull.active = false;
  _todayPull.pulling = false;
  _todayPull.front = null;
  _todayPull.stack = null;
  if (!front || !stack) return;
  front.style.transform = '';
  stack.classList.remove('is-pulling');
  const done = stack.querySelector('[data-today-pull-done]');
  if (done){ done.style.maxHeight = ''; done.style.opacity = ''; }
  if (!pulling) return;
  if (!state.todayShowDone && dy > 64){
    state.todayShowDone = true;
    renderAll();
  } else if (state.todayShowDone && dy < -48){
    state.todayShowDone = false;
    renderAll();
  }
}, { passive: true });

route();
